const a = (no, chapter, text) => ({ no, chapter, text });
export const ARTICLES = [
  a(1,'ch1','為促進都市計畫地區及指定地區下水道之建設與管理，以保護水域水質，特制定本法；本法未規定者適用其他法律。'),
  a(2,'ch1','本法用辭定義如左：\n一、下水：指排水區域內之雨水、家庭污水及事業廢水。\n二、下水道：指為處理下水而設之公共及專用下水道。\n三、公共下水道：指供公共使用之下水道。\n四、專用下水道：指供特定地區或場所使用而設置尚未納入公共下水道之下水道。\n五、下水道用戶：指依本法及下水道管理規章接用下水道者。\n六、用戶排水設備：指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備。\n七、排水區域：指下水道依其計畫排除下水之地區。'),
  a(3,'ch1','本法所稱主管機關︰在中央為內政部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。'),
  a(4,'ch1','中央主管機關辦理左列事項︰\n一、下水道發展政策、方案之訂定。\n二、下水道法規之訂定及審核。\n三、直轄市、縣（市）下水道系統發展計畫之核定。\n四、直轄市、縣（市）下水道建設、管理與研究發展之監督及輔導。\n五、下水道操作、維護人員之技能檢定及訓練。\n六、下水道技術之研究發展。\n七、跨越直轄市與縣（市）或二縣（市）以上下水道規劃、建設及管理之協調。\n八、其他有關全國性下水道事宜。\n前項各款事項涉及環保及水利者，應會同中央環保及水利主管機關辦理之。'),
  a(5,'ch1','直轄市主管機關辦理左列事項︰\n一、直轄市下水道建設之規劃及實施。\n二、直轄市下水道法規之訂定。\n三、直轄市下水道技術之研究發展。\n四、直轄市屬下水道之管理。\n五、直轄市下水道操作、維護人員之訓練。\n六、其他有關直轄市下水道事宜。'),
  a(6,'ch1','縣主管機關辦理左列事項：\n一、縣下水道建設之規劃及實施。\n二、縣下水道單行規章之訂定。\n三、縣屬下水道之管理。\n四、鄉（鎮、市）下水道建設與管理之監督及輔導。\n五、其他有關縣下水道事宜。\n省轄市下水道，由省轄市主管機關準用前項第一款至第三款及第五款之規定辦理。'),
  a(7,'ch1','公共下水道，由地方政府或鄉（鎮、市）公所建設及管理。但必要時，主管機關得指定有關之公營事業機構建設、管理之。'),
  a(8,'ch1','政府機關或公營事業機構新開發社區、工業區或經直轄市、縣（市）主管機關指定之地區或場所，應設置專用下水道，由各該開發之機關或機構建設、管理之。\n私人新開發社區、工業區或經直轄市、縣（市）主管機關指定之地區或場所，應設置專用下水道。但必要時，得由當地政府、鄉（鎮、市）公所或指定有關之公營事業機構建設、管理之。其建設費依建築基地及樓地板面積計算分擔之。\n前項應分擔之建設費於申請核發建造執照時，向各該建築物起造人徵收之。建設費徵收辦法，由中央主管機關定之。'),
  a(9,'ch1','中央、直轄市及縣（市）主管機關，為建設及管理下水道，應指定或設置下水道機構，負責辦理下水道之建設及管理事項。'),
  a(10,'ch2','下水道工程設施標準，由中央主管機關定之。'),
  a(11,'ch2','直轄市、縣（市）主管機關，應視實際需要，配合區域排水系統，訂定區域性下水道計畫，報請中央主管機關核定後，循法定程序納入都市計畫或區域計畫實施。'),
  a(12,'ch2','下水道工程之施工，應與其他有關公共設施同時規劃並配合進行。'),
  a(13,'ch2','下水道機構因工程上之必要，得洽商有關主管機關使用河川、溝渠、橋樑、涵洞、堤防、道路、公園、綠地等。但以不妨礙原有效用為限。'),
  a(14,'ch2','下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。\n因埋設前項管渠或其他設備，致其土地所有權人無法附建防空避難設備或法定停車場時，經當地主管建築機關勘查屬實者，得就該埋設管渠或其他設備直接影響部分，免予附建防空避難設備或法定停車場。'),
  a(15,'ch2','下水道機構因管渠或有關設備之規劃、設計與施工而須將其他地下設施為必要之處置時，應事先與有關機關取得協議。協議不成，應報請主管機關會商有關機關決定之。'),
  a(16,'ch2','下水道機構因勘查、測量、施工或維護下水道，臨時使用公、私土地時，土地所有人、占有人或使用人不得拒絕。但提供使用之土地因而遭受損害時，應予補償。如對補償有異議時，應報請中央主管機關核定後為之。'),
  a(17,'ch2','下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理。其由政府機關自行規劃、設計及監造者，應由符合中央主管機關規定之技術人員擔任之。'),
  a(18,'ch2','下水道設施之操作、維護，應由技能檢定合格人員擔任之。其技能檢定辦法，由中央主管機關定之。'),
  a(19,'ch3','下水道機構，應於下水道開始使用前，將排水區域、開始使用日期、接用程序及下水道管理規章公告週知。\n下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道之內。'),
  a(20,'ch3','用戶排水設備之管理、維護，由下水道用戶自行負責。'),
  a(21,'ch3','用戶排水設備，應由登記合格之下水道用戶排水設備承裝商或自來水管承裝商承裝。承裝商僱用之技工，應經技能檢定合格，並經中央主管機關訓練合格。\n前項下水道用戶排水設備承裝商管理規則，由中央主管機關定之。'),
  a(22,'ch3','用戶排水設備須經下水道機構檢驗合格，始得聯接於下水道。其檢驗不合格者，下水道機構應限期責令改善。\n用戶排水設備之標準，由中央主管機關定之。'),
  a(23,'ch3','下水道用戶非使用他人之排水設備不能排洩下水者，應申請下水道機構核准，始得聯接使用，並應按受益程度分擔其設置、使用及維護費用。\n前項用戶排水設備如需擴充、改良始得聯接使用者，其擴充、改良費用，由申請聯接之用戶負擔。'),
  a(24,'ch3','下水道機構，得派員攜帶證明文件檢查用戶排水設備、測定流量、檢驗水質。'),
  a(25,'ch3','下水道可容納排入之下水水質標準，由下水道機構擬訂，報請直轄市、縣（市）主管機關核定後公告之。\n下水道用戶排洩下水，超過前項規定標準者，下水道機構應限期責令改善；其情節重大者，得通知停止使用。'),
  a(26,'ch4','用戶使用下水道，應繳納使用費；其計收方式如左︰\n一、按下水道用戶使用自來水及其他用水之用量比例計收。\n二、按下水道用戶排放之下水水質及水量計收。\n三、其他經主管機關核定之方式。\n前項使用費計算公式及徵收辦法，由直轄市、縣（市）主管機關擬訂，報請中央主管機關核定之。'),
  a(27,'ch4','下水道用戶不依規定繳納下水道使用費者，得自繳納期限屆滿之次日起，每逾三日加徵應納使用費額百分之一滯納金；逾期一個月經催告而仍不繳納者，得移送法院裁定後強制執行。'),
  a(28,'ch5','下水道排放之放流水，超過水污染防治主管機關規定之放流水標準者，下水道機構應即改善。'),
  a(29,'ch5','主管機關對於未依規定期限，設置用戶排水設備並完成與下水道聯接使用者，除依第三十二條規定處罰外，並得命下水道機構代為辦理，所需費用由下水道用戶負擔。\n前項下水道用戶，應負擔之費用，經催告逾期不繳納者，得移送法院裁定後強制執行。'),
  a(30,'ch5','直轄市、縣（市）主管機關，應定期檢查下水道機構各項設施、放流水水質、器材、財務與有關資料及紀錄。'),
  a(31,'ch6','毀損下水道主要設備或以其他行為使下水道不堪使用或發生危險者，處六月以上五年以下有期徒刑，得併科五千元以上五萬元以下罰金。'),
  a(32,'ch6','下水道用戶有下列情事之一者，處新臺幣一萬元以上十萬元以下罰鍰：\n一、不依規定期限將下水排洩於下水道者。\n二、違反第二十二條規定，未經檢驗合格而聯接使用，或經檢驗不合格而不依限期改善者。\n三、拒絕下水道機構依第二十四條規定之檢查或檢驗者。\n四、違反第二十五條第二項規定，未能於限期內改善者。\n工廠、礦場或經水污染防治法之中央主管機關指定之事業，經依前項第四款規定處罰三次而仍未能改善者，直轄市、縣（市）主管機關得通知停止使用或報請其目的事業主管機關予以停業處分。'),
  a(33,'ch6','本法所定之罰鍰，由主管機關處罰；經通知而逾期不繳納者，得移送法院強制執行。'),
  a(34,'ch7','本法施行細則，由中央主管機關定之。'),
  a(35,'ch7','本法自公布日施行。'),
];

// 施行細則：民國96年06月05日修正版（來源：使用者提供之「下水道法施行細則」PDF）
export const RULES = [{"no":1,"text":"本細則依下水道法（以下簡稱本法）第三十四條規定訂定之。"},{"no":2,"text":"本法第一條所稱指定地區，指都市計畫地區以外之左列地區：\n一、水污染管制區。\n二、自來水水源之水質水量保護區域。\n三、工業區。\n四、其他經主管機關指定之地區。"},{"no":3,"text":"本法所稱下水道分為左列三種：\n一、雨水下水道：專供處理雨水之下水道。\n二、污水下水道：專供處理家庭污水及事業廢水之下水道。\n三、合流下水道：供處理雨水、家庭污水及事業廢水之下水道。"},{"no":4,"text":"本法第八條所稱新開發社區、工業區，係指符合下列條件之地區，其申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者：\n一、新開發社區：可容納五百人以上居住或總計興建一百住戶以上之社區。\n二、新開發工業區：\n（一）政府機關、公民營事業機構開發供事業設廠之地區。\n（二）事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者。\n前項第一款之新開發社區，其人口計算基準如左：\n一、實施都市計畫地區：以建築物污水處理設施設計技術規範所定使用人數方式計算。\n二、實施都市計畫以外地區：以每人使用三十平方公尺之樓地板面積計算。"},{"no":5,"text":"依本法第八條規定應設置專用下水道之地區或場所，於設置專用下水道前，應檢附專用下水道規劃及設計圖說等資料，申請該管主管機關核准，始得施工；完工後，須經下水道主管機關查驗合格，始得使用。\n在前項地區或場所內興建建築物，應於專用下水道完工經查驗合格後，始得核發使用執照。"},{"no":6,"text":"下水道設施用地在都市計畫範圍內者，下水道機構得洽請都市計畫主管機關依都市計畫法之規定設置下水道設施用地。"},{"no":7,"text":"依本法第十四條規定使用公、私有土地時，下水道機構應於工程計畫訂定後，以書面通知土地所有人、占有人或使用人。\n前項通知書應記載左列事項：\n一、預定開工日期。\n二、施工範圍。\n三、埋設物之尺寸及構造。\n四、施工方法。\n五、施工期間。\n六、償金。\n七、償金支付日期及領取償金時所應提示之證件。"},{"no":8,"text":"依本法第十六條規定臨時使用公、私有土地時，下水道機構應以書面通知土地所有人、占有人或使用人，如情況急迫，得先行施工，補行通知。"},{"no":9,"text":"土地所有人、占有人或使用人依本法第十四條第一項但書或第十六條但書提出異議者，應於前二條之通知到達後三十日內，以書面向下水道機構為之，逾期不予受理。"},{"no":10,"text":"本法第十四條、第十六條規定支付之償金或補償，其標準由直轄市、縣（市）主管機關訂定之。"},{"no":11,"text":"在公、私有土地內既有之下水道管渠或其他設施，非經主管機關核准，土地所有人、占有人或使用人不得變更。"},{"no":12,"text":"（刪除）"},{"no":13,"text":"本法第十七條所稱專業技師，指依技師法規定取得環境（衛生）工程、土木或水利科之工業技師。"},{"no":14,"text":"下水道系統設施完成後，下水道機構應將左列資料登錄建檔保管：\n一、下水道排水區域圖。\n二、管線系統分布平面圖。\n三、管線縱橫斷面圖（包括管材、管徑、埋設位置、高度、坡度、長度流量等）。\n四、處理設施及抽水設施平面圖、水位關係圖、構造圖等。\n五、放流口位置及設計圖。\n六、放流水之水量及水質分析資料。\n七、開工、竣工日期。\n八、其他有關操作、維護、管理應行登錄記載事項。"},{"no":15,"text":"下水道完成地區申請建築時，應先檢附用戶排水設備圖說、配置圖、排水口地點等資料申請下水道機構核准；用戶排水設備完工後，須經下水道機構檢驗合格，始得聯接於下水道。"},{"no":16,"text":"雨水及污水下水道分流地區，雨水不得排洩於污水下水道，家庭污水及事業廢水不得排洩於雨水下水道。"},{"no":17,"text":"下水道可使用之地區，其用戶應於依本法第十九條第一項所定公告開始使用之日起六個月內與下水道完成聯接使用。"},{"no":17.1,"label":"17-1","text":"（刪除）"},{"no":18,"text":"五層以下非供公眾使用之新建建築物，其下水道設備得由該建築物之建築師併同設計之。"},{"no":19,"text":"本法第三十一條所稱下水道主要設備如左：\n一、下水道系統管渠、放流口及其附屬設施。\n二、下水道抽水站設施及其相關設備。\n三、下水道處理廠設施及其相關設備。\n四、其他有關下水道重要設施。"},{"no":20,"text":"本細則自發布日施行。"}];
export const RULINGS = [{"id":"r1","agency":"內政部","date":"96.3.7","docNo":"台內營字第0960801006號","y":96,"src":"2018彙編","brief":"下水道法第1條規定之立法宗旨為「為促進都市計畫地區及指定地區下水道之建設與管理」，故其適用範圍應以「都市計畫地區」及…","text":"一、下水道法第1條規定之立法宗旨為「為促進都市計畫地區及指定地區下水道之建設與管理」，故其適用範圍應以「都市計畫地區」及「指定地區」為限，先予說明。\n二、下水道法施行細則第2條稱「指定地區」為水污染管制區、自來水水源之水質水量保護區域、工業區、其他經主管機關指定之地區。前述「其他經主管機關指定之地區」係授權主管機關得視當地環境特性及環境保護需要，指定已有下水道需要之地區為下水道應建設管理地區。來函所稱達一定規模，如係指下水道法第8條及施行細則第4條規定應建設專用污水下水道之規模者，主管機關得本諸權責，予以指定為應設置專用污水下水道之地區。本案所詢是否應設置專用污水下水道，請應依上開規定辦理。","refs":["A1","R2"]},{"id":"r2","agency":"內政部","date":"96.8.17","docNo":"台內營字第0960805113號","y":96,"src":"2018彙編","brief":"下水道法第1條規定之立法宗旨為「為促進都市計畫地區及指定地區下水道之建設與管理」，故其適用範圍應以「都市計畫地區」及…","text":"一、下水道法第1條規定之立法宗旨為「為促進都市計畫地區及指定地區下水道之建設與管理」，故其適用範圍應以「都市計畫地區」及「指定地區」為限，先予說明。\n二、下水道法施行細則第2條稱「指定地區」為水污染管制區、自來水水源之水質水量保護區域、工業區、其他經主管機關指定之地區。前述「其他經主管機關指定之地區」係授權主管機關得視當地環境特性及環境保護需要，指定已有下水道需要之地區為下水道應建設管理地區。來函所稱達一定規模，如係指下水道法第8條及施行細則第4條規定應建設專用污水下水道之規模者，主管機關得本諸權責，予以指定為應設置專用污水下水道之地區。本案所詢是否應設置專用污水下水道，請應依上開規定辦理。","refs":["A1","R2"]},{"id":"r3","agency":"內政部","date":"91.2.6","docNo":"台內營字第0960807941號","y":91,"src":"2018彙編","brief":"下水道法第2條第1款定義，下水為排水區域內之雨水、家庭污水及事業廢水，第2款稱「下水道」為處理下水而設之公共及專用下水道","text":"下水道法第2條第1款定義，下水為排水區域內之雨水、家庭污水及事業廢水，第2款稱「下水道」為處理下水而設之公共及專用下水道。故新開發社區、工業區或經主管機關指定之地區或場所設置專用下水道，自涵蓋雨水及污水下水道。","refs":["A2"]},{"id":"r4","agency":"內政部營建署","date":"95.2.15","docNo":"營署工程字第0950006763號","y":95,"src":"2018彙編","brief":"下水道法第2條第2款稱「下水道」為處理下水而設之公共及專用下水道，第4款稱「專用下水道」為供特定地區或場所使用而設置…","text":"下水道法第2條第2款稱「下水道」為處理下水而設之公共及專用下水道，第4款稱「專用下水道」為供特定地區或場所使用而設置尚未納入公共下水道之下水道。同法第8條第2項規定私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。本案楠梓加工出口區所設污水下水道管線及揚水加壓站為收集區內部分事業產生廢污水，經攔污、沉澱、消毒後放流，仍應視為污水下水道之一環。","refs":["A2"]},{"id":"r5","agency":"內政部","date":"96.12.6","docNo":"台內營字第0960807941號","y":96,"src":"2018彙編","brief":"下水道法第2條第1款定義，下水為排水區域內之雨水、家庭污水及事業廢水，第2款稱「下水道」為處理下水而設之公共及專用下水道","text":"下水道法第2條第1款定義，下水為排水區域內之雨水、家庭污水及事業廢水，第2款稱「下水道」為處理下水而設之公共及專用下水道。故新開發社區、工業區或經主管機關指定之地區或場所設置專用下水道，自涵蓋雨水及污水下水道。","refs":["A2","A8"]},{"id":"r6","agency":"內政部","date":"97.1.24","docNo":"內授營工程字第0970800488號","y":97,"src":"2018彙編","brief":"按建築法第96條之1及違章建築處理辦法第13條規定：「依本法規定強制拆除之建築物均不予補償，其拆除費用由建築物所有人負擔","text":"一、按建築法第96條之1及違章建築處理辦法第13條規定：「依本法規定強制拆除之建築物均不予補償，其拆除費用由建築物所有人負擔。前項建築物內存放之物品，主管機關應公告或以書面通知所有人、使用人或管理人自行遷移，逾期不遷移者，視同廢棄物處理。」、「直轄市、縣（市）政府拆除違章建築所需經費，應按預算程序編列預算支應」。至　貴府所陳為辦理污水下水道用戶接管工程，是否得辦理違章建築物相關救濟金之申請受理與發放及所需經費是否得申請上級機關補助等事宜乙節，無涉建築相關法令之規定。\n二、查依下水道法相關規定並無　貴府所稱之「用戶接管」，恐係「下水道用戶排水設備」之誤，合先說明。又查下水道法第2條第6款稱該設備為下水道用戶因接用下水道以排洩下水所設之管渠及有關設備，同法施行細則第17條規定，用戶應於下水道公告開始使用之日起6個月內與下水道完成聯接使用，故用戶排水設備係下水道用戶依規定自行接用公共污水下水道排洩污水之私有設備，應由下水道用戶自行施作，惟政府為加速提升下水道用戶接管普及率，現階段由政府以公務預算代為施作，如需使用私人土地，尚無所稱救濟金之申請受理、發放或補助等問題。","refs":["A2"]},{"id":"r7","agency":"內政部","date":"99.11.11","docNo":"內授營工程字第0990809655號","y":99,"src":"2018彙編","brief":"查下水道法第2條第6款稱「用戶排水設備」指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備","text":"查下水道法第2條第6款稱「用戶排水設備」指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備；該法第20條復稱，用戶排水設備之管理、維護，由下水道用戶自行負責。旨揭所詢巷道連接管及用戶接管工程事宜，皆屬前稱用戶排水設備，爰請依本部91年2月5日內授營工程字第0910002811號函(諒達)辦理。","refs":["A2","A14","A20"]},{"id":"r8","agency":"內政部","date":"99.11.23","docNo":"內授營工程字第0990233416號","y":99,"src":"2018彙編","brief":"查下水道法第14條規定意旨為供公共使用之污水管線經公、私有土地，自應給予補償","text":"查下水道法第14條規定意旨為供公共使用之污水管線經公、私有土地，自應給予補償。同法第2條第6款稱「用戶排水設備」，指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備；該法第20條復稱，用戶排水設備之管理、維護，由下水道用戶自行負責。旨揭所詢事宜，請依本部91年2月5日內授營工程字第0910002811號函及本部營建署94年2月14日營署工程字第0942902317號函辦理。\n至本部97年4月23日內授營工程字第0970803309號函所稱供公共使用之必要管渠，其性質屬公共下水道範疇，自得支付償金以為補償，與本部91年函釋尚無牴觸。","refs":["A2","A14","A20"]},{"id":"r9","agency":"內政部","date":"102.11.26","docNo":"內授營工程字第1020812298號","y":102,"src":"2018彙編","brief":"下水道法第14條意旨下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受…","text":"下水道法第14條意旨下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償；其有異議，方由中央主管機構核定。另查該法第20條規定，用戶排水設備之管理、維護，由下水道用戶自行負責，爰用戶排水設備屬用戶接用下水道之私有設備，尚無前開核定之適用。","refs":["A2","A20"]},{"id":"r10","agency":"內政部","date":"103.4.10","docNo":"內授營工程字第1030134772號","y":103,"src":"2018彙編","brief":"下水道法第14條意旨下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受…","text":"下水道法第14條意旨下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償；其有異議，方由中央主管機構核定。另查該法第20條規定，用戶排水設備之管理、維護，由下水道用戶自行負責，爰用戶排水設備屬用戶接用下水道之私有設備，尚無前開核定之適用。惟依據貴局103年3月19日高市水污二字第10331696600號函稱穿越旨揭土地係施作巷道連通管，本案補償範圍究係屬供「公共使用」之管渠或其他設備或用戶排水設備，請貴局補充說明。","refs":["A2","A20"]},{"id":"r11","agency":"內政部","date":"103.5.23","docNo":"內授營工程字第1030170067號","y":103,"src":"2018彙編","brief":"依據下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"一、依據下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。按上開函稱，貴局於旨揭土地行使下水道法第14條第1項所為供公共使用管線部分之埋設，擬支付償金數額，係依據高雄市政府所定「高雄市下水道工程使用土地支付償金及補助費標準」規定計算之，尚屬依法有據，爰有關償金計算，本部核依前開規定辦理。\n二、至有關償金對象乙節，查下水道法施行細則第7條規定意旨，下水道機構應於預定開工前，以書面通知土地所有人、占有人或使用人有關支付償金相關事宜。本案貴局所為事項之行使，是否符合前開規定，應本諸權責釐清後妥處。","refs":["A2","R7"]},{"id":"r12","agency":"內政部","date":"103.6.16","docNo":"營署工程字第1030037054號","y":103,"src":"2018彙編","brief":"查下水道法第2條第6款規定，用戶排水設備指下水道用戶因接用下水道以排洩下水所設之管渠及其有關設備","text":"查下水道法第2條第6款規定，用戶排水設備指下水道用戶因接用下水道以排洩下水所設之管渠及其有關設備。旨揭所詢，併請參酌本署93年9月23日營署工程字第0930060230號函示內容。","refs":["A2"]},{"id":"r13","agency":"內政部","date":"106.12.14","docNo":"營署水字第1061148659號","y":106,"src":"2018彙編","brief":"下水道法中並無用戶下水道之定義，公共下水道、排水區域及用戶排水設備於下水道法第2條中已有明定，依據下水道法第5條第1…","text":"下水道法中並無用戶下水道之定義，公共下水道、排水區域及用戶排水設備於下水道法第2條中已有明定，依據下水道法第5條第1項第4款及地方制度法第18條第1項第6款第4目規定，直轄市下水道建設及管理屬地方自治事項，本案請洽當地下水道主管機關衡酌實際情形後認定之。","refs":["A2","A5"]},{"id":"r14","agency":"內政部","date":"107.1.10","docNo":"內授營環字第1070800533號","y":107,"src":"2018彙編","brief":"下水道法地2條第1項第2、6款規定，下水道指為處理下水而設之公共及專用下水道，用戶排水設備指下水道用戶因接用下水道以…","text":"一、下水道法地2條第1項第2、6款規定，下水道指為處理下水而設之公共及專用下水道，用戶排水設備指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備。另依本部營建署93年9月23日營署工程字第0930060230號函略以「建築物內之給排水設備屬建築物範疇，由建築師依據建築技術規則設計，為便於公共下水道之接管作業，應將雨、污水分流設置。建築物外，連接下水道之下水道管材、陰井、人孔及銜接建築物之污水管線之用戶排水設備，均屬下水道範疇……」，故雨、污水下水道及有關之用戶排水設備均屬下水道範疇，合先敘明。\n二、依據下水道法第5條第1項第2、4款規定，直轄市主管機關辦理直轄市下水道法規之訂定及管理，另依據地方制度法第18條第1項第6款第4目規定，下水道建設及管理為直轄市自治事項，貴府所制定臺北市下水道管理自治條例經行政院交議由本部會同各有關機關審查後核定，尚無牴觸下水道法及有關子法。\n三、查貴府編訂之「臺北市雨水流出抑制設施設計參考手冊」之5.設計要點略以「流出抑制設施可於法定空地、建築物地面層、地下層或筏基內設置水池或雨水花園、水槽等多元雨水貯集或入滲手法……」，是故，雨水流出抑制設施之態樣眾多，是否屬下水道或用戶排水設備，請貴府依實認定。\n四、另查本部106年6月7日內授營建管字第1060808338號函略以「至有關貴府實施之『臺北市下水道管理自治條例』及相關規定或標準，如涉及建築法或建築技術規則規定之項目、構造或業務者，建議應仍由建築師依建築法及建築師法相關規定簽證負責……」，另查貴府訂定之「臺北市基地開發排入雨水下水道逕流量標準」第3條第1項第3款規定，雨水流出抑制設施為控制排放雨水逕流量至基地外之設施；究其功能為暫時儲存逕流量以防止過度集中流出，減輕下游管渠負荷，須透過水文分析及水理計算使其具排水調節及緩衝效能，並確保鄰近雨水下水道系統通洪能力，該設施無論設置於建築物內外，其所收集建築物或基地內之雨水逕流，如排放至雨水下水道系統，仍應考慮雨水下水道系統之負荷，故所涉下水道範疇，應依下水道法第17條及下水道法施行細則第13條規定辦理。至於專業簽證事項是否重複，請依據本部106年6月7日內授營建管字第1060808338號函略以「……惟該條例主管機關係為貴府，是有關該條例及相關規定所訂定之設施及業務，仍請貴府考量各專業技師及建築師依法所定之執業權限及其業務權責，避免專業簽證事項重複。」辦理。","refs":["A2","A5","A17","R13"]},{"id":"r15","agency":"內政部","date":"83.8.15","docNo":"台內營字第8388239號","y":83,"src":"2018彙編","brief":"下水道法第3條主管機關在中央為內政部","text":"下水道法第3條主管機關在中央為內政部；在省（市）為省（市）政府；在縣（市）為縣（市）政府。第4至第6條並明文規定各級主管機關應辦事項，俾確實執行該法規訂內容。故本法第8條所稱主管機關係指「下水道主管機關」。","refs":["A3","A8"]},{"id":"r16","agency":"內政部","date":"106.9.12","docNo":"營署工程字第1060058639號","y":106,"src":"2018彙編","brief":"查下水道法第3條規定，「本法所稱主管機關︰在中央為內政部","text":"查下水道法第3條規定，「本法所稱主管機關︰在中央為內政部；在直轄市為直轄市政府；在縣 (市) 為縣 (市) 政府。」第9條規定，「中央、直轄市及縣 (市) 主管機關，為建設及管理下水道，應指定或設置下水道機構，負責辦理下水道之建設及管理事項。」另查地方制度法第18條、第19條規定，下水道建設及管理屬地方自治事項，自得依上開規定為之。惟貴府應將辦理項及範圍與被指定為下水道機構協商確認後公告，以為日後執行之依據，涉公權力部分(如罰則、法令解釋等)仍應由貴府辦理。","refs":["A3","A9"]},{"id":"r17","agency":"內政部","date":"106.12.4","docNo":"內授營環字第1060818822號","y":106,"src":"2018彙編","brief":"查本部營建署93年7月21日營署工程字第0932911807號函送「研商市地重劃地區污水處理廠設置事宜紀錄」（會議紀…","text":"一、查本部營建署93年7月21日營署工程字第0932911807號函送「研商市地重劃地區污水處理廠設置事宜紀錄」（會議紀錄諒達）結論：「市地重劃按平均地權條例規定之程序辦理，重劃完成後，該地區設置專用下水道之原則，以個案考量，若達下水道法第8條及該法施行細則之規模者，需依規定設置專用下水道。」\n二、依據下水道法第3條規定，貴府為下水道法所稱之主管機關，下水道法第9條規定，貴府應指定或設置下水道機構，負責辦理下水道之建設及管理事項，該下水道機構即依據下水道法第22條及下水道法施行細則第15條規定，辦理下水道完成地區申請建築時核准及檢驗。惟貴府應評估受指定之下水道機構可否勝任下水道法所賦權責，且涉及公權力部分，仍應由貴府辦。","refs":["A3","A8","A9","A22","R15"]},{"id":"r18","agency":"內政部","date":"100.1.11","docNo":"內授營工程字第1000800172號","y":100,"src":"2018彙編","brief":"依據下水道法第4條第1項第7款規定，中央主管機關辦理跨越直轄市與縣（市）或二縣（市）以上下水道規劃、建設及管理之協調","text":"依據下水道法第4條第1項第7款規定，中央主管機關辦理跨越直轄市與縣（市）或二縣（市）以上下水道規劃、建設及管理之協調。本案淡水河系污水下水道系統涉臺北市、新北市及基隆市等轄區，爰本部同意擔任該系統之目的事業主管機關。","refs":["A4"]},{"id":"r19","agency":"內政部營建署","date":"90.5.8","docNo":"營署工程字第025222號","y":90,"src":"2018彙編","brief":"依地方制度法第18條第6款、第19條第6款及下水道法第6條規定，下水道建設及管理係屬貴府權責","text":"依地方制度法第18條第6款、第19條第6款及下水道法第6條規定，下水道建設及管理係屬貴府權責。有關已領有使用執照之建築物，使用用途變更，其污水處理之審查，請貴府本諸權責，訂定相關辦法規範之。","refs":["A6"]},{"id":"r20","agency":"內政部","date":"95.6.21","docNo":"內授營工程字第0950100159號","y":95,"src":"2018彙編","brief":"下水道法第7條規定：「公共下水道，由地方政府或鄉（鎮、市）公所建設及管理」","text":"下水道法第7條規定：「公共下水道，由地方政府或鄉（鎮、市）公所建設及管理」。貴府為台中縣下水道主管機關，本案所稱台中港港區內之公共雨水下水道系統，如係貴轄公共雨水下水道之一部分，則管理單位仍應為貴府。另自維護管理角度觀之，同一雨水下水道予以分段切割管理，徒增介面及影響排水功能之風險，亦不宜指定台中港務局為之。","refs":["A7"]},{"id":"r21","agency":"內政部營建署","date":"96.8.29","docNo":"營署工程字第0960045702號","y":96,"src":"2018彙編","brief":"下水道法第7條規定，公共下水道，由地方政府或鄉（鎮、市）公所建設及管理","text":"下水道法第7條規定，公共下水道，由地方政府或鄉（鎮、市）公所建設及管理。依前開規定，公共雨水下水道之建設及管理，自得由縣市政府或鄉（鎮、市）公所辦理。至　貴鄉雨水下水道建設，由前省住都局辦理發包施工，完工驗收後，移交　貴公所接管，負責其維護管理工作，尚屬適法。","refs":["A7"]},{"id":"r22","agency":"內政部","date":"84.1.17","docNo":"台內營字第8307031號","y":84,"src":"2018彙編","brief":"本部83年4月28日台內營字第827229號函規定，有關社區人口計算標準，都市計畫區依建築技術規則建築設備篇「化糞池…","text":"本部83年4月28日台內營字第827229號函規定，有關社區人口計算標準，都市計畫區依建築技術規則建築設備篇「化糞池使用人數」計算，其中總樓地板面積，依該規則建築設計施工篇第162條規定計算。","refs":["A8"]},{"id":"r23","agency":"內政部","date":"84.12.23","docNo":"台內營字第8408545號","y":84,"src":"2018彙編","brief":"專用下水道設置之目的在管制廢（污）水污染問題，若興建納骨塔非居住使用，自可免設專用下水道","text":"專用下水道設置之目的在管制廢（污）水污染問題，若興建納骨塔非居住使用，自可免設專用下水道。","refs":["A8"]},{"id":"r24","agency":"內政部","date":"85.1.15","docNo":"台內營字第8572061號","y":85,"src":"2018彙編","brief":"依下水道法第8條規定，政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設並管理之","text":"依下水道法第8條規定，政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設並管理之。縣（市）政府為縣（市）下水道主管機關，依法辦理縣（市）下水道有關事宜，在其所轄地區設置工業區，該工業區之專用下水道建設、管理，自應由縣（市）政府監督。\n現行工業區設有管理中心（站），負責辦理工業區內專用下水道營運、管理事項，縣（市）政府自可依下水道法之規定，指定該管理中心（站）為工業區下水道機構，倘工業區內事業有違反下水道法規定之案件，應由該管理中心（站）移送縣（市）政府處理。若該管理中心（站）無法勝任下水道法所賦權責，則原開發工業區之機關（構），仍需依前揭規定，負責該專用下水道之管理事宜。","refs":["A8","A9"]},{"id":"r25","agency":"內政部","date":"85.2.8","docNo":"台內營字第8501613號","y":85,"src":"2018彙編","brief":"經變更設計後之新開發社區，若其戶數超過100戶，仍需依下水道法規定，設置專用下水道","text":"經變更設計後之新開發社區，若其戶數超過100戶，仍需依下水道法規定，設置專用下水道。","refs":["A8"]},{"id":"r26","agency":"內政部","date":"85.2.27","docNo":"台內營字第8572291號","y":85,"src":"2018彙編","brief":"專用下水道指供特定區或場所使用下水道，其設置目的，在改善人為居住或活動產生之廢（污）水污染問題，大型商場雖非供「居住…","text":"專用下水道指供特定區或場所使用下水道，其設置目的，在改善人為居住或活動產生之廢（污）水污染問題，大型商場雖非供「居住」使用，惟因商業行為，人口出入頻繁，如其規模相當，所產生之廢（污）水量亦大，為解決該廢（污）水污染環境，下水道主管機關自得依下水道法第8條，指定其為興建專用下水道之地區或場所。","refs":["A8","A15"]},{"id":"r27","agency":"內政部","date":"85.8.28","docNo":"台內營字第8505730號","y":85,"src":"2018彙編","brief":"有關新開發社區設置專用下水道之原則及流程，請依照本部84年9月14日台內營字第8408366號函內容辦理，至山坡地開…","text":"有關新開發社區設置專用下水道之原則及流程，請依照本部84年9月14日台內營字第8408366號函內容辦理，至山坡地開發案，若依山坡地開發建築管理辦法規定，專用下水道應與雜項工作物一併完成時，則從其規定辦理。","refs":["A8"]},{"id":"r28","agency":"內政部營建署","date":"86.2.3","docNo":"營署公字第02548號","y":86,"src":"2018彙編","brief":"據貴校函稱，民國78年5月6日台灣省政府住都局核准建校時，並未要求設置專用下水道，現今校內欲新建學生宿舍，住宿人數3…","text":"據貴校函稱，民國78年5月6日台灣省政府住都局核准建校時，並未要求設置專用下水道，現今校內欲新建學生宿舍，住宿人數303人，其污水處理雖未達本部84年9月14日函應設置專用下水道之標準，惟花蓮縣政府仍得依下水道法第8條第2項之規定，指定貴校設置宿舍之專用下水道。","refs":["A8"]},{"id":"r29","agency":"內政部營建署","date":"86.3.10","docNo":"營署公字第04677號","y":86,"src":"2018彙編","brief":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。其目的在將廢（污）水處理至符合放流水標準，以免污染水源水體，惟以具一定規模或污染量（質）者為之，故同法施行細則稱「新開發社區」指500人以上居住或100住戶以上之地區。\n在水源水質水量保護區內建造一棟五樓自用住宅，屬一般建築物之興建，若未達「新開發社區」之規模，依各「水源水質水量保護區」管制事項之規定，各該保護區內「興建房舍，應具有廢污物處理衛生設備，其設計標準及廢污水放流應符合有關法令之規定」。查放流水標準訂有建築物之標準，本案屬一般建築物之興建，其廢污水應遵其規定辦理。","refs":["A8"]},{"id":"r30","agency":"內政部營建署","date":"86.3.12","docNo":"營署公字第04857號","y":86,"src":"2018彙編","brief":"工業區之開發，應依下水道法第8條之規定，設置專用下水道系統，其目的旨在防治事業生產過程產生之廢（污）水，若區內採雨、…","text":"工業區之開發，應依下水道法第8條之規定，設置專用下水道系統，其目的旨在防治事業生產過程產生之廢（污）水，若區內採雨、污水分流制施設，依該法施行細則第16條，雨水及污水應分別排洩於雨、污水下水道內，不得混排。該細則第3條復稱雨水下水道指專供處理雨水之下水道；污水下水道指專供處理家庭污水及事業廢水之下水道，二者功能不同。查放流水標準僅訂有污水下水道之標準，雨水下水道則尚厥如，若工業區內雨水下水道遭廢（污）水排洩於內，則工業區管理單位宜善盡管理之責，確實查察不法偷排之污染源，請環保單位依法處分。","refs":["A8","R16"]},{"id":"r31","agency":"內政部營建署","date":"86.3.14","docNo":"營署公字第51320號","y":86,"src":"2018彙編","brief":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"一、下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。其目的在將廢（污）水處理至符合放流水標準。以免污染水源水體，惟以具一定規模或污染量（質）者為之，故同法施行細則稱「新開發社區」指500人以上居住或100住戶以上之地區。\n二、本案○君擬在基隆河水源水質水量保護區內建造一棟五樓自用住宅屬一般建築物之興建，並未達「新開發社區」之規模。依台灣省政府70年1月28日七0府建四字第103556號函公告「基隆河水源水質水量保護區」管制事項八規定，該保護區內「興建房舍，應具有廢污物處理衛生設備，其設計標準及廢污水放流應符合有關法令之規定」。查放流水標準訂有建築物之標準，本案屬一般建築物之興建，其廢污水應遵其規定辦理。","refs":["A8"]},{"id":"r32","agency":"內政部營建署","date":"86.4.26","docNo":"營署公字第54943號","y":86,"src":"2018彙編","brief":"下水道法第8條規定，新開發社區應設置專用下水道系統","text":"下水道法第8條規定，新開發社區應設置專用下水道系統。本部84年9月14日台（84）內營字第848036號函規定其人口計算基準，在都市計畫地區，依建築技術規則「建築設備篇」之「化糞池使用人數計算」。復查本部84年1月17日台（84）內營字第8307031號函業已解釋前揭化糞池使用人數計算方式，依同規則建築設計施工編第162條規定，停車場得不計入總樓地板面積（以上內容均詳如附件）。另查「化糞池使用人數計算方式」，百貨商場依營業面積每平方公尺以0.2人計算，故大型購物商場宜比照前開方式計算。\n至下水道之入滲量問題，「污水下水道系統規劃要點」八、（五）係指污水管線埋設於地下之入滲量如何計算，而建築物中之污水管線，非埋設於地下，應無入滲之問題，故毋需計算入滲量。","refs":["A8","R4"]},{"id":"r33","agency":"內政部營建署","date":"86.5.14","docNo":"營署公字第09280號","y":86,"src":"2018彙編","brief":"下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理","text":"下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理；同法施行細則第13條稱專業技師為環境（衛生）、土木或水利科之工業技師、所詢專用下水道處理設施之鋼筋結構部分，係屬下水道設施之一環，故該部份，仍得由上開專業技師辦理之。","refs":["A8","A17","R13"]},{"id":"r34","agency":"內政部營建署","date":"87.3.13","docNo":"營署公字第53233號","y":87,"src":"2018彙編","brief":"按精鍾商專於民國78年5月6日既經台灣省政府住都局核准建校，斯時並未要求設置專用下水道，以本案新建學校宿舍，並未達下…","text":"按精鍾商專於民國78年5月6日既經台灣省政府住都局核准建校，斯時並未要求設置專用下水道，以本案新建學校宿舍，並未達下水道法規定設置之標準，該核自屬毋庸設置專用下水道。惟為防治污染，花蓮縣政府基於現主管機關立場，仍得依下水道法第8條第2項之規定，指訂該校設置宿舍之專用下水道，故本案是否設置專用下水道，仍宜請花蓮縣政府本諸權責逕行核處。","refs":["A8"]},{"id":"r35","agency":"內政部營建署","date":"87.7.16","docNo":"營署建字第13199號","y":87,"src":"2018彙編","brief":"依下水道法第8條第2項規定：「私人新發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"依下水道法第8條第2項規定：「私人新發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。」該法所稱「專用下水道」並明訂於同法第2條第4款，是工業區專用下水道既為「專用下水道」，依本部86年12月2日台（86）內營字第8689174號函釋說明三「………開發建築基地內設施，係建築法所稱之雜項工作物，應依建築法之規定請領建造執照。」，本案仍請依上開函釋辦理。","refs":["A8"]},{"id":"r36","agency":"內政部營建署","date":"87.8.18","docNo":"營署公字第20411號","y":87,"src":"2018彙編","brief":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。按學校產生污水之性質與社區類似，於申請設校時，下水道主管機關自得視當地環境情況，依前揭規定，指定該校設置專用下水道。本案學校若未設置專用下水道，而新申請增建廚房或活動中心等建築物，是否應設置專用下水道？請貴局就實際情形，逕為處理，若有污染之虞，自得依前揭規定，指定該新建建物設置專用下水道；至人口計算標準，準依建築技術規則「建築設備編」第41條，化糞池使用人數「建築物用途」五之方式為之。","refs":["A8","R4"]},{"id":"r37","agency":"內政部營建署","date":"87.8.31","docNo":"營署公字第22494號","y":87,"src":"2018彙編","brief":"下水道法第8條規定新開發社區、工業區或經主管機關指定之地區或場所應興建專用下水道","text":"下水道法第8條規定新開發社區、工業區或經主管機關指定之地區或場所應興建專用下水道；而新開發社區依同法施行細則第4條係指可容納500人以上或總計興建100住戶以上之社區。上開法定解釋至為明確，毋庸置疑，本部82年4月28日台　內營字第8272290號函釋內容係補充解釋，與下水道法之規定並無相悖。至所詢是否須辦理環境影響評估乙節，請另洽環境單位辦理。","refs":["A8","R4"]},{"id":"r38","agency":"內政部營建署","date":"87.9.8","docNo":"營署公字第23448號","y":87,"src":"2018彙編","brief":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。其目的在收集該地區之廢污水處理後排放，以防治污染。按醫院產生之污水屬事業廢水，其處理係依水污染防治法相關規定為之，本案既已依水污染防治法提具水污染防治措施計畫，其目的與專用下水道相同，如該防治措施已能將廢污水（包括宿舍污水）收集處理，則毋再另設置專用下水道之必要。","refs":["A8"]},{"id":"r39","agency":"內政部營建署","date":"87.9.16","docNo":"營署公字第24191號","y":87,"src":"2018彙編","brief":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。按學校產生之污水性質與社區類似，於申請設校時，下水道主管機關自得視當地環境情況，依前揭規定，指定該校設置專用下水道。本案學校屬舊有學校，若未設置專用下水道，而新增建建教室使用人數超過500人，貴府得指定該新建教室設置其專用下水道。","refs":["A8"]},{"id":"r40","agency":"內政部營建署","date":"88.5.13","docNo":"營署公字第13238號","y":88,"src":"2018彙編","brief":"新開發社區應依照下水道法第8條之規定設置專用下水道，同法施行細則第4條稱新開發社區為可容納500人以上居住或總計興建100住戶之社區","text":"一、新開發社區應依照下水道法第8條之規定設置專用下水道，同法施行細則第4條稱新開發社區為可容納500人以上居住或總計興建100住戶之社區。目前下水道法縣市主管機關大部未設置下水道專責單位，為彌補其下水道審查人力不足，宜藉專業技師專業能力協助，內政部84年9月14日台（84）內營字第8480366號函，有關新開發社區設置專用下水道之原則及流程，有關技師簽認證明予以詳加規定（如附件），請參照。\n二、至污水下水道系統違反水污染防治法之罰鍰相關事宜，請另洽環保單位。","refs":["A8","R4"]},{"id":"r41","agency":"內政部營建署","date":"88.6.29","docNo":"營署公字第17194號","y":88,"src":"2018彙編","brief":"下水道法第8條規定私人新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道，同法施行細則第4條稱新開發工業…","text":"一、下水道法第8條規定私人新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道，同法施行細則第4條稱新開發工業區為： (一)政府機關、公民營事業機構開發公事業設廠之地區。 (二)事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者。\n二、前開係規定工業區設置專用下水道之規模及原則，並無污水廠數之限制。工業區開發者或事業設廠者，得依其實際規劃需要設置一或多座污水處理廠。本案麥寮工業區以分期分區方式開發，依需要分別設置數座污水處理廠，並無違反下水道法之規定。","refs":["A8","R4"]},{"id":"r42","agency":"內政部營建署","date":"88.9.7","docNo":"營署公字第28269號","y":88,"src":"2018彙編","brief":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道，同法施行細則第4條稱「新開…","text":"一、下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道，同法施行細則第4條稱「新開發社區」為可容納500人以上居住或總計興建100住戶以上之社區；「新開發工業區」為左列情形之一者：\n（一）政府機關、公民營事業機構開發供事業設廠之地區。\n（二）事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者。\n二、本案事業於政府依法劃設供工業使用之土地設廠，其基地未達二公頃，若亦未經主管機關依下水道法指定應設置專用下水道，則毋需設置。惟於其基地內外興建戶數大於100戶，仍屬前開施行細則所稱「新開發社區」，應依規定設置專用下水道。\n三、至新開發社區原建造執照變更設計後符合專用下水道之條件，應於申請變更同時，依該施行細則第5條之規定為之。","refs":["A8","R4"]},{"id":"r43","agency":"內政部","date":"88.10.7","docNo":"八內營字第8874870號","y":88,"src":"2018彙編","brief":"下水道法第8條規定新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道，同法施行細則第4條稱「新開發社區…","text":"一、下水道法第8條規定新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道，同法施行細則第4條稱「新開發社區」為可容納500人以上居住或總計興建100住戶以上之社區；「新開發工業區」為：（一）政府機關、公民營事業機構開發供事業設廠之地區。（二）事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者。\n二、依前開規定，新開發社區設置規模達100住戶或500人以上即應依法設置專用下水道；若未達前述規模，有污染之虞，主管機關仍得指定其設置專用下水道。至「事業於政府依法劃設供工業使用之土地設廠」，其基地面積達二公頃以上始達應設置專用下水道之規模，面積未達二公頃以上，自毋需設置專用下水道，惟其污水處理問題，應另依環保相關法令為之。","refs":["A8"]},{"id":"r44","agency":"內政部營建署","date":"89.1.4","docNo":"營署公字第43848號","y":89,"src":"2018彙編","brief":"下水道法第8條之規定，新開發社區或經主管機關指定之地區或場所應設置專用下水道，該法施行細則第4條稱「新開發社區」為可…","text":"下水道法第8條之規定，新開發社區或經主管機關指定之地區或場所應設置專用下水道，該法施行細則第4條稱「新開發社區」為可容納500人以上居住或總計興建100住戶以上之社區。故需達前開條件，方適用本部規定之專用下水道設置申請流程，否則均按一般建造案件處理。","refs":["A8","R4"]},{"id":"r45","agency":"內政部營建署","date":"89.10.27","docNo":"營署工程字第53725號","y":89,"src":"2018彙編","brief":"新開發社區應依下水道法第8條規定設置專用下水道並管理之，所稱「新開發社區」依同法施行細則第4條，指可容納500人以上…","text":"一、新開發社區應依下水道法第8條規定設置專用下水道並管理之，所稱「新開發社區」依同法施行細則第4條，指可容納500人以上居住或總計興建100住戶以上之社區。前揭設置專用下水道旨在處理社區污水，維護環境衛生、防治水污染。本案台灣紙業公司開發社區如具前項規模，自應依規定為之，其擬將已領建築執照及未申請建照之污水集中設於一領有使用執照供住宅用途之地下一層及筏基設置污水處理設施處理，若該設施之容量可容納新增之污水量，自可同意，惟該設置之核准、完工後查驗、使用執照之核發，請依施行細則第5條規定辦理。\n二、有關該住宅用途建築物增設污水處理設備，涉建築執照問題乙節，按建築法第7條及第28條第1項第2款規定：「本法所稱雜項工作物，為營業爐竈、水塔、瞭望臺、廣告牌、散裝倉、廣播塔、煙囪、圍牆、駁崁、高架遊戲設施、游泳池、地下儲藏庫、建築物興建完成後增設之中央系統空氣調節、昇降設備、防空避難、污物處理及挖填土石方等工程。」、「雜項執照：雜項工作物之建築，應請領雜項執照。」本案如於已領得使用執照之建築物增設污水處理設備（機械），自應依前揭規定請領雜項執照，另按建築法第73條執行要點係將建築物用途依使用強度及危險指標分為9類24組，是建築物用途如有跨類跨組變更，應依同法第73條規定辦理變更使用，本案原申請建照時已標示污水處理槽位置，現擬增設污水處理設備（機械），尚無涉及上開使用類組變更規定。","refs":["A8","R4"]},{"id":"r46","agency":"內政部營建署","date":"90.1.31","docNo":"營署工程字第004445號","y":90,"src":"2018彙編","brief":"下水道法第8條規定私人新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道，所稱「新開發工業區」依同法施行…","text":"下水道法第8條規定私人新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道，所稱「新開發工業區」依同法施行細則第4條，指政府機關、公民營事業機構開發供事業設廠之地區或事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者。專用下水道設置目的，旨在維護環境衛生、防治水污染，工業區申請建照面積未達前揭標準，主管機關仍得依前開規定指定設置專用下水道。本案請貴府本諸權責，衡酌辦理。","refs":["A8","R4"]},{"id":"r47","agency":"內政部營建署","date":"90.4.11","docNo":"營署工程字第019657號","y":90,"src":"2018彙編","brief":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。其目的旨在收集該地區之廢污水處理後排放，以防治污染。按醫院之污水屬事業廢水，若申請案已依水污染防治相關規定提具水污染防治措施計畫，並經核准，其目的與設置專用下水道相同，即廢污水（包括醫院生活污水）可妥善處理，則毋需再行提具專用下水道申請，惟應事先協調下水道主管機關。","refs":["A8"]},{"id":"r48","agency":"內政部營建署","date":"90.6.7","docNo":"營署工程字第033715號","y":90,"src":"2018彙編","brief":"下水道法第8條規定，新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道，該法施行細則第5條稱新開發社區…","text":"下水道法第8條規定，新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道，該法施行細則第5條稱新開發社區為供100住戶以上或500人以上居住之社區。除社區外，主管機關對具相當規模之地區或場所，其產生之污染量有污染之虞，仍得指定其應設置專用下水道。本案請貴府本諸權責認定之。","refs":["A8","R5"]},{"id":"r49","agency":"內政部","date":"90.6.21","docNo":"台內營字第9009312號","y":90,"src":"2018彙編","brief":"下水道法第8條規定私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條規定私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。該法施行細則第5條復規定，該專用下水道設置前，應檢附專用下水道規劃及設計圖說等資料，申請該管主管機關核准，始得施工；完工後，須經下水道主管機關查驗合格，始得使用。而水污染防治法第13條，事業於設立或變更前，應先檢具水污染防治措施計畫，經主管機關審查核准。茲因水污染防治措施目的與設置專用下水道相同，若該措施相關書圖業經審查，則毋需再重複送下水道單位審查，避免浪費行政資源，惟應會知；若該水污染防治措施為設置專用下水道，而相關書圖未予審查，則自應檢送下水道單位核准。","refs":["A8","R5"]},{"id":"r50","agency":"內政部營建署","date":"90.7.20","docNo":"營署工程字第042740號","y":90,"src":"2018彙編","brief":"下水道法第8條規定，新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道","text":"一、下水道法第8條規定，新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道。其目的在處理生活污水或事業廢水，防治水污染。而認定標準及人口計算基準則依施行細則第4條規定辦理。除新開發社區或工業區外，主管機關仍得指定有污染之虞之地區或場所設置專用下水道。所詢「聖帝廟新建工程」是否應設置專用下水道，請貴府依前述原則衡酌辦理。\n二、至新開發社區是否適用「建築物污水處理設施設計技術規範」內「建築物用途說明Ａ--Ｇ類」各項場所之建築物乙節，查施行細則第4條係規定該規範為人口計算基準依據，當人口達500人以上者為新開發社區，應依規定設置專用下水道。","refs":["A8","R4"]},{"id":"r51","agency":"內政部","date":"90.8.1","docNo":"台內營字第9011671號","y":90,"src":"2018彙編","brief":"台中港倉儲專區應依下水道法第8條之規定設置專用下水道，貴府並得指定下水道機構，負責該專區有關下水道建設、管理事宜，惟…","text":"一、台中港倉儲專區應依下水道法第8條之規定設置專用下水道，貴府並得指定下水道機構，負責該專區有關下水道建設、管理事宜，惟涉及專用下水道書圖之核准、驗收、或違規事件之處分，仍應由貴府（下水道法縣主管機關）為之。\n二、至前揭所稱下水道機構之指定，由貴府視該專用下水道由何者負責管理決定之。","refs":["A8"]},{"id":"r52","agency":"內政部營建署","date":"90.8.2","docNo":"營署工程字第045715號","y":90,"src":"2018彙編","brief":"下水道法第8條規定，新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道，所稱新開發社區依據該法施行細則第…","text":"下水道法第8條規定，新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道，所稱新開發社區依據該法施行細則第4條：指容納100住戶以上或500人以上之社區，而人口計算標準，都市計畫地區依「建築物污水處理設施設計技術規範」所定使用人數方式計算，都市計畫以外地區以每人使用三十平方公尺之樓地板面積計算。若未達前開標準，主管機關認為有污染之虞者，仍得視指定該地區或場所設置專用下水道。本案民間收費站是否須設置專用下水道，請貴府依前開原則，視當地環境情形衡酌辦理。","refs":["A8","R4"]},{"id":"r53","agency":"內政部營建署","date":"91.9.30","docNo":"營署工程字第0910062178號","y":91,"src":"2018彙編","brief":"下水道法第8條規定、新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道","text":"下水道法第8條規定、新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道。所稱新開發工業區，依據該法施行細則第4條解釋，指政府機關、公民營事業機構開發工事業設廠之地區或事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者。本案所詢尚非前開所屬範疇，請其另依環保法令規定設置廢污水處理設施。","refs":["A8"]},{"id":"r54","agency":"內政部","date":"91.12.4","docNo":"營署工程字第0910075377號","y":91,"src":"2018彙編","brief":"工業區應依下水道法第8條之規定設置專用下水道，其目的為處理其區內廢（污）水，以防治水污染","text":"工業區應依下水道法第8條之規定設置專用下水道，其目的為處理其區內廢（污）水，以防治水污染。若經經濟部工業局同意納入其所屬大里工業區污水處理廠代為處理，且經貴府（下水道主管機關）同意，得予為之。惟同意之理由消失，則其仍應另行依規定設置專用下水道。","refs":["A8"]},{"id":"r55","agency":"內政部營建署","date":"92.3.5","docNo":"營署工程字第0920009598號","y":92,"src":"2018彙編","brief":"新開發社區應依下水道法第8條之規定設置專用下水道並管理之，所稱新開發社區，下水道法施行細則第4條稱達100戶或500人以上居住之社區","text":"新開發社區應依下水道法第8條之規定設置專用下水道並管理之，所稱新開發社區，下水道法施行細則第4條稱達100戶或500人以上居住之社區。本案既已整體開發分區建設，並達前開規定規模，自應依照辦理，並無分區後住戶低於規模之區別。","refs":["A8","R4"]},{"id":"r56","agency":"內政部營建署","date":"92.4.10","docNo":"營署工程字第0920018717號","y":92,"src":"2018彙編","brief":"下水道法第8條規定，新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條規定，新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。學校是否應設置專用下水道，應由主管機關視該校對當地水污染及環境之衝擊情形，依前開規定辦理。若學校係下水道法公布前既設，欲申請部分教室校舍新建或改建，其污水處理問題，則以該新建或改建之規模認定之。","refs":["A8"]},{"id":"r57","agency":"內政部營建署","date":"92.7.23","docNo":"營署工程字第0920043823號","y":92,"src":"2018彙編","brief":"查新開發工業區應依下水道法第8條之規定設置專用下水道，同法施行細則第4條稱「新開發工業區」有二，其一為政府機關、公民…","text":"一、查新開發工業區應依下水道法第8條之規定設置專用下水道，同法施行細則第4條稱「新開發工業區」有二，其一為政府機關、公民營事業機構開發供事業設廠之地區；其二為事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者。依前開意旨，凡新設、增建、擴建、改建，其「基地」面積達二公頃以上之事業，皆為應設置專用下水道之範疇。依來函所示，華新麗華公司申請增建廠房，面積為2,503.13平方公尺，未達前述規模，自毋需設置專用下水道。至貴府函說明是否適用下水道法施行細則，應請貴府另行查明，其若屬合法可供設廠之工業用地，自得適用前開原則。\n二、另事業若已依水污染防治法規定設置廢污水處理設施，其目的與專用下水道相同，應毋需另設置專用下水道之必要。","refs":["A8","R4"]},{"id":"r58","agency":"內政部營建署","date":"92.10.8","docNo":"營署工程字第0920058940號","y":92,"src":"2018彙編","brief":"下水道法第8條第2項規定：私人新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道","text":"一、下水道法第8條第2項規定：私人新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道。所稱「主管機關指定之地區或場所」指該法施行細則第4條所作「新開發社區」、「新開發工業區」之定義以外，主管機關衡酌當地環境特性認為對環境有污染之虞，仍須設置專用下水道之必要者。前稱施行細則第4條解釋「新開發工業區」為政府機關、公民營事業機構開發供事業設廠之地區（如台中、民雄、幼獅工業區---等）或事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者（如都市計畫區之工業區、都市計畫區外之丁種建築用地等）。\n二、前開政府機關、公民營事業機構開發供事業設廠之新開發工業區內之事業應依下水道法第19條之規定，除經當地主管機關核准者外，均應依規定將廢污水排洩於下水道之內。本案指尚無管線可供接管，需直接排放於地面水體之事業，其放流水標準仍須符合放流水標準，且需申請排放許可經核准始得為之，俟管線到達後，仍須將污水排洩於下水道內。\n三、至事業於政府依法劃設供工業使用之土地設廠，其基地面積未達二公頃以上者，自毋需設置專用下水道，其廢污水之處理，悉另依「水污染防治法」之相關規定辦理。","refs":["A8","R4"]},{"id":"r59","agency":"內政部營建署","date":"93.1.14","docNo":"營署工程字第0930002707號","y":93,"src":"2018彙編","brief":"下水道法第8條規定新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道，同法第2條第4款稱「新開發社區」指…","text":"下水道法第8條規定新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道，同法第2條第4款稱「新開發社區」指供特定地區或場所使用而設置尚未納入公共下水道之下水道。依前開要旨，新開發社區、工業區或經主管機關指定之地區或場所均應依規定辦理專用下水道之設置，並應管理之。復查該法第19條第2項規定，下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道之內。專用下水道屬下水道之一種，其排水區域內之污水亦應遵照前開規定辦理，而若其放流水排放及營運管理事項，均符合相關法令規定，自無須強制納入公共下水道，惟地方下水道主管機關認有納管之必要，得經協調同意納入。","refs":["A8"]},{"id":"r60","agency":"內政部營建署","date":"93.1.29","docNo":"營署工程字第0930005632號","y":93,"src":"2018彙編","brief":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。所稱「主管機關指定之地區或場所」，其認定標準及範圍應由主管機關視申請個案對當地環境衝擊衡酌決定之。故有關學校是否需設置專用下水道，請貴府本諸權責辦理。","refs":["A8"]},{"id":"r61","agency":"內政部營建署","date":"93.4.23","docNo":"營署工程字第0930027988號","y":93,"src":"2018彙編","brief":"自來水淨水流程係將原水淨化為自來水，包括沉澱、過濾、消毒等設備，一般自來水廠均設有處理淨化過程中產生之污泥、反沖洗水…","text":"自來水淨水流程係將原水淨化為自來水，包括沉澱、過濾、消毒等設備，一般自來水廠均設有處理淨化過程中產生之污泥、反沖洗水等設施，故「自來水廠」仍屬水污染防治法所稱之「事業」，需符合其放流水標準，除上述事業之污水處裡外，廠區內尚有辦公、員工宿舍等生活污水須妥善處理。爰此，自來水廠內生活污水達下水道法設置專用下水道規模者，即100住戶或500人以上者，仍須設置專用下水道，未達此規模者，則設置建築物污水處理設施處理。惟本案位處和平工業區內，該廠產生之生活污水應優先排洩於工業區之專用下水道處理，如未接入，則請依前開原則辦理。有關竣工查驗，仍須依相關規定為之。","refs":["A8"]},{"id":"r62","agency":"內政部營建署","date":"93.5.21","docNo":"營署工程字第號0930033726","y":93,"src":"2018彙編","brief":"私人新開發社區應依「下水道法」第8條規定設置專用下水道，所稱專用下水道包括污水處理場及污水管線","text":"私人新開發社區應依「下水道法」第8條規定設置專用下水道，所稱專用下水道包括污水處理場及污水管線。社區興建建築物之使用執照，依同法施行細則第5條規定，應於專用下水道完工經查驗合格後，始得核發。所稱查驗，指社區之污水處理場是否按圖施工、建築物有否以污水管線銜接至污水處理場。全社區若採設置單一污水處理場，足以處理社區開發完成之污水，社區以分期方式開發，如污水處理場已經主管機關於第一期核發使用執照時查驗合格，則第二期起，僅查驗該期之管線部份。","refs":["A8","R5"]},{"id":"r63","agency":"內政部","date":"93.6.21","docNo":"內授營工程字第0930007853號","y":93,"src":"2018彙編","brief":"下水道分為公共下水道及專用下水道，下水道法第2條第3款稱公共下水道為公共使用之下水道","text":"下水道分為公共下水道及專用下水道，下水道法第2條第3款稱公共下水道為公共使用之下水道；第3款稱專用下水道為供特定地區或場所使用而設置尚未納入公共下水道之下水道。同法第8條規定：政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設管理之。私人新開發社區、工業區或經主管機關指定之地區或場所應設置專用下水道。國家風景區屬國家經營之風景特定地區，下水道主管機關自得指定其為應設置專用下水道之地區，經費由目的事業主管機關負擔。","refs":["A8"]},{"id":"r64","agency":"內政部營建署","date":"94.1.28","docNo":"營署工程字第0940003346號","y":94,"src":"2018彙編","brief":"下水道法第8條規定，新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道，該法施行細則第4條稱「新開發社…","text":"一、下水道法第8條規定，新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道，該法施行細則第4條稱「新開發社區」為可容納500人以上居住或總計興建100住戶以上之社區申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者。故專用下水道應將社區污水集中處理符合放流水標準後，依規定排放。復依下水道法第19條並規定，下水道排水區域內之下水，除經當地主管機關核准者外，應依規定排洩於下水道之內。\n二、依前開規定，新開發社區既依規定設置專用下水道，則該區域內之污水，自應依法排洩於專用下水道之內。所詢專用下水道區內之新增建物裝設預鑄式污水處理槽，不銜接該社區專用下水道，主管機關自得就事實認定不予核發建築物之使用執照，且自無所稱獨立污水處理設施管理責任歸屬問題。","refs":["A8"]},{"id":"r65","agency":"內政部營建署","date":"94.3.28","docNo":"營署工程字第0940013502號","y":94,"src":"2018彙編","brief":"下水道法第8條規定新開發社區應設置專用下水道並管理之，其目的在處理該社區之廢污水","text":"下水道法第8條規定新開發社區應設置專用下水道並管理之，其目的在處理該社區之廢污水。查水污染防治法第13條規定，事業於設立或變更前，應檢具水污染防治措施計畫及相關文件，送直轄市、縣（市）主管機關或中央主管機關審查核准。所稱水污染防治措施指該事業之水污染處理設施，其功能與專用下水道相同。本案大溪山莊既已依水污染防治法規定辦理，並領有廢（污）水排放許可證，則毋需再為專用下水道設置之申請，惟貴府須予確認全區廢污水均已納入該污水處理設施處理，且其放流水符合排放標準。","refs":["A8"]},{"id":"r66","agency":"內政部營建署","date":"94.6.17","docNo":"營署工程字第0940030707號","y":94,"src":"2018彙編","brief":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。同法施行細則第4條定義新開發社區為可容納500人以上居住或總計興建100住戶以上，申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者。政府機關或公營事業機構興建辦公場所、房舍，使用人次規模若相當於500人以上居住或總計興建100住戶者，則其污染量與新開發社區相當，主管機關自得依下水道法第8條之規定，「指定」為應設置專用污水下水道之地區或場所，其審查程序悉依下水道法及施行細則規定辦理。","refs":["A8"]},{"id":"r67","agency":"內政部營建署","date":"94.12.16","docNo":"營署工程字第0940066060號","y":94,"src":"2018彙編","brief":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。所稱新開發社區，依據該法施行細則第4條指申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水之可容納500人以上居住或總計興建100住戶以上社區。下水道法施行細則於75年公布，其第4條對新開發社區定義即有明文規定，86年修正時，再作前開明確解釋。本案斗南第二市場大樓總戶數達286戶，是否已依前開規定設置專用下水道，請貴府查明，若已設置，其申請排入公共水體，請洽環保單位依水污染防治法相關規定辦理。","refs":["A8","R4"]},{"id":"r68","agency":"內政部營建署","date":"95.2.16","docNo":"營署工程字第0950007084號","y":95,"src":"2018彙編","brief":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。該法施行細則第5條稱「新開發社區」為可容納500人以上居住或總計興建100住戶以上之社區，其申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者。是若學校及醫院之新建建築物,其規模達前開規模者，直轄市、縣（市）主管機關得指定其為之應設置專用下水道之地區或場所，設置專用下水道。","refs":["A8"]},{"id":"r69","agency":"內政部營建署","date":"95.3.10","docNo":"營署工程字第0950009583號","y":95,"src":"2018彙編","brief":"下水道法第8條規定：政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設、管理之","text":"下水道法第8條規定：政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設、管理之。私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。該法施行細則第4條稱新開發工業區為政府機關、公民營事業機構開發供事業設廠之地區或事業於政府依法劃設供工業使用之土地設廠，其基地面積達2公頃以上者。查工廠廢水因其水質與公共污水下水道所處理之家庭污水不同，故其達前開規模者，應依規定設置專用污下水道處理其事業廢水。惟若公共污水下水道已到達政府依法劃設供工業使用之土地範圍，該地區之工廠廢水若其水質符合當地下水道主管機關核定之可容納下水水質標準者，則得經當地下水道主管機關同意後，納入公共污水下水道系統。","refs":["A8"]},{"id":"r70","agency":"內政部營建署","date":"95.3.29","docNo":"營署工程字第0950015050號","y":95,"src":"2018彙編","brief":"下水道法第8條規定，政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設、管理之","text":"一、下水道法第8條規定，政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設、管理之。私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。同法施行細則第4條稱新開發社區為可容納500人以上居住或總計興建100住戶以上之社區，其申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者。依前開規定，舊有學校增建教室，使用人數達500人者，直轄市、縣（市）下水道主管機關得指定該增建部分設置專用下水道。至其使用人口計算方式，依前開施行細則第4條規定，實施都市計畫地區，以建築物污水處理設施設計技術規範所定使用人數方式計算，實施都市計畫以外地區：以每人使用30平方公尺之樓地板面積計算。\n二、至專用下水道指污水收集管渠、污水處理廠及相關設施。","refs":["A8","R4"]},{"id":"r71","agency":"內政部營建署","date":"95.4.11","docNo":"營署工程字第0950016687號","y":95,"src":"2018彙編","brief":"下水道法第8條規定，政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設、管理之","text":"下水道法第8條規定，政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設、管理之。私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。同法施行細則第4條稱新開發社區、工業區為符合下列條件之地區，其申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者：\n一、新開發社區：可容納500人以上居住或總計興建100住戶以上之社區。\n二、新開發工業區：政府機關、公民營事業機構開發供事業設廠之地區或事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者。按專用下水道設置之目的旨在處理一定規模以上之廢（污）水，以防治污染，本案申請新建測試機房，若建築物用途全為機械房，未產生事業廢水及達新開發社區規模之員工生活污水，則免設置專用下水道。","refs":["A8"]},{"id":"r72","agency":"內政部營建署","date":"95.10.11","docNo":"營署工程字第0950049495號","y":95,"src":"2018彙編","brief":"下水道法第8條規定，政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設、管理之","text":"一、下水道法第8條規定，政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設、管理之。私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。復依86年7月16日該法施行細則第4條修正前之規定稱新開發社區指經主管機關認定之社區及合於下列情形之一者而言：（一）可容納500人以上居住或總計興建100住戶以上者。（二）依山坡地有關法規規定於山坡地從事開發建築者。依上述規定各直轄市、縣（市）政府於社區開發案送審階段即需認定是否應設置專用下水道，經「認定」者方設置之。嗣因「認定」乙節，標準不一，爭議頗多，本部為強化生活污水之管理，並求執法之明確，於86年7月16日台（86）內營字第8673235號令修正公布前開下水道法施行細則第4條，刪除「認定」機制，並以凡達100住戶或500人者，皆稱為「新開發社區」，其未能接用公共下水道者，應設置專用下水道。\n二、本案百年大鎮社區查係82年申請開發案，適用86年7月16日下水道法施行細則第4條修正前之規定，爰開發時，貴府未「認定」要求設置專用下水道，斯時其污水係依建築技術規則規定，設置化糞池處理之，今自無另行設置專用下水道之問題。","refs":["A8","R4"]},{"id":"r73","agency":"內政部營建署","date":"95.11.20","docNo":"營署工程字第0950057235號","y":95,"src":"2018彙編","brief":"下水道法第8條規定：「政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設、管理之","text":"下水道法第8條規定：「政府機關或公營事業機構，新開發社區、工業區之專用下水道，由各該機關或機構建設、管理之。私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道」。依前開規定，新開發社區開發者自需設置專用下水道並管理之，社區開發完成，開發者將專用下水道移交為社區區分所有權人所有後，其區分所有權人自應負管理之責；未完成移交者，則仍由開發者管理。至公共下水道屬公共設施，由政府建設、管理之。","refs":["A8"]},{"id":"r74","agency":"內政部營建署","date":"96.8.20","docNo":"營署工程字第0960045137號","y":96,"src":"2018彙編","brief":"貴縣溪湖鎮興學自辦市地重劃及二林鎮豐田自辦市地重劃，是否應依下水道法第8條暨同法施行細則第4條之規定，施設專用下水道…","text":"貴縣溪湖鎮興學自辦市地重劃及二林鎮豐田自辦市地重劃，是否應依下水道法第8條暨同法施行細則第4條之規定，施設專用下水道乙節，請　貴府依本署93年7 月21日營署工程字第0932911807號函送「研商市地重劃地區污水處理廠設置相關事宜紀錄」（會議紀錄諒達）結論：「市地重劃地區按平均地權條例規定之程序辦理，重劃完成後，該地區設置專用下水道之原則，以個案考量，若達下水道法第8條及該法施行細則之規模者，需依規定設置專用下水道。」辦理。","refs":["A8"]},{"id":"r75","agency":"內政部","date":"96.9.11","docNo":"台內營字第0960805725號","y":96,"src":"2018彙編","brief":"依下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"依下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。同法施行細則第4條稱新開發社區為可容納500人以上居住或總計興建100住戶以上之社區，申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者。因學校產生之污水性質與社區類似，本案新增建大樓使用人數如達可容納500人以上或總計興建100戶以上之規模者，得由貴府本權責依前開規定指定為應設置專用下水道之場所。","refs":["A8"]},{"id":"r76","agency":"內政部","date":"96.9.21","docNo":"營署工程字第0960051164號","y":96,"src":"2018彙編","brief":"工業區之開發，應依下水道法第8條之規定，設置專用下水道，其目的旨在防治事業生產過程產生之廢(污)水，若區內採雨、污水…","text":"工業區之開發，應依下水道法第8條之規定，設置專用下水道，其目的旨在防治事業生產過程產生之廢(污)水，若區內採雨、污水分流制設施，則應依同法施行細則第16條之規定，雨水及污水應分別排洩於雨、污水下水道內；又同法施行細則第3條復稱，雨水下水道係指專供處理雨水之下水道，污水下水道指專供處理家庭污水及事業廢水之下水道，二者功能不同，不得混排。本案  貴府來函指稱，該工業區之雨水下水道系統雨水放流口排放之污(廢)水含有上游社區住戶產生流入之生活污水，顯已違反前開規定，應由轄區縣(市)環保及下水道主管機關依法查察取締。","refs":["A8","R3","R16"]},{"id":"r77","agency":"內政部","date":"97.2.20","docNo":"內授營工程字第0970801063號","y":97,"src":"2018彙編","brief":"新開發社區應依下水道法第8條之規定設置專用下水道，倘該專用下水道已與公共下水道完成銜接，則社區污水已排洩至公共系統處…","text":"新開發社區應依下水道法第8條之規定設置專用下水道，倘該專用下水道已與公共下水道完成銜接，則社區污水已排洩至公共系統處理，該社區已無單獨排放污水之污染問題，自得據以洽原列管單位辦理得否解除該專用下水道列管事宜。","refs":["A8"]},{"id":"r78","agency":"內政部","date":"97.3.12","docNo":"內授營工程字第0970801864號","y":97,"src":"2018彙編","brief":"依下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"依下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。其目的在處理污（廢）水、防治污染及維護環境衛生，故凡達一定規模者，應依規定設置專用下水道。　貴校學生人數若達該法施行細則第4條所稱新開發社區規模以上者，則其污染量相當，在公共下水道尚未到達前，主管機關自得本諸權責依前開規定，指定　貴校應設置專用下水道。","refs":["A8","R4"]},{"id":"r79","agency":"內政部","date":"97.5.8","docNo":"內授營工程字第0970803711號","y":97,"src":"2018彙編","brief":"工業區應依下水道法第8條第2項規定設置專用下水道，其目的為處理其區內廢(污)水，以防治水污染","text":"工業區應依下水道法第8條第2項規定設置專用下水道，其目的為處理其區內廢(污)水，以防治水污染。直轄市及縣(市)主管機關並得依下水道法所賦權責，指定工業區開發者或管理者為下水道機構，負責區內專用水道操作、維護等相關事宜。倘下水道排水區域內有若干工業區，其專用下水道之操作、維護係採聯合運作方式為之，則主管機關為劃分各工業區應辦理事項及權責，自得同時指定2個(含以上)下水道機構，惟該機構之權責事項應予明確分工。","refs":["A8"]},{"id":"r80","agency":"內政部","date":"97.8.28","docNo":"內授營工程字第0970807053號","y":97,"src":"2018彙編","brief":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。同法施行細則第4條稱「新開發社區」為可容納500人居住或總計興建100住戶以上之社區；「新開發工業區」為：（一）政府機關、公民營事業機構開發供事業設廠之地區。（二）事業於政府依法劃設供工業使用之土地設廠，其基地面積達2公頃以上者。依前開規定，專用下水道設置時機係申請開發時經主管機關認定其開發完成時，公共下水道尚無法容納其廢污水者。除前開情形者外，主管機關並得對產生污染量與前述規模相當且有污染之虞之地區或場所，指定其應設置專用下水道。本案有關「一定規模」之範圍，爰請　貴府本諸權責衡酌當地環境特性，依前開規定認定之。","refs":["A8"]},{"id":"r81","agency":"內政部","date":"98.5.8","docNo":"內授營工程字第0980804436號","y":98,"src":"2018彙編","brief":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。所稱專用下水道，該法第2條第4款指供特定地區場所使用而設置尚未納入公共下水道之下水道。","refs":["A8"]},{"id":"r82","agency":"內政部","date":"99.7.6","docNo":"內授營工程字第0990133280號","y":99,"src":"2018彙編","brief":"查下水道法施行細則第5條規定，「依本法第8條規定應設置專用下水道之地區或場所，於設置專用下水道前，應檢附專用下水道規…","text":"查下水道法施行細則第5條規定，「依本法第8條規定應設置專用下水道之地區或場所，於設置專用下水道前，應檢附專用下水道規劃及設計圖說等資料，申請該管主管機關核准…」。故下水道法第8條第1項所稱之政府機關或公營事業機構、新開發社區、工業區之專用下水道，自應從其規定辦理。","refs":["A8","R5"]},{"id":"r83","agency":"內政部","date":"100.1.21","docNo":"台內營字第1000800463號","y":100,"src":"2018彙編","brief":"下水道法第8條第2項規定私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條第2項規定私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。所稱經主管機關指定之地區或場所，指新開發社區、工業區以外，開發行為經當地下水道主管機關認為其規模非設置專用下水道，不足以處理其廢（污）水之地區或場所。","refs":["A8"]},{"id":"r84","agency":"內政部","date":"101.4.9","docNo":"內授營工程字第1010150285號","y":101,"src":"2018彙編","brief":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條第2項規定，私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。其目的在收集該地區之廢（污）水處理後排放，以防治污染。來函既稱以領有水污染防治許可證在案，其目的與專用下水道相同，如該防治措施已能將廢（污）水收集處理，則毋須再另設置專用下水道之必要。請　貴府就本案事實認定，本諸權責辦理。","refs":["A8"]},{"id":"r85","agency":"內政部","date":"101.7.26","docNo":"內授營綜字第1010258010號","y":101,"src":"2018彙編","brief":"查下水道法第8條規定，私人新開發社區應設置專用下水道","text":"查下水道法第8條規定，私人新開發社區應設置專用下水道；所稱新開發社區，依該法施行細則第4條規定為可容納500人以上居住或總計興建100戶以上之社區。另依非都市土地開發審議作業規範住宅社區專編第16點亦已明定：「閭鄰公園、社區道路應同意贈與鄉(鎮、市)，污水處理場應贈與直轄市、縣(市)。前項贈與應含土地及設施，但操作管理維護仍由社區管理委員會負責。」，旨揭經許可之非都市土地住宅社區如達前開下水道法規定，則應設置專用下水道，至有關該污水處理場贈與及操作維護管理權責事宜，該作業規範已明文規定，爰應從其規定辦理。","refs":["A8","R4"]},{"id":"r86","agency":"內政部","date":"102.4.29","docNo":"營署工程字第1020024513號","y":102,"src":"2018彙編","brief":"下水道法第8條規定，新開發社區應設置專用下水道","text":"下水道法第8條規定，新開發社區應設置專用下水道；該法施行細則第4條並規定申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水應設置專用下水道規模。故旨揭所詢，住宅區內興建個案符合前開規定者，即應設置專用下水道。","refs":["A8","R4"]},{"id":"r87","agency":"內政部","date":"102.11.20","docNo":"營署工程字第0980027965號","y":102,"src":"2018彙編","brief":"下水道法第8條規定應設置專用下水道場所","text":"下水道法第8條規定應設置專用下水道場所；同法施行細則第4條並規定其規模。來函所稱基地面積達2公頃以上工業區為何未設有污水下水道，宜先予釐清；至尚未有公共污水下水道可供排放廢(污)水，其符合放流水標準之事業廢(污)水經雨水下水道管理單位同意後即可為之。貴所如有執行疑義，查地方制度法第19條規定，下水道建設及管理屬地方自治事項，建議由當地下水道主管機關，衡酌實際情形訂定相關規定。","refs":["A8"]},{"id":"r88","agency":"內政部","date":"104.5.27","docNo":"營署工程字第1040032170號","y":104,"src":"2018彙編","brief":"下水道法第14條意旨公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備，惟下水道機構應…","text":"下水道法第14條意旨公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備，惟下水道機構應擇其損害最少之處所及方法並支付償金。如對處所及方法之選擇或支付償金仍有異議，方報請中央主管機關核定。","refs":["A8"]},{"id":"r89","agency":"內政部","date":"104.7.9","docNo":"營署工程字第1042910860號","y":104,"src":"2018彙編","brief":"下水道法第8條第2項前段規定，「私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道","text":"下水道法第8條第2項前段規定，「私人新開發社區、工業區或經主管機關指定之地區或場所，應設置專用下水道。」另非都市土地開發審議作業規範貳、專編第一編住宅社區第16條規定、「閭鄰公園、社區道路應同意贈與鄉(鎮、市)，污水處理場應贈與直轄市、縣(市)。前項贈與應含土地及設施，但操作管理維護仍由社區管理委員會負責。」前者立法原意為規定專用下水道設置權責，後者旨在規範非都市土地開發時，專用下水道設置後之權屬及管理權利義務，二者並無違悖。","refs":["A8"]},{"id":"r90","agency":"內政部","date":"89.11.2","docNo":"台內營字第8912055號","y":89,"src":"2018彙編","brief":"貴府為下水道法第3條規定之縣主管機關，所應辦理下水道事項，該法第6條並已明文規定","text":"貴府為下水道法第3條規定之縣主管機關，所應辦理下水道事項，該法第6條並已明文規定。工業區應由開發機構設置專用下水道並管理之。工業區服務中心既經貴府指定為下水道機構，則該中心應確實管理該區內下水道管理事項，惟貴府仍須負督導之責，如工業區內有違反下水道法規定事項時，該中心應檢具實情，函報貴府，由貴府依該法相關規定處分之。","refs":["A9"]},{"id":"r91","agency":"內政部","date":"91.1.10","docNo":"營署工程字第09310070號","y":91,"src":"2018彙編","brief":"依據經濟部工業局90年12月17日第字第09003527330號函說明一，促進產業升級條例第66條，工業主管機關開發…","text":"依據經濟部工業局90年12月17日第字第09003527330號函說明一，促進產業升級條例第66條，工業主管機關開發之工業區，其公共設施之污水處理設施，於必要時，得委託公民營事業建設管理。因此貴府得指定該工業區所委託之事業機構為下水道機構。","refs":["A9"]},{"id":"r92","agency":"內政部營建署","date":"91.4.15","docNo":"營署工程字第0910005484號","y":91,"src":"2018彙編","brief":"下水道法第六條規定，縣主管機關辦理事項包括第4款所列縣（鎮、市）下水道建設與管理之監督及輔導、第五款所稱有關縣下水道事宜等項","text":"下水道法第六條規定，縣主管機關辦理事項包括第4款所列縣（鎮、市）下水道建設與管理之監督及輔導、第五款所稱有關縣下水道事宜等項。依上開規定，凡縣轄區內有關下水道諸事宜，均為縣主管機關應辦理事項。查新竹工業區雖為經濟部所屬，惟位處新竹縣境，貴府依法仍負監督與輔導之責，故本案仍應由貴府本諸權責辦理。","refs":["A9"]},{"id":"r93","agency":"內政部","date":"91.6.26","docNo":"營署工程字第0910036044號","y":91,"src":"2018彙編","brief":"下水道法第3條規定，該法主管機關在縣（市）為縣（市）政府，台北水源特定區位處台北縣境，故該水源特定區範圍之下水道主管…","text":"一、下水道法第3條規定，該法主管機關在縣（市）為縣（市）政府，台北水源特定區位處台北縣境，故該水源特定區範圍之下水道主管機關為台北縣政府，依據台北縣政府環境保護局91年6月7日北環下字第0910034937號函說明，台北水源特定區下水道業務，該府已於91年2月15日公告，指定經濟部台北水源特定區管理局為該特定區之污水下水道機構，負責污水下水道建設與管理事項及經下水道主管機關核定之專用下水道系統內部建築物納管部份之總量控管。而專用下水道系統，現階段由台北縣政府環境保護局為業務管理機關。\n二、至花園新城新開發社區專用下水道問題，查下水道法第8條及該施行細則第4條之規定，其應設置專用下水道，處理該社區污水，若有新開發者欲於該社區內開發，可與該社區專用污水下水道管理者洽商污水處理問題，若該污水處理廠容量飽和或其他因素無法接納新增污水，則原開發者可擴充原污水處理廠容量或由新開發者自行新建專用下水道處理，俾符合下水道法之規定。","refs":["A9"]},{"id":"r94","agency":"內政部","date":"92.3.12","docNo":"營署工程字第0920003853號","y":92,"src":"2018彙編","brief":"貴府為下水道法縣主管機關，縣轄下水道之建設、管理、監督、輔導，自可依權責指定委託工業區專用下水道系統之管理機構為「下水道機構」","text":"貴府為下水道法縣主管機關，縣轄下水道之建設、管理、監督、輔導，自可依權責指定委託工業區專用下水道系統之管理機構為「下水道機構」。","refs":["A9"]},{"id":"r95","agency":"內政部","date":"92.5.16","docNo":"營署工程字第0920027429號","y":92,"src":"2018彙編","brief":"貴府為下水道法縣主管機關，花蓮縣轄內專用下水道之監督輔導，自應由貴府依法行政，並無專用下水道設置者為何之區分","text":"貴府為下水道法縣主管機關，花蓮縣轄內專用下水道之監督輔導，自應由貴府依法行政，並無專用下水道設置者為何之區分。故由貴府指定下水道機構管理工業區專用下水道，並無不當。","refs":["A9"]},{"id":"r96","agency":"內政部","date":"96.3.19","docNo":"台內營字第0960034664號","y":96,"src":"2018彙編","brief":"查「桃園縣下水道管理規則」第2條稱貴府為下水道主管機關，貴府工務局下水道課為管理機關，爰該管理機關是否為　貴府依下水…","text":"查「桃園縣下水道管理規則」第2條稱貴府為下水道主管機關，貴府工務局下水道課為管理機關，爰該管理機關是否為　貴府依下水道法第9條規定所設置之下水道機構？其負責管理範圍為何？如其管理下水道範圍未包括　貴轄內各工業區下水道，則　貴府為桃園縣下水道主管機關，依該法所賦權責，自得針對該工業區下水道管理需要，指定「林口工三工業區服務中心」為林口工三工業區下水道機構。至於涉及公權力行使之事項，諸如工業區內事業違反下水道法案件，應由該機構移送　貴府依法處分等，自不待言。另該受指定機構之應辦理事項，　貴府應予指明，俾資明確。","refs":["A9"]},{"id":"r97","agency":"內政部","date":"99.7.12","docNo":"台內營字第0990805527號","y":99,"src":"2018彙編","brief":"依據下水道法第25條規定，下水道機構擬訂下水道可容納排入之下水水質標準，並報請直轄市、縣（市）主管機關核定後公告","text":"依據下水道法第25條規定，下水道機構擬訂下水道可容納排入之下水水質標準，並報請直轄市、縣（市）主管機關核定後公告。旨揭所詢事項如包含前開標準，仍應由　貴府依前開規定辦理。","refs":["A9","A25"]},{"id":"r98","agency":"內政部","date":"102.11.4","docNo":"台內營字第1020811506號","y":102,"src":"2018彙編","brief":"大鵬灣風景特定區係依都市計畫法第14條規定劃設，位處屏東縣東港鎮及林邊鄉，區內「污二」系統主要為處理本特定區廢污水，…","text":"大鵬灣風景特定區係依都市計畫法第14條規定劃設，位處屏東縣東港鎮及林邊鄉，區內「污二」系統主要為處理本特定區廢污水，來函所詢其開發主體為何，查「變更大鵬灣風景特定區計畫（第一次通盤檢討）書」已明定主辦單位為大鵬灣管理處，則宜遵照計畫書內容執行。爰屏東縣政府指定　貴部觀光局大鵬灣風景特定區管理處為下水道機構，為下水道法第9條付予地方主管機關之權責，於法尚無不當。惟該府應將辦理事項及範圍與被指定為下水道機構協商確認後公告，以為日後執行之依據，涉公權力部分（如罰責、法令解釋等）仍應由該府辦理。","refs":["A9"]},{"id":"r99","agency":"內政部","date":"99.4.15","docNo":"內授營工程字第0990071921號","y":99,"src":"2018彙編","brief":"下水道法第13條規定下水道機構因工程上必要，得洽商有關主管機關使用河川、溝渠、橋梁、涵洞、堤防、道路、公園、綠地等，對補償與否並無規定","text":"一、下水道法第13條規定下水道機構因工程上必要，得洽商有關主管機關使用河川、溝渠、橋梁、涵洞、堤防、道路、公園、綠地等，對補償與否並無規定。至下水道機構因工程上之必要，在公、私有土地下埋設管渠或其他設備，該法第14條已明文規定應支付償金，自應從其規定辦理。\n二、前開支付償金標準，依據下水道法施行細則第10條規定，由直轄市、縣（市）主管機關訂之。查　貴府已訂有「臺北縣下水道工程使用私有土地補償標準」，所詢使用公有土地之補償標準，仍請　貴府本諸權責辦理。","refs":["A13","A14","R10"]},{"id":"r100","agency":"內政部","date":"75.7.18","docNo":"台內營字第426128號","y":75,"src":"2018彙編","brief":"下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，並應支付償金","text":"下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，並應支付償金。下水道法第14條第1項已有明文規定。本案埋設下水道管線穿越私有土地，應依上開規定辦理。","refs":["A14"]},{"id":"r101","agency":"內政部","date":"75.8.7","docNo":"台內營字第429433號","y":75,"src":"2018彙編","brief":"本案有關使用私人土地埋設暗管其施工處所、方法及支付償金請依下水道法施行細則第7、9條之規定辦理","text":"一、本案有關使用私人土地埋設暗管其施工處所、方法及支付償金請依下水道法施行細則第7、9條之規定辦理。但應擇其損害最少之處所及方法為之，並應支付償金。\n二、下水道法第14條所稱之上級主管機關係指下水道機構所隸屬之下水道主管機關。","refs":["A14","R7"]},{"id":"r102","agency":"內政部","date":"86.12.30","docNo":"台內營字第8690199號","y":86,"src":"2018彙編","brief":"下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，依下水道法第14條地1項之規定，其土地所有人、占有人…","text":"一、下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，依下水道法第14條地1項之規定，其土地所有人、占有人或使用人不得拒絕，但應擇其損害最少之處所及方法為之，並應支付償金；復依同法施行細則第7條之規定，下水道機構並應於工程計畫訂定後，將包括開工日期、施工範圍、方法、期間、償金及支付日期、領取償金時所應提示之證件等事項書面通知土地所有人、占有人或使用人。\n二、依前揭規定，下水道法具強制性，若土地所有人、占有人或使用人抗拒或拒領償金，致工程進行遭阻礙時，自得依提存法之規定將償金提存法院，並依法執行工程施工。","refs":["A14"]},{"id":"r103","agency":"內政部營建署","date":"91.1.18","docNo":"營署工程字第0910000341號","y":91,"src":"2018彙編","brief":"下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之所及方法為之，並應支付償金。本案私有地部份依前開規定，應予支付償金，至公地遭占用部份，則應先查明占用原因，依相關規定處理。","refs":["A14"]},{"id":"r104","agency":"內政部","date":"91.2.5","docNo":"內授營工程字第0910002811號","y":91,"src":"2018彙編","brief":"下水道法第2條第六款稱「用戶排水設備」，指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備","text":"下水道法第2條第六款稱「用戶排水設備」，指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備。復依同法第20條規定，用戶排水設備之管理、維護，由下水道用戶自行負責。依前開立法旨意，用戶排水設備係用戶為接用下水道所設置之設備，其物權屬用戶私有，應由用戶自行負責建設、管理。而該法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之所及方法為之，並應支付償金。查其立法原意，係指下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償。本案貴處在既成道路或計畫道路私有土地下埋設管渠或其他設備，係做為連接公共污水下水道非供公共使用之私有用戶排水設備，即便由下水道機構代為施工，並以公務預算支應，核與第14條之性質迴異，自無支付償金問題。","refs":["A14"]},{"id":"r105","agency":"內政部營建署","date":"91.4.29","docNo":"營署工程字第0910023571號","y":91,"src":"2018彙編","brief":"下水道法第14條：下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條：下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之所及方法為之，並應支付償金。前開法令尚無得以徵收為之之規定。","refs":["A14"]},{"id":"r106","agency":"內政部營建署","date":"91.9.27","docNo":"營署工程字第0910059466號","y":91,"src":"2018彙編","brief":"依據台灣省政府功能業務與組織調整暫行條例第7條規定「台灣省法規應配合業務調整修正或廢止，於修正、廢止前，其不牴觸本條例規定部份，繼續適用」","text":"依據台灣省政府功能業務與組織調整暫行條例第7條規定「台灣省法規應配合業務調整修正或廢止，於修正、廢止前，其不牴觸本條例規定部份，繼續適用」。查下水道法施行細則第10條業經本部於88年12月23日台內營字第8878333號令修正為：「本法第14條、第16條規定支付償金或補償，其標準由直轄市、縣（市）主管機關訂定之」。依前開規定，貴府應訂定前稱支付償金或補償標準，在尚未訂定前，前台灣省政府所訂「台灣省下水道工程使用土地支付支付償金或補償標準」仍可適用，惟貴府宜速依法訂定標準，以資適法。","refs":["A14","R14"]},{"id":"r107","agency":"內政部","date":"93.1.12","docNo":"營署工程字第0932900528號","y":93,"src":"2018彙編","brief":"下水道法第2條第6款稱「用戶排水設備」，指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備","text":"一、下水道法第2條第6款稱「用戶排水設備」，指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備。復依同法第20條規定，用戶排水設備之管理、維護，由下水道用戶自行負責。依前開意旨，「用戶排水設備」屬私有設備，不予補償，本部91年2月5日內授營工程字第0910002811號函已釋示在案。惟若係供公共使用之污水管線經私有地，自應依該法第14條給予補償。貴處施工之管線何者屬用戶排水設備，何者屬供公共使用之污水管線，應請本諸權責釐清，以免滋生補償爭議。\n二、至償金之支付時機，並無明文規定，請逕為處理。","refs":["A14"]},{"id":"r108","agency":"內政部","date":"93.7.22","docNo":"內授營工程字第0930008598號","y":93,"src":"2018彙編","brief":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。前開規定以在公、私有土地下埋設下水道管渠為限，而對支付償金有所異議時，需報請中央主管機關核定。本案係既成道路之排水改善工程，究係道路附屬設施或雨水下水道工程，貴府宜先釐清，若係屬既成道路之一部份，請參據大法官第440號解釋辦理。另本案係爭緣由為當事人不願以支付償金方式接受補償，尚非下水道法中央主管機關核定事項。","refs":["A14"]},{"id":"r109","agency":"內政部","date":"93.9.7","docNo":"內授營工程字第0930010400號","y":93,"src":"2018彙編","brief":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。本案系爭緣由為當事人不願以支付償金方式接受補償，尚非下水道法中央主管機關核定事項。惟既成道路埋設地下設施，涉及補償乙節，請參據大法官第440號解釋辦理。","refs":["A14"]},{"id":"r110","agency":"內政部營建署","date":"93.12.10","docNo":"營署工程字第0930075559號","y":93,"src":"2018彙編","brief":"下水道法第14條規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之」。查本案係爭為土地所有人等希以徵收方式辦理，非對處所及方法之選擇或支付償金有異議，尚非中央主管機關核定範疇。至其拒領補償費，宜另依提存法及相關法令辦理。","refs":["A14"]},{"id":"r111","agency":"內政部營建署","date":"94.4.18","docNo":"營署工程字第第0940019351號","y":94,"src":"2018彙編","brief":"下水道法第3條規定：本法所稱中央主管機關在中央為內政部","text":"下水道法第3條規定：本法所稱中央主管機關在中央為內政部。故凡本法條文「中央主管機關」皆係「內政部」。","refs":["A14"]},{"id":"r112","agency":"內政部營建署","date":"94.11.1","docNo":"營署工程字第0940054742號","y":94,"src":"2018彙編","brief":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。依前述規定，本案於私有土地施設公共雨水下水道（用戶排水設備除外），自應給予償金。至償金標準，請貴府依該法施行細則第10條規定訂定之。","refs":["A14"]},{"id":"r113","agency":"內政部營建署","date":"95.3.22","docNo":"營署工程字第0950033749號","y":95,"src":"2018彙編","brief":"下水道法第14條規定：下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定：下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。依前開規定，本案應給予土地所有權人補償。惟據陳情人所述，係請依法辦理土地徵收或協議價購，非對處所及方法之選擇或支付償金有異議，非屬本部依上開規定核定範疇。","refs":["A14"]},{"id":"r114","agency":"內政部營建署","date":"95.6.27","docNo":"營署工程字第0950031455號","y":95,"src":"2018彙編","brief":"下水道法第14條規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。」，本案於私有土地下埋設雨水下水道暗渠，若不影響該土地之利用，尚無取得土地之必要，宜依上開規定為之。","refs":["A14"]},{"id":"r115","agency":"內政部營建署","date":"95.10.24","docNo":"營署工程字第0950054284號","y":95,"src":"2018彙編","brief":"下水道法第14條規定：下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定：下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。依前開規定，本案陳情人不得拒絕，但應支付其償金。惟其訴請徵收土地之系爭乙節，尚非「中央主管機關核定」範疇。","refs":["A14"]},{"id":"r116","agency":"內政部營建署","date":"95.10.27","docNo":"營署工程字第0950052287號","y":95,"src":"2018彙編","brief":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"一、下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。所稱支付償金應指下水道機構所為之下水道工程，方予支付。貴府稱非下水道機構施工之既成道路或其他現有巷道之側溝，應屬既成道路或現有巷道之附屬設施，其改善更新是否應支付償金乙節，自非下水道法解釋範疇。惟若該側溝因都市排水需要，經貴府納為雨水下水道之一環，由下水道機構統籌管理維護，則其改善更新，涉及下水道法第14條所稱之行為，應依該規定補償。\n二、另下水道法第16條規定，下水道機構因勘查、測量、施工或維護下水道，臨時使用公、私土地時，土地所有人、占有人或使用人不得拒絕。但提供使用之土地因而遭受損害時，應予補償。意指提供使用之土地因勘查、測量、施工或維護下水道所遭「損害」之補償行為，本案所稱既有之側溝如亦經貴府認定為雨水下水道，則其有上開損害之事實時，自適用損害補償之規定，非以工程材質變更及擴大與否認定之。","refs":["A14","A16"]},{"id":"r117","agency":"內政部","date":"96.3.16","docNo":"台內營字第0960033586號","y":96,"src":"2018彙編","brief":"下水道法第14條規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。」依上開規定，土地所有人、占有人或使用人對處所及方法之選擇或支付償金有異議時，由中央主管機關核定。本案○○○先生提具異議書，言明其決定以租約方式出租，不接受使用土地支付償金發放方式，核與下水道法規定內容不符，尚非本部核定範疇。","refs":["A14"]},{"id":"r118","agency":"內政部","date":"96.3.22","docNo":"台內營字第0950033749號","y":96,"src":"2018彙編","brief":"下水道法第14條規定：下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定：下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。依前開規定，本案應給予土地所有權人補償。惟據陳情人所述，係請依法辦理土地徵收或協議價購，非對處所及方法之選擇或支付償金有異議，非屬本部依上開規定核定範疇。","refs":["A14"]},{"id":"r119","agency":"內政部","date":"97.4.23","docNo":"內授營工程字第0970803309號","y":97,"src":"2018彙編","brief":"有關施作用戶排水設備在既成道路或計畫道路私有土地下埋設管渠或其他設備連接至公共污水下水道，是否支付償金乙案，查本部業…","text":"一、有關施作用戶排水設備在既成道路或計畫道路私有土地下埋設管渠或其他設備連接至公共污水下水道，是否支付償金乙案，查本部業於91年2月5日以內授營工程字第0910002811號函（諒達）釋有案，先予敘明。\n二、本案　貴府函稱「用戶接管」應屬下水道用戶排水設備，所詢為辦理該設備工程，於計畫道路未徵收私有土地上埋設之用戶連接管，如係為供公共使用之必要管渠，自得依前開規定，支付償金以為補償。","refs":["A14"]},{"id":"r120","agency":"內政部","date":"97.8.28","docNo":"內授營工程字第0970807026號","y":97,"src":"2018彙編","brief":"查下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"一、查下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。前開旨對供公共使用之污水管線經公、私有土地，自應給予補償。\n二、同法第2條第6款稱「用戶排水設備」，指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備；該法第20條復稱，用戶排水設備之管理、維護，由下水道用戶自行負責。本部於91年2月5日以內授營工程字第0910002811號函（諒達）釋有案，意旨：用戶排水設備屬私有設備，現行雖由政府代為施作，並以公務預算支應，核與第14條之性質迥異，自無支付償金問題；惟土地所有人、占有人或使用人非該用戶排水設備使用者，自得給予補償。","refs":["A14"]},{"id":"r121","agency":"內政部","date":"98.4.3","docNo":"內授營工程字第0980802655號","y":98,"src":"2018彙編","brief":"下水道屬公共設施之一環，攸關大眾生活環境品質，故下水道法第14條爰有公、私有土地所有人、占有人或使用人不得拒絕下水道…","text":"下水道屬公共設施之一環，攸關大眾生活環境品質，故下水道法第14條爰有公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備之強制性規定，惟應支付償金，以維其權益。該法施行細則第7條規定，前開所為之土地使用，下水道機構應於工程計畫訂定後，以書面通知當事人，包括償金支付日期及領取時應提示之證件等事項。至所詢償金支付時機，該法尚無規定，貴府得另依行政程序法及提存法等規定視個案事實，本諸權責逕行處分。","refs":["A14","R7"]},{"id":"r122","agency":"內政部","date":"98.4.10","docNo":"內授營工程字第0980060084號","y":98,"src":"2018彙編","brief":"下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理","text":"一、下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理。所稱專業技師依該法施行細則第13條，指依技師法規定取得環境(衛生)工程、土木或水利科之工業技師。所詢下水道用戶排水設備之設計人、監造人與建築法規範之建築物「設計人」、「監造人」資格是否同為建築師執行乙節，下水道法第2條第6款稱「用戶排水設備」為下水道用戶因接用下水道以排洩下水所設之管渠及有關設備，尚非建築物範疇，查建築師非技師法所稱技師，故有關該設備之規劃、設計及監造自應由前開專業技師辦理。\n二、惟下水道法施行細則第18條規定，五層以下非供民眾使用之「新建建築物」，其下水道設備得由該建築物之建築師「併同」設計之，則下水道設備由建築師設計時機，僅指新建建築物於設計階段，併同設計之。","refs":["A14","A17","R7","R13","R18"]},{"id":"r123","agency":"內政部","date":"99.8.11","docNo":"內授營工程字第0990806804號","y":99,"src":"2018彙編","brief":"查下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"查下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方式為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。\n本案系爭為陳情人希以徵收其土地之方式辦理，非對施工處所及方法之選擇、償金提具異議，本部99年6月23日台內營字第0990804933號函(諒達)業說明在案。","refs":["A14","R10"]},{"id":"r124","agency":"內政部","date":"99.12.1","docNo":"台內營字第0990809965號","y":99,"src":"2018彙編","brief":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。依前開意旨，僅於對前開施工處所、方法之選擇或支付償金額度發生異議時，始由中央主管機關核定。查本案系爭為土地所有人希以徵收其土地之方式辦理，非對償金之額度提具異議，爰非屬本部依前開規定核定範疇。","refs":["A14"]},{"id":"r125","agency":"內政部","date":"100.3.18","docNo":"台內營自第1000801952號","y":100,"src":"2018彙編","brief":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。復依同法施行細則第7條規定，依本法第14條規定使用公、私有土地時，下水道機構應於工程計畫訂定後，以書面通知土地所有人、占有人或使用人，緣亦需土地權屬確定。","refs":["A14"]},{"id":"r126","agency":"內政部","date":"101.10.23","docNo":"內授營工程字第1010810224號","y":101,"src":"2018彙編","brief":"下水道法第14條規定意旨公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備，如對處所及…","text":"下水道法第14條規定意旨公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備，如對處所及方法之選擇或支付償金有異議，應報請中央主管機關核定。惟依據來函所稱，系爭為土地所有人希以徵收其土地之方式辦理，非對處所及方法之選擇或支付償金提具異議，核與前開規定不符，非屬本部核定範疇。","refs":["A14"]},{"id":"r127","agency":"內政部","date":"102.1.11","docNo":"台內營字第1020800109號","y":102,"src":"2018彙編","brief":"下水道法第14條規定意旨公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備，惟下水道機構應支付償金","text":"下水道法第14條規定意旨公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備，惟下水道機構應支付償金。與大法官解釋第440號並無相悖。貴局水利工程處因工程上之必要，於旨揭土地下所為公共管線部份之埋設，並擬擇其損害最少之處及方法為之且支付償金，則旨揭土地所有人不得拒絕。惟應依下水道法施行細則第7條規定，備齊相關文件，書面通知該土地所有人，並依行政執行法相關規定處理。","refs":["A14","R7"]},{"id":"r128","agency":"內政部","date":"102.3.11","docNo":"內授營工程字第1020122906號","y":102,"src":"2018彙編","brief":"本案所稱用戶接管工程，其經過私有土地之補償事宜，請悉依本部91年2月5日內授營工程字第0910002811號函及本部…","text":"本案所稱用戶接管工程，其經過私有土地之補償事宜，請悉依本部91年2月5日內授營工程字第0910002811號函及本部營建署94年2月14日營署工程字第0942902317號函送94年2月3日「研商埋設污水下水道用戶排水設備管渠經私有土地是否應予補償事宜」會議結論辦理。","refs":["A14"]},{"id":"r129","agency":"內政部","date":"102.9.17","docNo":"內授營工程字第1020306736號","y":102,"src":"2018彙編","brief":"下水道法第14條規定意旨，供公共使用之污水管線經私有地，應給予補償","text":"下水道法第14條規定意旨，供公共使用之污水管線經私有地，應給予補償。來函所詢因旨揭地號於88年經高雄地方法院辦理假扣押登記及98年高雄稅稅捐稽徵處實施囑託禁止處分，且該土地所有權人已過世，其償金支付對象乙節，查尚非下水道法解釋範疇，建請依其他法令規定辦理。","refs":["A14"]},{"id":"r130","agency":"內政部","date":"102.10.1","docNo":"內授營工程字第1020810357號","y":102,"src":"2018彙編","brief":"下水道法第14條規定意旨公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備，如對處所及…","text":"下水道法第14條規定意旨公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備，如對處所及方法之選擇或支付償金有異議，應報請中央主管機關核定。查本案係爭為異議人希以徵收其土地之方式辦理，非對處所及方法之選擇或支付償金提具異議，與下水道法規定不符，非屬本部依前開規定之範疇。","refs":["A14"]},{"id":"r131","agency":"內政部","date":"102.11.15","docNo":"內授營工程字第1020348558號","y":102,"src":"2018彙編","brief":"下水道法第14條意旨下水道機構在公、私有土地下埋設管渠或其他設備，應支付償金","text":"下水道法第14條意旨下水道機構在公、私有土地下埋設管渠或其他設備，應支付償金。惟旨揭所詢是否可比照土地收條例第26條規定設立補償費保管專戶辦理乙節，查下水道法尚無相關規定，請貴府本諸權責卓處。","refs":["A14"]},{"id":"r132","agency":"內政部","date":"102.11.27","docNo":"內授營工程字第1020354627號","y":102,"src":"2018彙編","brief":"下水道法第14條意旨下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受…","text":"下水道法第14條意旨下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償；其有異議，方由中央主管機構核定。另查該法第20條規定，用戶排水設備之管理、維護，由下水道用戶自行負責，爰用戶排水設備屬用戶接用下水道之私有設備，尚無前開核定之適用。本案補償範圍究係屬供「公共使用」之管渠或其他設備或用戶排水設備，請貴局補充說明。","refs":["A14","A20"]},{"id":"r133","agency":"內政部","date":"104.1.19","docNo":"營署工程字第1040001193號","y":104,"src":"2018彙編","brief":"下水道法第14條意旨下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受…","text":"下水道法第14條意旨下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償。另查該法第20條規定，用戶排水設備之管理、維護，由下水道用戶自行負責，爰用戶排水設備屬用戶接用下水道之私有設備，不予補償。惟貴府應本諸權責釐清公共使用之管線與用戶排水設備，以免滋生補償爭議。","refs":["A14"]},{"id":"r134","agency":"內政部","date":"104.1.23","docNo":"內授營工程字第1040402352號","y":104,"src":"2018彙編","brief":"查下水道法第14條意旨為下水道機構在公、私有土地下埋設管渠或其他設備，應給予償金","text":"查下水道法第14條意旨為下水道機構在公、私有土地下埋設管渠或其他設備，應給予償金；另查同法施行細項第7條第1項規定下水道機構應於工程計畫訂定後，以書面通知土地所有人、占有人或使用人；第2項規定通知書應記載事項第7款及有償金支付日期。依據地方制度法第18條及第19條規定，下水道建設及管理屬地方自治事項，有關償金支付日期，請貴署各分署、辦事處與宜蘭縣政府協商為之。","refs":["A14"]},{"id":"r135","agency":"內政部","date":"105.1.11","docNo":"營署工程字第1043040599號","y":105,"src":"2018彙編","brief":"（一）下水道法第14條疑義：","text":"（一）下水道法第14條疑義：\n1.下水道法第14條前段規定，「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方式為之，並應支付償金。」其所稱之「必要」指下水道工程依據下水道工程設施標準辦理規劃、設計，實無其他適合路線或位置可供埋設管渠或其他設備。另查該法第20條規定，用戶排水設備之管理、維護，由下水道用戶自行負責，用戶排水設備屬用戶接用下水道之私有設備，尚無前開規定之適用。\n2.下水道機構遇有下水道法第14條需支付償金情事時，應依同法施行細則第7條規定辦理。下水道機構如未依前開規定辦理，下水道法雖無相關規範，惟仍應依行政程序法等相關規定辦理。\n（二）下水道法第20條規定，用戶排水設備之管理、維護由下水道用戶自行負責，其意旨為用戶排水設備屬私有設備。惟為提升用戶接管普及率，目前由政府編列預算代民眾施工。各直轄市、縣(市)政府施工時，常遇民眾將原應留設之防火空間私自增加建築使用空間，孳生施工空間不足情事，爰訂有相關規定規範施作用戶排水設備時，用戶應配合留設足夠空間俾利施工及埋設相關設備。如遇有留設空間不足之疑義，則宜由當地主管機關衡酌個案情形辦理。\n（三）「…是否須全體住戶（每一層）均簽屬“申請接管及施工同意書”…」1節，查本署施工規範第0254章污水下水道用戶接管工程埋設施工第3.1.5節規定「應召開施工說明會，以契約所列圖示範圍接管戶全數接管為原則，協助進行用戶接管宣導作業及分發接管通知書」，另查同章第3.3.2節規定「各建物均須於施工前請住戶(至少為一樓住戶)填具「污水下水道用戶接管申請表」，是以如用戶接管工程施作須進入一樓屋內打除下方化糞池，應至少請一樓住戶簽署用戶接管申請表，惟實際操作規定，仍應依原採購機關招標文件規定為宜。\n（四）有關「……鑑界費用是否納入工程款項中(政府支付)？抑或是由住戶自行支付？」1節，因申請土地鑑界需為土地所有權人辦理，爰應由民眾自行付費向地政單位申請。\n（五）查本署施工規範第02534章「污水下水道用戶接管工程埋設施工」第3.6.7節規定，「……遇有須通過住戶牆壁或地板時，應儘量避免破壞主結構物，如因事實上不可避免者，應先徵得用戶及工程司同意、並以最小量之破壞為原則，……」，故施作原則應避免破壞主結構物，若須破壞須徵得用戶同意。\n（六）依行政院公共工程委員會100年1月28日工程企字第10000040880號函，機關訂定採購契約，以採該會訂頒之政府採購契約範本為原則，並就各採購案特性採行相關因應措施，檢附104年5月27日修正工程契約範本1份供參。下載網址：行政院公共工程委員會首頁 / 法令規章 / 政府採購法規 / 招標相關文件及表格。\n（七）依據地方制度法第18條及第19條規定，下水道建設及管理屬地方自治事項。臺北市政府及新北市政府分別訂有「臺北市下水道管理自治條例」及「新北市下水道管理規則」以管理其所屬下水道，檢附條文各1份供參。\n（八）有關「板橋地區污水下水道系統第二期工程」第一標文件提送情形，細部設計資料新北市政府於101年4月18日北水污計字第1011603619號函送本署，契約書資料新北市政府於101年10月11日北水污計字第1012705882號函送本署，惟其契約書、設計成果核備及相關進度資料因係屬新北市政府水利局本權責辦理，建請洽原採購機關提供為宜。","refs":["A14","A20"]},{"id":"r136","agency":"內政部","date":"105.3.15","docNo":"內授營工程字第1050018501號","y":105,"src":"2018彙編","brief":"按下水道法第14條第1項前段規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"按下水道法第14條第1項前段規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。查臺中市政府已依下水道法施行細則第10條定有「臺中市下水道工程使用土地支付償金及補償費標準」，已建立相當之補償機制，且依法有據，本案核依前開標準辦理。","refs":["A14","R10"]},{"id":"r137","agency":"內政部","date":"105.5.20","docNo":"營署工程字第1052907784號","y":105,"src":"2018彙編","brief":"查下水道法第14條規定意旨，下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，…","text":"查下水道法第14條規定意旨，下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，予以支付償金，以為補償。另查下水道法第2條第6款規定，用戶排水設備指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備；同法第20條規定，用戶排水設備之管理、維護，由下水道用戶自行負責，爰用戶排水設備屬私有設備，尚非下水道法第14條適用範疇。","refs":["A14","A23"]},{"id":"r138","agency":"內政部","date":"105.7.4","docNo":"內授營工程字第1050809459號","y":105,"src":"2018彙編","brief":"依據下水道法第14條規定意旨，公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備，惟下…","text":"依據下水道法第14條規定意旨，公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設管渠或其他設備，惟下水道機關應擇其損害最少之處所及方法並支付償金。如對處所及方法之選擇或支付償金仍有異議，應報請中央主管機關核定。查貴府依下水道法施行細則第10條訂有「花蓮縣下水道工程使用土地支付償金及補償費標準」，已建立補償機制依法有據，本案核依前開標準辦理。","refs":["A14"]},{"id":"r139","agency":"內政部","date":"106.8.17","docNo":"台內營字第1060811816號","y":106,"src":"2018彙編","brief":"查下水道法第14條第1項規定，「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"查下水道法第14條第1項規定，「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。」下水道機構倘係為埋設供公共使用之管渠或其他設備，亦不影響該土地之利用，尚無需取得土地之必要，宜依上開規定為之。","refs":["A14"]},{"id":"r140","agency":"內政部","date":"106.9.7","docNo":"內授營工程字第1060063948號","y":106,"src":"2018彙編","brief":"查下水道法第14條第1項規定，「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"查下水道法第14條第1項規定，「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。」其意旨係規定水道埋設供公共使用之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償。\n另查下水道法第20條規定，「用戶排水設備之管理、維護，由下水道用戶自行負責。」依其意旨，用戶排水屬私有設備。依據貴府上開函號稱，本案係用戶排水設備之埋設，尚難謂具公共使用性質，爰無下水道法第14條之適用。","refs":["A14","A20"]},{"id":"r141","agency":"內政部","date":"106.11.28","docNo":"內授營環字第1060818433號","y":106,"src":"2018彙編","brief":"依據下水道法第14條第1項規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人…","text":"依據下水道法第14條第1項規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕，但應擇其損害最少之處所及方法為之，並應支付償金。旨揭工程G32～G36工作井管線穿越私有土地，埋設路徑既經貴府檢討為損害最少之方法，應依前開規定辦理。","refs":["A14"]},{"id":"r142","agency":"內政部營建署","date":"84.8.10","docNo":"營署公字第52820號","y":84,"src":"2018彙編","brief":"有關本部84年7月14日台（84）內營字8480080號函示「本案台北市政府辦理公共污水下水道工程施工時，與瓦斯管線…","text":"有關本部84年7月14日台（84）內營字8480080號函示「本案台北市政府辦理公共污水下水道工程施工時，與瓦斯管線牴觸，瓦斯管線需配合拆遷時，其拆遷經費分擔比例為污水管線單位負擔三分之一，瓦斯管線單位負擔三分之二」係指永久拆遷而言，至於其臨時拆遷之經費分擔方式理應由污水管線單位全額負擔較屬合理。","refs":["A15"]},{"id":"r143","agency":"內政部","date":"85.10.18","docNo":"台內營字第8585932號","y":85,"src":"2018彙編","brief":"案經本署於85年10月4日邀請經濟部等相關單位會商，獲致結論如下：「一、今後於辦理各公共污水下水道工程施工與瓦斯管線…","text":"案經本署於85年10月4日邀請經濟部等相關單位會商，獲致結論如下：「一、今後於辦理各公共污水下水道工程施工與瓦斯管線牴觸，需瓦斯管線配合拆遷時，其拆遷經費分攤比例為污水管線單位負擔三分之一，瓦斯管線單位負擔三分之二。二、請地方政府道路主管機關依相關規定確實審核各管線單位所送其管線埋設資料，其確實督導其埋設位置，以免造成以後污水管線施工時之困擾。」","refs":["A15"]},{"id":"r144","agency":"內政部","date":"85.12.24","docNo":"台內營字第8582299號","y":85,"src":"2018彙編","brief":"自來水管線部分：由污水下水道施工單位負擔三分之一，自來水事業單位負擔三分之二，惟如省（市）政府已有協議成立者，得依原協議辦理","text":"一、自來水管線部分：由污水下水道施工單位負擔三分之一，自來水事業單位負擔三分之二，惟如省（市）政府已有協議成立者，得依原協議辦理。\n二、電力、電信及油管部分：由污水下水道施工單位負擔三分之一；電力、電信及油管事業單位負擔三分之二。\n三、軍警通訊管線部分，由污水下水道施工單位全額負擔。","refs":["A15"]},{"id":"r145","agency":"內政部營建署","date":"86.4.25","docNo":"營署公字第07465號","y":86,"src":"2018彙編","brief":"本案雨水下水道工程不論其為併入道路工程預算內施工或單獨成立預算施工，均可依行政院84年4月11日台84交字第0118…","text":"一、本案雨水下水道工程不論其為併入道路工程預算內施工或單獨成立預算施工，均可依行政院84年4月11日台84交字第01185號函示，歸類為「公共設施管線挖掘道路注意要點」第2點所述道路之改善工程，並依同要點第9點規定，於已有管線必須遷移時，管線機構應立即予以配合並自行負擔全部遷移費用。\n二、另依行政院86年4月1日台86交字第12662號函准交通部所報「公共設施管線工程挖掘道路注意要點」第9條修正案規定：「既有管線必須永久遷移者，管線單位應自行負擔全部遷移費用；屬臨時遷移時，由道路施工單位全額負擔遷移、搶修費。」前述院准「公共設施管線工程挖掘道路注意要點」第9條修正案，其實施日期待交通部決定後，由該部行文各單位據以辦理。","refs":["A15"]},{"id":"r146","agency":"內政部營建署","date":"83.7.18","docNo":"營署公字第12178號","y":83,"src":"2018彙編","brief":"下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理","text":"下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理。同法施行細則第13條稱前項專業技師，指依技師法規定取得環境（衛生）工程、土木或水利科之工業技師。","refs":["A17"]},{"id":"r147","agency":"內政部營建署","date":"83.11.22","docNo":"營署公字第18253號","y":83,"src":"2018彙編","brief":"經濟部80年4月19日經（80）工字第○15522號令發布「各科技師執業範圍，環境工程科執業範圍中之「水處理」乙項，…","text":"一、經濟部80年4月19日經（80）工字第○15522號令發布「各科技師執業範圍，環境工程科執業範圍中之「水處理」乙項，與污水（衛生）下水道部分相關故污水（衛生）下水道工程可視為「環境工程」之一部分，在未設有下水道工程技師前，下水道工程資歷宜可視為環境工程之服務年資。\n二、污水（衛生）下水道工程含污水收集管線、抽（揚）水站、污水處理廠等規劃、設計、施工及營運管理，所涉範圍包括土木、水利、化學、生物、機電……等專門學科，非水處理乙項所能囊括。日後台灣地區下水道建設相關業務，無論於政府或民間勢將日益繁重，故有必要增列下水道工程技師，以加強專業人力、加速推動建設。\n三、另台灣地區地狹人稠，水資源有限，如何規劃水源保護區之合理管理與開發，淨水技術之研究發展供給民眾良好品質之自來水為未來之需求趨勢，亦有必要增設自來水技師，以應所需。","refs":["A17"]},{"id":"r148","agency":"內政部營建署","date":"84.7.10","docNo":"營署公字第12650號","y":84,"src":"2018彙編","brief":"下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理","text":"下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理。同法施行細則稱「專業技師」，指依技師法規定取得環境（衛生）工程、土木或水利科之工業技師。前揭條文意指下水道之規劃、設計及監造，亦得委由前開專業技師辦理，而受委託之技師須經「登記開業」。","refs":["A17"]},{"id":"r149","agency":"內政部","date":"88.7.30","docNo":"台內營字第8806175號","y":88,"src":"2018彙編","brief":"下水道法第17條規定：「下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理","text":"一、下水道法第17條規定：「下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理。其由政府機關自行規劃、設計及監造者，應由符合中央主管機關規定之技術人員擔任之」下水道工程包括污水處理廠、管線、機電設備等，其相關專業包括土木、水利、環境工程、機械、化工等，故所稱「技術人員」係指政府機關依「公務人員任用法」、「技術人員任用條例」、「專門職業及技術人員轉任公務人員條例」、「聘用人員聘用條例」任用之上述專業人員。\n二、另下水道之操作、維護屬慝定之技能，依下水道法第18條規定，應由技能檢定合格人員擔任之。而技能檢定辦法屬技能檢定事宜，依職業訓練法第31條規定，為提高技能水準，建立證照制度，應由技能檢定主管機關（行政院勞工委員會）辦理技能檢定，並依該法第33條訂定辦理技能檢定及發證辦法，為免法規重複，並符合統一證照之原則，本部74年12月30日台內營字第367972號函報行政院75年2月1日台75內2283號函核示同意下水道法第18條所稱技能檢定辦法不予訂定。前開規定於專用下水道之規劃、設計及監造、操作、維護均適用之。","refs":["A17"]},{"id":"r150","agency":"內政部營建署","date":"90.12.14","docNo":"台內營字第9017265號","y":90,"src":"2018彙編","brief":"下水道法第17條規定，下水道之規劃、設計、監造，得委託登記開業之有關專業技師辦理","text":"下水道法第17條規定，下水道之規劃、設計、監造，得委託登記開業之有關專業技師辦理。同法施行細則第13條稱該「專業技師」指依技師法規定取得環境（衛生）工程、土木或水利科之工業技師。依前開解釋，土木工程技師得接受委託辦理下水道之規劃、設計、監造工作。","refs":["A17"]},{"id":"r151","agency":"內政部營建署","date":"92.12.12","docNo":"營署工程字第0920075697號","y":92,"src":"2018彙編","brief":"新開發社區應依下水道法第8條設置專用下水道並管理之，完工後並應經下水道主管機關查驗合格使得核發建築物使用執照，該法第…","text":"新開發社區應依下水道法第8條設置專用下水道並管理之，完工後並應經下水道主管機關查驗合格使得核發建築物使用執照，該法第17條並規定下水道設施之操作、維護應由技能檢定合格人員擔任之。依前開規定，社區之興建及該專用下水道之操作維護等自應遵照之。而水污染防治法第21條、22條令規定污水下水道應設置廢（污）水處理專責單位或人員、並應申報其操作、放流水水質水量及環境保護主管機關進入污水下水道檢查處理、排放等事項。法令既有規定，自應依規定辦理，二者並無競合問題，至罰則方面，下水道法尚無相關規定。","refs":["A17"]},{"id":"r152","agency":"內政部營建署","date":"93.1.9","docNo":"營署工程字第0920082105號","y":93,"src":"2018彙編","brief":"下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理","text":"下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理。同法施行細則第13條稱「專業技師」，指依技師法規定取得環境（衛生）工程、土木或水利科之工業技師。有關技師辦理簽證之規定，並非下水道法規範範疇，請洽技師簽證主管機關辦理。","refs":["A17"]},{"id":"r153","agency":"內政部營建署","date":"93.5.28","docNo":"營署建管字第0930035655號","y":93,"src":"2018彙編","brief":"按下水道法第17條規定：「下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理……」，惟「營造業係指經向中央或…","text":"按下水道法第17條規定：「下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理……」，惟「營造業係指經向中央或直轄市、縣（市）主管機關辦理許可、登記，承攬營繕工程之廠商」及「專任工程人員係指受聘於營造業之技師或建築師，擔任其所承攬工程之施工技術指導及施工安全人員」，分別為營造業法第3條第2款及第9款所明定。又營造業專任工程人應負責辦工作，無涉下水道法第17條及其施行細則第13條之規定。","refs":["A17"]},{"id":"r154","agency":"內政部營建署","date":"93.9.23","docNo":"營署工程字第號0930060230","y":93,"src":"2018彙編","brief":"建築物內之給排水設備屬建築物範疇，由建築師依據建築技術規則設計，為便於公共下水道之接管作業，應將雨、污水分流設置","text":"建築物內之給排水設備屬建築物範疇，由建築師依據建築技術規則設計，為便於公共下水道之接管作業，應將雨、污水分流設置。建築物外，連接下水道之下水道管材、陰井、人孔及銜接建築物之污水管線之用戶排水設備，均屬下水道範疇，除下水道法施行細則第18條規定，五層以下非供公眾使用之新建建築物，其下水道設備得由該建築物之建築師併同設計外，悉依下水道法第17條規定，得由登記開業之有關專業技師辦理。依前開規定，凡建築物部份，均由建築師設計之，本署86年5月16日營署公字第09280號函釋專用下水道處理設施之鋼筋結構部份，屬下水道設施之一環，由專業技師辦理乙節，與前稱原則並無相悖。","refs":["A17","R18"]},{"id":"r155","agency":"內政部","date":"100.10.3","docNo":"台內營字第1000192492號","y":100,"src":"2018彙編","brief":"查下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理","text":"查下水道法第17條規定，下水道之規劃、設計及監造，得委託登記開業之有關專業技師辦理；同法施行細則第13條稱前開業專業技師，指依技師法規定取得環境(衛生)工程、土木或水利科之工業技師。又該法施行細則第19條第3款並規定下水道主要設備包含下水道處理廠設施及其相關設備，爰土木工程科技師辦理所詢旨揭事宜應依前開規定為之。","refs":["A17","R13","R19"]},{"id":"r156","agency":"內政部","date":"102.10.4","docNo":"營署工程字第1020065094號","y":102,"src":"2018彙編","brief":"依據下水道法第17條及施行細則第13條規定，下水道之規劃、設計及監造，得委託登記開業之環境(衛生)工程、土木及水利科之工業技師辦理","text":"依據下水道法第17條及施行細則第13條規定，下水道之規劃、設計及監造，得委託登記開業之環境(衛生)工程、土木及水利科之工業技師辦理。至來函所詢下水道於規劃、設計及工程竣工後之成果審查或查驗是否包括其他工業技師乙節，查下水道法尚無相關規定。","refs":["A17","R13"]},{"id":"r157","agency":"內政部營建署","date":"81.12.7","docNo":"營署公字第17284號","y":81,"src":"2018彙編","brief":"所稱「檢定合格人員」係指經行政院勞委會職訓於檢定合格之「技術士」","text":"所稱「檢定合格人員」係指經行政院勞委會職訓於檢定合格之「技術士」；領有「技術士」證者而言。","refs":["A18"]},{"id":"r158","agency":"內政部","date":"93.10.11","docNo":"內授營工程字第0930087013號","y":93,"src":"2018彙編","brief":"下水道法第18條規定，下水道設施之操作、維護，應由技能檢定合格人員擔任之","text":"下水道法第18條規定，下水道設施之操作、維護，應由技能檢定合格人員擔任之。目前行政院勞工委員會所訂技術士技能檢定職類分級，有關下水道設施操作維護職類分為管渠系統、機電設備、處理系統、水質檢驗四項。貴轄污水處理廠操作人員亦應依照前開規定辦理，俾落實專業人員證照制度。","refs":["A18"]},{"id":"r159","agency":"內政部營建署","date":"95.4.3","docNo":"營署工程字第0950014392號","y":95,"src":"2018彙編","brief":"下水道法第18條規定「下水道設施之操作、維護，應由技能檢定合格人員擔任之」","text":"下水道法第18條規定「下水道設施之操作、維護，應由技能檢定合格人員擔任之」。同法第21條規定「用戶排水設備，應由登記合格之承裝商承裝。承裝商僱用之技工，應經技能檢定合格。前項用戶排水設備承裝商管理規則及其技工技能檢定辦法，由中央主管機關定之」。前開下水道設施操作、維護人員由貴會開辦之下水道設施操作、維護職類技能合格人員為之，尚能滿足現階段之需求。而下水道用戶排水設備承裝商僱用之「技工」係負責下水道用戶排水設備承裝工作，與下水道設施操作、維護之技能並不相同，尚不適合於現行「下水道設施操作、維護職類」項下增列，宜另行新增職類檢定。貴辦公室所提職類名稱、需具備專業知識及技能、與前稱設施操作、維護人員界定等事項，本署將另案邀集貴會與相關單位研商。","refs":["A18"]},{"id":"r160","agency":"內政部","date":"74.7.8","docNo":"台內營字第321489號","y":74,"src":"2018彙編","brief":"查依照下水道法第22條規定，用戶排水設備須經下水道機構檢驗合格，始得聯接於下水道","text":"查依照下水道法第22條規定，用戶排水設備須經下水道機構檢驗合格，始得聯接於下水道。同法第19條第2項規定下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道內。而所謂之下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道內。而所謂之下水係指雨水、家庭污水及事業廢水，因此依據排水功能，下水道可分為雨水下水道，及污水下水道兩種，除合流式下水道外，家庭污水及事業廢水自不應排入雨水下水道。但如因污水下水道系統未建立，事業廢水亦需在有條件情形下經下水道機構同意，始得暫時排入雨水下水道，俟污水下水道完成後排入污水下水道系統。事業廢水符合放流水標準，並經當地主管機關核准排放於非下水道系統之水體，得不受下水道法之約束，如排放於下水道系統之溝渠，需依上開之規定辦理，並無不妥，與水污染防治法第9條之規定亦無牴觸之處。","refs":["A19","A22"]},{"id":"r161","agency":"內政部營建署","date":"86.3.3","docNo":"營署公字第04236號","y":86,"src":"2018彙編","brief":"下水道法第19條規定，下水道機構，應於下水道開始使用前，將排水區域、開始使用日期、接用程序及下水道管理規章公告週知","text":"一、下水道法第19條規定，下水道機構，應於下水道開始使用前，將排水區域、開始使用日期、接用程序及下水道管理規章公告週知。下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道之內。前開公告行為及其事項，依法由「下水道機構為主」，所詢工業區管理機關若經下水道主管機關指定為「下水道機構」者，自得依法為之。\n二、同法第32條為違反本法之處分規定，所指不依期限接用下水道、排水設備不合格、拒絕接受檢驗及排入下水水質超過標準不予改善等諸項行為，皆需於第19條公告事項內明確規範，俾資用戶遵守，故未經公告，自無從依法處分。","refs":["A19"]},{"id":"r162","agency":"內政部營建署","date":"90.5.30","docNo":"營署工程字第025422號","y":90,"src":"2018彙編","brief":"工業區應依下水道法第8條規定設置專用下水道並管理之，其目的在處理工業區內廢（污）水，達防治水污染之目標","text":"工業區應依下水道法第8條規定設置專用下水道並管理之，其目的在處理工業區內廢（污）水，達防治水污染之目標。若工業區內專用下水道之污水處理廠因處理功能提升或容量飽和等因素，無法容納廢（污）水時，區內事業廢（污）水仍須自行處理其廢（污）水達放流水標準，經當地下水道主管機關同意後，得排放於區內雨水下水道。惟上開行為屬暫行性權宜措施，俟污水處理廠無法容納原因消失，區內廢污水仍應納入污水處理廠處理，俾符專用下水道設置緣由。","refs":["A19"]},{"id":"r163","agency":"內政部營建署","date":"97.7.3","docNo":"台內營字第0970805227號","y":97,"src":"2018彙編","brief":"下水道法第19條第1項規定：「下水道機構，應於下水道開始使用前，將排水區域、開始使用日期、接用程序及下水道管理規章公告週知","text":"下水道法第19條第1項規定：「下水道機構，應於下水道開始使用前，將排水區域、開始使用日期、接用程序及下水道管理規章公告週知。」；同法施行細則第17條亦規定：「下水道可使用之地區，其用戶應於依本法第19條第1項所定公告開始使用之日起6個月內與下水道完成聯接使用。」；同法第29條第1項復規定：「主管機關對於未依規定期限，設置用戶排水設備並完成與下水道聯接使用者，除依第32條規定處罰外，並得命下水道機構代為辦理，所需經費由下水道用戶負擔。」。前開意旨，用戶應於規定期限與下水道完成聯接使用，倘違反者，予以處罰，主管機關得命下水道機構代辦，並由用戶負擔經費。其規定期限內聯接行為之執行者為何，法尚無規範。若主管機關以獎勵方式編列預算，於6個月內代為施作完成，尚無違反下水道法之規定；惟因用戶拒絕或其他情事，致未能於期限內完成聯接，始有處罰、代辦及付費之執行契機。來函所稱「得編列預算…」，核與該法第29條第1項及施行細則第17條規定並無不合。至規範「施工及維護管理空間」乙節，下水道法亦無規定，請本諸權責自行決定。","refs":["A19","A21","A29","A32","R17"]},{"id":"r164","agency":"內政部營建署","date":"99.5.11","docNo":"台內營字第0990803676號","y":99,"src":"2018彙編","brief":"依據下水道法第19條第2項規定，下水道排水區域內之下水，除經當地主管機關核准外，應依公告規定排洩於下水道之內，不得有…","text":"依據下水道法第19條第2項規定，下水道排水區域內之下水，除經當地主管機關核准外，應依公告規定排洩於下水道之內，不得有廢（污）水無故未與系統完成聯接之情事。故若既設之管線欲予廢除，自適用下水道法施行細則第11條規定。","refs":["A19","R11"]},{"id":"r165","agency":"內政部營建署","date":"104.11.10","docNo":"營署工程字第1040072257號","y":104,"src":"2018彙編","brief":"下水道法第19條第2項規定，下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道之內","text":"下水道法第19條第2項規定，下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道之內。另查地方制度法第19條規定，下水道建設及管理屬地方自治事項。旨揭所詢，南投縣政府既已函復在案，仍請依該府意見辦理。","refs":["A19"]},{"id":"r166","agency":"內政部","date":"103.2.13","docNo":"營署工程字第1030007946號","y":103,"src":"2018彙編","brief":"下水道法第20條規定，下水道用戶排水設備之管理、維護，由用戶自行負責","text":"下水道法第20條規定，下水道用戶排水設備之管理、維護，由用戶自行負責。其意旨該設備屬用戶所有，有關新建物該設備切換裝置之申請，自應由用戶辦理。","refs":["A20"]},{"id":"r167","agency":"內政部營建署","date":"87.5.11","docNo":"營署公字第11183號","y":87,"src":"2018彙編","brief":"下水道法第21條規定，用戶排水設備，應由登記合格之承裝商承裝","text":"下水道法第21條規定，用戶排水設備，應由登記合格之承裝商承裝。及同法第22條規定用戶排水設備須經下水道機構檢驗合格，始得聯接於下水道，至該設備由何人規劃、設計及監造，法尚無明文規定。","refs":["A21"]},{"id":"r168","agency":"內政部營建署","date":"91.3.18","docNo":"營署工程字第0910012857號","y":91,"src":"2018彙編","brief":"下水道法第21條規定，用戶排水設備，應由登記合格之承裝商承裝","text":"下水道法第21條規定，用戶排水設備，應由登記合格之承裝商承裝。前揭係指承裝施工，而設計工作，依第17條規定，得委託登記開業之有關專業技師辦理。","refs":["A21"]},{"id":"r169","agency":"內政部營建署","date":"91.4.1","docNo":"營署工程字第0910016961號","y":91,"src":"2018彙編","brief":"下水道法第21條規定，用戶排水設備，應由登記合格之承裝商承裝","text":"下水道法第21條規定，用戶排水設備，應由登記合格之承裝商承裝。前揭係指承裝施工，而設計工作，依第17條規定，得委託登記開業之有關專業技師辦理。","refs":["A21"]},{"id":"r170","agency":"內政部","date":"94.6.24","docNo":"內授營工程字第0940033647號","y":94,"src":"2018彙編","brief":"污水下水道用戶接管工程品質，攸關污水下水道功能，故下水道法第21條規定，用戶排水設備，應由登記合格之承裝商承裝，該法…","text":"污水下水道用戶接管工程品質，攸關污水下水道功能，故下水道法第21條規定，用戶排水設備，應由登記合格之承裝商承裝，該法施行細則第17條之1第2項並規定，下水道用戶排水設備，得由自來水管承裝商承裝。依前開解釋，自來水管承裝商營業項目，自得包括污水下水道用戶排水設備之施工。","refs":["A21"]},{"id":"r171","agency":"內政部","date":"97.4.17","docNo":"內授營工程字第0970803088號","y":97,"src":"2018彙編","brief":"下水道法第21條第1項規定：「用戶排水設備，應由登記合格之下水道用戶排水設備承裝商或自來水管承裝商承裝","text":"下水道法第21條第1項規定：「用戶排水設備，應由登記合格之下水道用戶排水設備承裝商或自來水管承裝商承裝。承裝商僱用之技工，應經技能檢定合格，並經中央主管機關訓練合格。」，依前開規定，下水道用戶排水設備係採下水道用戶排水設備承裝商或自來水管承裝商皆得承裝之雙軌制運作方式；所稱承裝技工資格，本部於97年3月20日以台內營字第0970800940號令發布，並於97年3月25日內授營工程字第0970802379號函各機關在案。而下水道用戶排水設備承裝資格，本部於97年3月20日以台內營字第0970801667號令發布，並於97年3月26日以內授營工程字第0970802386號函（均諒達）各機關有案，請　貴府參照辦理。","refs":["A21"]},{"id":"r172","agency":"內政部","date":"97.5.21","docNo":"內授營工程字第0970804047號","y":97,"src":"2018彙編","brief":"下水道法第21條第1項規定：「用戶排水設備，應由登記合格之下水道用戶排水設備承裝商或自來水管承裝商承裝","text":"下水道法第21條第1項規定：「用戶排水設備，應由登記合格之下水道用戶排水設備承裝商或自來水管承裝商承裝。承裝商雇用之技工，應經技能檢定合格，並經中央主管機關訓練合格。」，前開所稱訓練，依法應由中央主管機關(內政部)為之，  貴府建議以辦理「馬祖地區污水下水道系統工程」施工教育訓練之結業證書替代廠商資格，於法不符，未便同意。","refs":["A21"]},{"id":"r173","agency":"內政部","date":"98.10.27","docNo":"營署工程字第0980072047號","y":98,"src":"2018彙編","brief":"下水道法第21條第1項規定，用戶排水設備，應由登記合格之下水道用戶排水設備承裝商或自來水管承裝商承裝","text":"下水道法第21條第1項規定，用戶排水設備，應由登記合格之下水道用戶排水設備承裝商或自來水管承裝商承裝。承裝商雇用之技工，應經技能檢定合格，並經中央主管機關訓練合格。依前開規定，下水道用戶排水設備之承裝，係採雙軌制，合格之下水道用戶排水設備承裝商或自來水管承裝商皆可辦理。至有關前開合格之下水道用戶排水設備承裝商或自來水管承裝商應具備之條件部分，於本部訂定之「下水道用戶排水設備承裝商管理規則」或經濟部所訂「自來水管承裝商管理辦法」中已有明文規定。","refs":["A21"]},{"id":"r174","agency":"內政部","date":"94.12.2","docNo":"內授營工程字第0940011760號","y":94,"src":"2018彙編","brief":"查下水道法第26條規定略以：「用戶使用下水道，應繳納使用費","text":"查下水道法第26條規定略以：「用戶使用下水道，應繳納使用費；---前項使用費計算公式及徵收辦法，由直轄市、縣（市）主管機關擬訂，報請中央主管機關核定之。」依前開規定，貴市公共污下水道之使用費計算公式及徵收辦法，由貴府擬訂，報請本部核定。至楠梓加工出口區污水下水道屬貴轄區專用污水下水道，其使用費計算公式及徵收辦法，現行下水道法並無應報請中央主管機關核定之規定。","refs":["A22","A26"]},{"id":"r175","agency":"內政部","date":"106.11.30","docNo":"營署水字第1061135549號","y":106,"src":"2018彙編","brief":"本案建設公司未依據下水道法施行細則第15條規定檢附用戶排水設備圖說、配置圖、排水口地點等資料，或未依前述資料施工，依…","text":"一、本案建設公司未依據下水道法施行細則第15條規定檢附用戶排水設備圖說、配置圖、排水口地點等資料，或未依前述資料施工，依據下水道法第22條規定，下水道機構應限期責令改善。\n二、按建築技術規則為建築法第97條授權訂定，該規則總則編第3條明定「建築物之設計、施工、構造及設備，依本規則各編規定。......」。有關已領有使用執照之建築物，其建築執照處理程序已終結，如有不符建築技術規則之情事，其建築執照依行政程序法有關行政處分之撤銷、廢止或補正之規定辦理。","refs":["A22","R15"]},{"id":"r176","agency":"內政部營建署","date":"106.12.14","docNo":"內授營環字第1060819572號","y":106,"src":"2018彙編","brief":"依據下水道法施行細則第15條規定，下水道完成地區申請建築時，須檢附用戶排水設備圖說等有關資料申請下水道機構核准","text":"依據下水道法施行細則第15條規定，下水道完成地區申請建築時，須檢附用戶排水設備圖說等有關資料申請下水道機構核准。符合建築法第98條及軍事機關建築物辦理免建築執照及委請地方政府指示（定）建築線注意事項規定，適用免辦建築執照範圍之建築物，如其用戶排水設備接用下水道以排洩下水，仍應依據下水道法第22條及下水道法施行細則第15條規定辦理。","refs":["A22","R15"]},{"id":"r177","agency":"內政部","date":"106.12.29","docNo":"營署水字第1061157717號","y":106,"src":"2018彙編","brief":"下水道用戶排水設備標準第32條中，規定污水管渠管材為塑化類管者，應為橘紅色，其他管材應有橘紅色之顯著標示，至於PVC…","text":"一、下水道用戶排水設備標準第32條中，規定污水管渠管材為塑化類管者，應為橘紅色，其他管材應有橘紅色之顯著標示，至於PVC管是否可使用於高層建築物，請貴公司參照建築技術規則建築技術施工編第12章第227、247條規定，五十公尺或樓層在十六層以上之高層建築物，各種配管管材均應以不燃材料製成，或使用具有同等效能之防火措施。\n二、另建築物內之給排水設備，請依據本署93年9月23日營署工程字第0930060230號函，將雨、污水分流設置。","refs":["A22"]},{"id":"r178","agency":"內政部","date":"86.10.21","docNo":"台內營字第8607680號","y":86,"src":"2018彙編","brief":"下水道法第25條第2項規定，下水道用戶排洩下水，超過下水道機構擬定，報請省（市）主管機關核定公告之可容納排入之下水水…","text":"一、下水道法第25條第2項規定，下水道用戶排洩下水，超過下水道機構擬定，報請省（市）主管機關核定公告之可容納排入之下水水質標準者，下水道機構應限期責令改善；其情節重大者，得通知停止使用。同法第19條第2項規定，下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道之內。\n二、依前開要旨，下水道排水區域內之用戶，皆需將下水排洩於下水道內，且其排入水質應符合可容納排入之下水水質標準之規定；而超過水質標準，屬情節重大者，經下水道機構通知停止使用，仍需依限期改善後將下水排入下水道內，以達下水道興建之目的，故經通知停止使用下水道之用戶，若不依限期改善者，顯已違反前揭第25條第2項之規定，由主管機關依同法第32條第1項予以處罰，並得依同條第2項予以連續處罰。","refs":["A25"]},{"id":"r179","agency":"內政部","date":"101.4.19","docNo":"台內營字第1010803147號","y":101,"src":"2018彙編","brief":"下水道法第25條第1項規定，下水道可容納排入之下水水質標準，由下水道機構擬定，報請直轄市、縣(市)主管機關核定後公告之","text":"下水道法第25條第1項規定，下水道可容納排入之下水水質標準，由下水道機構擬定，報請直轄市、縣(市)主管機關核定後公告之。准此，下水道機構包括政府機關、公、民營機構或團體，其得擬定下水道可容納下水水質標準，經當地下水道主管機關核定後公告執行。貴府為政府機關，所為前開規定，是否以「自治規則」或「公告」方式處理，得由　貴府自行衡酌為之。","refs":["A25"]},{"id":"r180","agency":"內政部","date":"90.7.3","docNo":"台內營字第9010082號","y":90,"src":"2018彙編","brief":"下水道法第26條規定用戶應繳納之使用費計算公式及徵收辦法，由直轄市、縣（市）主管機關擬訂，報請中央主管機關核定之","text":"一、下水道法第26條規定用戶應繳納之使用費計算公式及徵收辦法，由直轄市、縣（市）主管機關擬訂，報請中央主管機關核定之。上開規定為下水道法賦予之授權規定。而是否需先依地方自治條例為必要程序之處置，屬地方政府權責，請貴府自行衡酌為之。\n二、至下水道使用費是否屬於「規費」乙節，案經財政部90年6月26日台財庫第090003281號函解釋（如附件影本），請參考。","refs":["A26"]},{"id":"r181","agency":"內政部","date":"93.8.31","docNo":"內授營工程字第0930010254號","y":93,"src":"2018彙編","brief":"有關地方制度法公布施行後，地方行政機關基於其他法律授權訂定之自治規則，其內容涉及創設、剝奪或限制地方自治團體居民之權…","text":"有關地方制度法公布施行後，地方行政機關基於其他法律授權訂定之自治規則，其內容涉及創設、剝奪或限制地方自治團體居民之權利義務者，其名稱應如何訂定乙節，本部88年6月14日台（88）內民字第8805134號函釋在案（如附件）。查貴府擬訂「污水下水道使用費徵收條例」，係依下水道法第26條訂定，依上開函釋，以「自治條例」訂定為宜。","refs":["A26"]},{"id":"r182","agency":"內政部營建署","date":"94.8.18","docNo":"營署工程字第0940041500號","y":94,"src":"2018彙編","brief":"下水道法第26條第1項規定，用戶使用下水道，應繳納使用費","text":"下水道法第26條第1項規定，用戶使用下水道，應繳納使用費；其計收方式依第1款規定，按下水道用戶使用自來水及其他用水之用量比例計收，又第2項規定使用費計算公式及徵收辦法，由直轄市、縣（市）主管機關擬定，報請中央主管機關核定之，前開規定係基於使用者付費精神立法。貴處徵收污水下水道使用費，係依據「台北市污水下水道使用費徵收自治條例」執行，依法有據，毋庸置疑。","refs":["A26"]},{"id":"r183","agency":"內政部","date":"98.5.27","docNo":"營署工程字第0980034491號","y":98,"src":"2018彙編","brief":"查下水道法第26條規定，用戶使用下水道，應繳納使用費…，下水道使用費計算方式及徵收辦法，由直轄市、縣(市)主管機關擬…","text":"查下水道法第26條規定，用戶使用下水道，應繳納使用費…，下水道使用費計算方式及徵收辦法，由直轄市、縣(市)主管機關擬定，報請中央主管機關核定之。前開意旨，用戶使用「公共下水道」，須依主管機關所定徵收辦法繳納使用費。至私設之社區專用下水道使用費收取乙節，屬私權範疇，下水道法尚無明文規定","refs":["A26"]},{"id":"r184","agency":"內政部","date":"97.4.19","docNo":"台內營字第1000803032號","y":97,"src":"2018彙編","brief":"下水道法第26條規定，用戶使用下水道，應繳納使用費","text":"下水道法第26條規定，用戶使用下水道，應繳納使用費。同法第27條規定，下水道用戶不依規定繳納下水道使用費者，得自繳納期限屆滿之次日起，每逾三日加徵應納使用費額百分之一滯納金；逾期一個月經催告而仍不繳納者，得移送法院裁定後強制執行。查本案所稱社區既已非都市土地開發審議作業規範規定，將其興建完成之污水處理場贈與　貴府，自得視為下水道法所稱縣屬下水道之一環。準此，所詢該法第27條適用乙節，得由　貴府依前開規定為之。","refs":["A27"]},{"id":"r185","agency":"內政部","date":"97.4.28","docNo":"內授營工程字第0970068585號","y":97,"src":"2018彙編","brief":"下水道法第27條規定，下水道用戶不依規定繳納下水道使用費者，得自繳納期限屆滿之次日起，每逾三日加徵應納使用費額百分之一滯納金","text":"下水道法第27條規定，下水道用戶不依規定繳納下水道使用費者，得自繳納期限屆滿之次日起，每逾三日加徵應納使用費額百分之一滯納金；逾期一個月經催告而仍不繳納者，得移送法院裁定後強制執行。依前開立法意旨，有關滯納金於法尚無明文上限規定，爰  貴縣「下水道使用費徵收自治條例(草案)」，仍請依前開規定辦理。","refs":["A27"]},{"id":"r186","agency":"內政部","date":"106.5.9","docNo":"台內營字第1060805666號","y":106,"src":"2018彙編","brief":"本部前以92年4月28日內授營工程字第0920005391號函釋滯納金核算至移送強制執行之日為止，及97年4月28日…","text":"一、本部前以92年4月28日內授營工程字第0920005391號函釋滯納金核算至移送強制執行之日為止，及97年4月28日內授營工程字第0970068585號函說明滯納金無明文上限規定在案。惟查106年2月24日司法院釋字第746號解釋理由略以，加徵滯納金有助達成人民於法定期限或逾期後儘速完成公法上金錢給付義務之目的；惟加徵方式，應視稽徵成本、逾期繳納情形、物價及國民經濟水準等因素，以避免致個案適用結果過苛。\n二、揆諸前開司法院解釋精神，並參酌現行相關法令規定及函釋體例（例如規費法第20條第1項、工程受益費徵收條例第15條及財政部82年1月5日台財稅第811688010號函），下水道用戶不依下水道法第27條規定繳交使用費，逾期1個月應徵收百分之十滯納金，並即予催告，經催告而仍不繳納者，移送強制執行。","refs":["A27"]},{"id":"r187","agency":"內政部","date":"100.10.21","docNo":"台內營字第1000199102號","y":100,"src":"2018彙編","brief":"按下水道法施行細則第19條僅對下水道主要設備規定如下：(一)下水道系統管渠、放流口及其附屬設施","text":"按下水道法施行細則第19條僅對下水道主要設備規定如下：(一)下水道系統管渠、放流口及其附屬設施。(二)下水道抽水站設施及其相關設備。(三)下水道處理廠設施及其相關設備。(四)其他有關下水道重要設施。除前開所列者外，為非下水道主要設備；另下水道之箱涵屬下水道工程設施標準第4條所規範下水道管渠設施之一，自屬下水道主要設備","refs":["A31","R19"]},{"id":"r188","agency":"內政部","date":"103.1.21","docNo":"營署工程字第1030004122號","y":103,"src":"2018彙編","brief":"下水道法施行細則第19條業明確規範下水道主要設備，各款所列均為下水道構造及設施","text":"下水道法施行細則第19條業明確規範下水道主要設備，各款所列均為下水道構造及設施。來函雖稱地面逕流收集系統屬道路之附屬工程設施，然地面逕流系統為雨水下水道收集範圍，如該地面逕流系統經  貴府納為雨水下水道之一環統籌管理，則有下水道法之適用。案涉地方自治事項，請  貴府本諸權責妥處。","refs":["A31","R19"]},{"id":"r189","agency":"內政部","date":"104.3.4","docNo":"台內營字第1040802692號","y":104,"src":"2018彙編","brief":"查下水道法施行細則(下稱施行細則)第19條規定：「本法第31條所稱下水道主要設備如左：一、下水道系統管渠、放流口及其附屬設施","text":"查下水道法施行細則(下稱施行細則)第19條規定：「本法第31條所稱下水道主要設備如左：一、下水道系統管渠、放流口及其附屬設施。二、下水道抽水站設施及其相關設備。三、下水道處理廠設施及其相關設備。四、其他有關下水道重要設施。」是本案  貴府所詢興建高級處理設施及其輸水至臨海工業區之管線，係將污水處理廠之放流水經再處理後回收之相關設施(備)，屬施行細則第19條第1款及第3款所定範疇，自得適用下水道法相關規定。","refs":["A31","R19"]},{"id":"r190","agency":"內政部營建署","date":"86.8.27","docNo":"營署公字第53954號","y":86,"src":"2018彙編","brief":"下水道第19條規定，下水道機構應於下水道開始使用前，將排水區域、開始使用日期、接用程序及下水道管理規章公告週知","text":"一、下水道第19條規定，下水道機構應於下水道開始使用前，將排水區域、開始使用日期、接用程序及下水道管理規章公告週知。下水道區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道之內。同法施行細則第17條復規定，下水道可使用之地區，其用戶應於前揭所定公告開始使用之日起6個月內與下水道完成聯接使用。\n二、依前開條文規定，下水道機構應將用戶接用下水道之程序（包括申請、接管、完成聯接等手續）及下水道管理規章（內容須包括用戶使用費收取方法、費率計算基準………等）於下水道開始使用前公告，俾排水區域內之用戶遵行，而自公告開始使用之日起6個月內各用戶皆應完成接用，逾期者，下水道機構自行依下水道法第32條第1項第1款之規定，予以處罰。","refs":["A32"]},{"id":"r191","agency":"內政部營建署","date":"92.9.9","docNo":"營署工程字第0920053063號","y":92,"src":"2018彙編","brief":"下水道法第25條第2項規定：下水道用戶排洩下水，超過下水道可容納之下水水質標準者，下水道機構應限期責令改善","text":"下水道法第25條第2項規定：下水道用戶排洩下水，超過下水道可容納之下水水質標準者，下水道機構應限期責令改善；其情節重大者，得通知停止使用。違反前開規定者，得依同法第32條第4款予以處罰。故貴府應嚴密監視用戶排放水質，遇有違法事實時，即限期責其改善或視情節通知停用，仍未改善者，始科以處罰，以資適法。","refs":["A32"]},{"id":"r192","agency":"內政部","date":"84.5.5","docNo":"台內營字第8472548號","y":84,"src":"2018彙編","brief":"貴府為下水道主管機關，工業區設置專用下水道，其下水道用戶未依下水道法規定聯接使用或排放水質未符合下水道機構規定水質標…","text":"貴府為下水道主管機關，工業區設置專用下水道，其下水道用戶未依下水道法規定聯接使用或排放水質未符合下水道機構規定水質標準，自應由貴府依下水道法規定予以處罰","refs":["other"]},{"id":"r193","agency":"內政部營建署","date":"86.8.13","docNo":"營署工程字第18092號","y":86,"src":"2018彙編","brief":"查污水處理廠、抽水站、截流站等工程係屬環保工程或土木工程，上開工程之設置標準悉明訂於下水道相關法規中，故其中除污水處…","text":"查污水處理廠、抽水站、截流站等工程係屬環保工程或土木工程，上開工程之設置標準悉明訂於下水道相關法規中，故其中除污水處理廠之管理大樓如係純供管理人員工作及住宿場所，應依建築法之規定申請建造執照，其餘應不屬建築法規範之範疇。","refs":["other"]},{"id":"r194","agency":"內政部營建署","date":"87.3.26","docNo":"營署公字第06469號","y":87,"src":"2018彙編","brief":"有關下水道法規定處罰之罰鍰單位為銀元，復請查照","text":"有關下水道法規定處罰之罰鍰單位為銀元，復請查照。","refs":["other"]},{"id":"r195","agency":"內政部營建署","date":"88.11.18","docNo":"營署公字第36769號","y":88,"src":"2018彙編","brief":"有關工業區專用下水道規劃設計是否需由專業技師簽證，目前下水道法並無相關規定，惟為彌補縣市政府下水道專業人力之不足，貴…","text":"有關工業區專用下水道規劃設計是否需由專業技師簽證，目前下水道法並無相關規定，惟為彌補縣市政府下水道專業人力之不足，貴中心有關專用下水道之申請，得先由專業技師簽證，至是否由貴中心總顧問之技師為之，請自行酌之。","refs":["other"]},{"id":"r196","agency":"內政部營建署","date":"90.5.21","docNo":"營署環字第921210號","y":90,"src":"2018彙編","brief":"查貴署87年7月8日修正令頒之「開發行為應實施環境影響評估細目及範圍認定標準」第28條第1項第2款規定環境保護工程中…","text":"一、查貴署87年7月8日修正令頒之「開發行為應實施環境影響評估細目及範圍認定標準」第28條第1項第2款規定環境保護工程中污水下水道系統之污水處理廠興建或擴建工程符合第1款第2、3、4目或處理廠之目標年服務人口在廿五萬人以上者應實施環境評估，因此依該條款規定應實施環境影響評估細目及範圍，僅限於污水下水道系統之污水處理廠工程部份，並未包含污水下水道系統之管線工程部份。\n二、經查污水下水道系統管線工程為一般性、經常性、短暫性之工程，且多配合道路工程施設或埋設於既有道路，目前其他管線工程如自來水管線、排水管涵等工程，亦均未納列上述應實施環境影響評估細目及範圍認定標準。","refs":["other"]},{"id":"r197","agency":"內政部營建署","date":"90.12.28","docNo":"台內營字第09017078號","y":90,"src":"2018彙編","brief":"按「起造人自領得建造執照或雜項執照之日起，應於6個月內開工","text":"按「起造人自領得建造執照或雜項執照之日起，應於6個月內開工；並應於開工前，會同承造人及監造人將開工日期，連同姓名或名稱、住址及證書字號及承造人之施工計畫書，申請該管主管建築機關備查。……」，為建築法第54條所明文，查本部88年7月12日台88內營字第8806518號函（影本如附件）說明五略以「是起造人依法申報開工，係屬備查性質，主管機關並無准駁之依據，自不得以加註之方式限制起造人申報開工，外審單位請釋及審查時間亦不得歸責予起造人。……」，是建築法第五十四條所規定之申報開工，尚無本案所陳下水道法施行細則第5條規定設置專用下水道之申請核准施工程序，本案自應依上開規定辦理。","refs":["other","R5"]},{"id":"r198","agency":"內政部營建署","date":"91.9.10","docNo":"營署工程字第0910057064號","y":91,"src":"2018彙編","brief":"有關專用下水道設置申請變更專業技師，未附原承辦技師之拋棄書，是否准予變更乙案現行下水道法並無規定專業技師變更之相關條…","text":"有關專用下水道設置申請變更專業技師，未附原承辦技師之拋棄書，是否准予變更乙案現行下水道法並無規定專業技師變更之相關條文，貴府是否有另行規定，或於下水道自治條例中具相關規定，請本諸權責自行決定。","refs":["other"]},{"id":"r199","agency":"內政部營建署","date":"92.10.6","docNo":"營署工程字第0920059300號","y":92,"src":"2018彙編","brief":"台端函訴台北市政府於都市計畫範圍內未公告細部計畫地區，非法興建排水溝，並未經同意使用私有地乙案，按經台北市政府工務局…","text":"台端函訴台北市政府於都市計畫範圍內未公告細部計畫地區，非法興建排水溝，並未經同意使用私有地乙案，按經台北市政府工務局92年9月22日北市工養字第09232369500號函復本署說明（如附件）。有關涉及下水道法解釋部份，因該法於73年12月公布，為台端系爭事實之後，基於法令不溯既往之原則，並不適用。請另循其他途徑解決。","refs":["other"]},{"id":"r200","agency":"內政部營建署","date":"94.1.7","docNo":"營署工程字第0942900170號","y":94,"src":"2018彙編","brief":"有關交通部台灣鐵路管理局申請「台鐵烏日新站工程專用污水下水道系統工程設置」開工乙案，按建築法第九十八條規定：特種建築…","text":"有關交通部台灣鐵路管理局申請「台鐵烏日新站工程專用污水下水道系統工程設置」開工乙案，按建築法第九十八條規定：特種建築物得經行政院之許可，不適用本法全部或一部之規定。前開意涵係指特種建築物得免按建築法全部或一部之規定，惟仍需符合都市計畫、消防----等其他法令之規定。本案有關專用污水下水道之申請、書圖審查、完工驗收仍需依下水道法相關規定為之。","refs":["other"]},{"id":"r201","agency":"內政部營建署","date":"95.12.22","docNo":"營署建管字第0950065586號","y":95,"src":"2018彙編","brief":"按「污水廠、抽水站、截流站等工程係屬環保工程或土木工程，上開工程之設置標準悉明訂於下水道相關法規中，故其中除污水處理…","text":"按「污水廠、抽水站、截流站等工程係屬環保工程或土木工程，上開工程之設置標準悉明訂於下水道相關法規中，故其中除污水處理廠之管理大樓如係純管理人員工作及住宿場所，應依建築法之規定申請建造執照，其餘應不屬建築法規範之範疇。」本署86年8月13日86營署建字第18092號函說明二業已函釋在案，本案請就個案事實依上揭函釋規定本於權責認定卓處。","refs":["other"]},{"id":"r202","agency":"內政部","date":"96.9.20","docNo":"台內營字第0960805917號","y":96,"src":"2018彙編","brief":"有關「下水道用戶排水設備承裝商管理規則」第2條適用對象乙案","text":"有關「下水道用戶排水設備承裝商管理規則」第2條適用對象乙案\n一、旨揭規則第2條所稱之「下水道用戶排水設備承裝商」為承攬下水道用戶接用下水道以排洩下水之管渠及有關設備裝修工程業務之公司或商號。故下水道用戶排水設備承裝商之承攬範圍應符合該第2條之規定，至於所詢可否承攬分支幹管、主幹管及其他部分，查下水道法及其子法並無相關規定，如屬營造業法或其他法令規範範疇，請依相關規定辦理。\n二、貴府來函所稱「下水道用戶排水設備承裝商管理辦法」之「辦法」二字應為「規則」。","refs":["other"]},{"id":"r203","agency":"內政部","date":"102.7.5","docNo":"內授營字第1020230792號","y":102,"src":"2018彙編","brief":"按建築法（下稱本法）第73條第2項規定：「建築物應依核定之使用類組使用，其有變更使用類組或有第9條建造行為以外主要構…","text":"按建築法（下稱本法）第73條第2項規定：「建築物應依核定之使用類組使用，其有變更使用類組或有第9條建造行為以外主要構造、防火區劃、防火避難設施、消防設備、停車空間及其他與原核定使用不合之變更者，應申請變更使用執照。但建築物在一定規模以下之使用變更，不在此限。」前揭條文所稱本法第9條建造行為以外主要構造、防火區劃、防火避難設施、消防設備、停車空間及其他與原核定使用不合之變更，應申請變更使用執照之具體項目，建築物使用類組及變更使用辦法（下稱本辦法）第8條各款定有明文。\n至本案所稱因變更開發許可之環境影響評估（差異分析）審查結論，需變更內部構造之污水處理設施，因非屬本辦法第8條所示應辦理變更使用執照之規定項目，自無本法第73條及辦法相關條文規定之適用。又同案另陳本案變更污水處理設施內部構造之情節得否採該（下水道法）目的事業主管機關備查或核准方式辦理即可乙節，請提供個案具體資料（包括該設施原核定內容及申請變更構造相關圖說）並研提處理意見到部再議。","refs":["other"]},{"id":"r204","agency":"內政部","date":"106.12.14","docNo":"內授營環字第1060819582號","y":106,"src":"2018彙編","brief":"本部營建署86年8月13日營署工程字第18092號函暨95年12月22日營署建管字第0950065586號函已釋示「…","text":"本部營建署86年8月13日營署工程字第18092號函暨95年12月22日營署建管字第0950065586號函已釋示「污水處理廠、抽水站、截流站等工程係屬環保工程或土木工程，上開工程之設置標準悉明訂於下水道相關法規中，故其中除污水處理廠之管理大樓如係純供管理人員工作及住宿場所，應依建築法之規定申請建造執照，其餘應不屬建築法規範之範疇。」本案請貴府依上揭函釋本權責認定。","refs":["other","R5"]},{"id":"r205","agency":"內政部營建署","date":"87.10.27","docNo":"營署公字第26736號","y":87,"src":"2018彙編","brief":"按下水道法施行細則第3條第2項指污水下水道為：專供處理家庭污水及事業廢水之下水道，復依同法施行細則第19條：下水道主…","text":"按下水道法施行細則第3條第2項指污水下水道為：專供處理家庭污水及事業廢水之下水道，復依同法施行細則第19條：下水道主要設備包括下水道系統管渠、下水道抽水站及下水道處理廠等，故污水處理廠自包括於污水下水道系統內。又污水下水道屬都市計畫法第42條所稱都市計畫範圍內應設置之公共設施之一，鑑於區段徵收土地將可增值，區域內土地所有權人有形無形利益遽增，基於公平原則，污水下水道自應由共同參與區段徵收者負擔。故本署建議辦理區段徵收時污水下水道之建設費用應納入其開發成本內。","refs":["R3"]},{"id":"r206","agency":"內政部營建署","date":"93.6.28","docNo":"營署工程字第號0930042064","y":93,"src":"2018彙編","brief":"查下水道法施行細則第3條，下水道分為雨水下水道、污水下水道及合流下水道三種，雨水之下水道指專供處理雨水之下水道","text":"查下水道法施行細則第3條，下水道分為雨水下水道、污水下水道及合流下水道三種，雨水之下水道指專供處理雨水之下水道。來函所稱「公共排水溝」，非下水道法之法定用辭，無從判定是否屬下水道範疇，若屬水利法相關規定所稱區域排水、灌溉等排水溝渠，則依其目的事業主管機關權責而有所區分，請另洽相關主管機關。而新開發社區專用下水道之放流水排放，仍須依照水污染防治法第14條及第19條相關規定辦理。","refs":["R3"]},{"id":"r207","agency":"內政部營建署","date":"102.9.25","docNo":"營署工程字第1020061542號","y":102,"src":"2018彙編","brief":"雨水下水道功能在排放雨水，尚未有公共污水下水道可收集處理家庭污水地區，其合於放流水標準之家庭污水及事業廢水，得經該雨…","text":"雨水下水道功能在排放雨水，尚未有公共污水下水道可收集處理家庭污水地區，其合於放流水標準之家庭污水及事業廢水，得經該雨水下水道管理單位同意後排放其內。惟前開情形尚非下水道法施行細則第3條第3款所稱合流下水道，亦非來函所稱雨、污水合流地區。","refs":["R3"]},{"id":"r208","agency":"內政部營建署","date":"103.4.7","docNo":"內授營工程字第1030130067號","y":103,"src":"2018彙編","brief":"來函既稱污(廢)水係由廠商各自依水污染防治法處理，其放流水排入園區內匯流管線至海放口專管排放，自毋須再設置下水道，核…","text":"來函既稱污(廢)水係由廠商各自依水污染防治法處理，其放流水排入園區內匯流管線至海放口專管排放，自毋須再設置下水道，核自無旨揭所詢下水道法之適用。","refs":["R3"]},{"id":"r209","agency":"內政部營建署","date":"105.10.6","docNo":"內授營工程字第1050070645號","y":105,"src":"2018彙編","brief":"道路側溝係道路排水設施，下水道法施行細則第3條規定，雨水下水道為專供處理雨水之下水道，二者同時具有排除積水之功能","text":"道路側溝係道路排水設施，下水道法施行細則第3條規定，雨水下水道為專供處理雨水之下水道，二者同時具有排除積水之功能。道路側溝如經當地下水道主管機關納為雨水下水道之一環，方為下水道法解釋範疇。復依據地方制度法第18條及第19條規定，下水道建設及管理屬地方自治事項，旨揭所詢，應洽當地下水道主管機關為宜。","refs":["R3"]},{"id":"r210","agency":"內政部營建署","date":"87.2.20","docNo":"營署公字第02967號","y":87,"src":"2018彙編","brief":"依本部86年7月16日台（86）內營字第8673235號函令修正「下水道法施行細則」第4條，稱「新開發工業區」為：","text":"一、依本部86年7月16日台（86）內營字第8673235號函令修正「下水道法施行細則」第4條，稱「新開發工業區」為：\n(一)政府機關、公民營事業機構開發供事業設廠之地區。\n(二)事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者。\n二、本案麥寮六輕開發計畫，究係採以整體開發方式設廠？或於依法劃設之工業用地設廠？其基地面積若干？請貴府逕行本諸權責依法認定。","refs":["R4"]},{"id":"r211","agency":"內政部","date":"87.10.22","docNo":"台內營字第8773096號","y":87,"src":"2018彙編","brief":"本部86年7月16日台（86）內營字第8673235令修正下水道法施行細則第4條，除對新開發社區、工業區界定其定義外…","text":"一、本部86年7月16日台（86）內營字第8673235令修正下水道法施行細則第4條，除對新開發社區、工業區界定其定義外，該條第2項第1款，並規定實施都市計畫地區新開發社區人口計算基準以建築技術規則建築設備篇所訂化糞池使用人數計算。由於化糞池部份，業經本部87年7月2日台（87）內營字第8772179號令修正（如附件一）為「建築物污水處理設施」，並經本部87年9月25日台（87）內營字第8772865號函「建築物污水處理設施設計技術規範」，其使用人數、污水量及水質皆訂有標準（如附件二）。\n二、有關實施都市計畫地區新開發社區人口計算基準及污水量、污水水質，請依前揭標準為之。","refs":["R4"]},{"id":"r212","agency":"內政部","date":"87.12.9","docNo":"台內營字第8773453號","y":87,"src":"2018彙編","brief":"有關下水道法施行細則第4條第1項第2款第1目所稱「供事業設廠之地區」，指凡經政府機關、公民營事業機構以「整體開發」方…","text":"有關下水道法施行細則第4條第1項第2款第1目所稱「供事業設廠之地區」，指凡經政府機關、公民營事業機構以「整體開發」方式開發之工業區皆屬之，無需規定規模之大小。","refs":["R4"]},{"id":"r213","agency":"內政部營建署","date":"88.6.2","docNo":"營署公字第14072號","y":88,"src":"2018彙編","brief":"新開發社區應依照下水道法第8條之規定設置專用下水道並管理之，同法施行細則第4條稱新開發社區為可容納500人以上居住或…","text":"一、新開發社區應依照下水道法第8條之規定設置專用下水道並管理之，同法施行細則第4條稱新開發社區為可容納500人以上居住或總計興建100住戶之社區。依前開解釋，同一申請案件興建規模達上述條件者即應設置專用下水道。\n二、有關新開發社區人數計算，請依下水道法施行細則第4條之規定為之。","refs":["R4"]},{"id":"r214","agency":"內政部","date":"88.7.27","docNo":"營署公字第63229號","y":88,"src":"2018彙編","brief":"有關專用下水道之認定標準，本部前於82年2月4日以台（82）內營字第8272290號函示說明一略以「同法施行細則第4…","text":"一、有關專用下水道之認定標準，本部前於82年2月4日以台（82）內營字第8272290號函示說明一略以「同法施行細則第4條所撐新開發社區，指經主管機關認定之社區及合於左列情形之一者…」（諒達），授與各主管機關自行認定所稱之新開發社區，唯因各地方主管機關對新開發社區之認定標準不一，致生疑義，是以，本部復於84年9月14日以台（84）內營字第8480366號函示有關新開發社區設置專用下水道之原則及流程，略以「…專用下水道，其設置原則：1可容納500人以上居住或總計興建100戶以上者。2主管機關認定之社區。」（諒達）\n二、查本案係屬82年9月份之建照，自應依本部82年2月4日台（82）內營字第8272290號函辦理，由貴處逕行認定是否應屬新開發社區。","refs":["R4"]},{"id":"r215","agency":"內政部","date":"88.9.7","docNo":"台內營字第8874487號","y":88,"src":"2018彙編","brief":"下水道法施行細則第4條第2項第1款規定，實施都市計畫地區之新開發社區人口計算基準，以建築技術規則建築設備編所定化糞池使用人數方式計算","text":"下水道法施行細則第4條第2項第1款規定，實施都市計畫地區之新開發社區人口計算基準，以建築技術規則建築設備編所定化糞池使用人數方式計算。因本部87年7月2日台內營字第8772179號令修正「建築技術規則」建築設計施工編及建築設備編部份條文，「化糞池」部分業經修正為「污水處理設施」；另本部87年9月25日台（87）內營字第8772865號函訂頒「建築物污水處理設施設計技術規範」，該第二章訂定污水處理設施使用人數、污水量及水質參數，是以，有關前稱新開發社區人口計算及污水量估算方式，請依其規定為之。","refs":["R4"]},{"id":"r216","agency":"內政部營建署","date":"89.7.1","docNo":"營署公字第21308號","y":89,"src":"2018彙編","brief":"新開發工業區應依下水道法規定設置專用下水道，所稱「新開發工業區」，依據該法施行細則第4條，分政府機關、公民營事業機構…","text":"新開發工業區應依下水道法規定設置專用下水道，所稱「新開發工業區」，依據該法施行細則第4條，分政府機關、公民營事業機構開發供事業設廠之地區及事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者二種。台端所詢原工廠多棟廠房經核准分為多廠設立，且經環保機關審查為非屬應先提報水污染防治措施之事業，若僅申請建物分戶，變更辦理增編門牌，且其生產量及員工均不變時，則得免再另行設置專用下水道。所詢事涉水污染防治法部份，請另洽環保機關。","refs":["R4"]},{"id":"r217","agency":"內政部營建署","date":"89.8.8","docNo":"營署公字第25341號","y":89,"src":"2018彙編","brief":"新開發工業區應依下水道法規定設置專用下水道，所稱「新開發工業區」，依據該法施行細則第4條，分政府機關、公民營事業機構…","text":"新開發工業區應依下水道法規定設置專用下水道，所稱「新開發工業區」，依據該法施行細則第4條，分政府機關、公民營事業機構開發供事業設廠之地區及事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者二種。所詢原領有使用執照之工廠辦理廠房部份樓地板變更用途或分戶及增編門牌並分別申請工廠設立供多棟廠房使用。查若其生產量及員工數均不變時，則得免再另行設置專用下水道。","refs":["R4"]},{"id":"r218","agency":"內政部營建署","date":"90.11.5","docNo":"營署工程字第066832號","y":90,"src":"2018彙編","brief":"下水道法施行細則第4條第2項規定新開發社區人口計算方式，在都市計畫地區以「建築物污水處理設施設計技術規範」所定使用方式計算","text":"下水道法施行細則第4條第2項規定新開發社區人口計算方式，在都市計畫地區以「建築物污水處理設施設計技術規範」所定使用方式計算。蓋人口數計算旨在污水量之推估；該規範中，建築物使用別，採類舉方式規定，若其用途別未包括於該列舉項目內時，得以合理之使用人口推估之，由貴府本諸下水道主管機關權責審核。","refs":["R4"]},{"id":"r219","agency":"內政部營建署","date":"92.6.10","docNo":"營署工程字第0920031170號","y":92,"src":"2018彙編","brief":"新開發工業區應依下水道法第8條之規定設置專用下水道，其目的在防治廢水污染，惟規定其規模，俾利遵循","text":"新開發工業區應依下水道法第8條之規定設置專用下水道，其目的在防治廢水污染，惟規定其規模，俾利遵循。故該法施行細則第4條稱「新開發工業區」有二，其一為政府機關、公民營事業機構開發供事業設廠之地區；其二為事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上之事業，皆為應設置專用下水道之範疇。","refs":["R4"]},{"id":"r220","agency":"內政部營建署","date":"93.6.25","docNo":"營署工程字第號0930007817","y":93,"src":"2018彙編","brief":"查「下水道法施行細則」第4條本部於86年7月16日台（86）內營字第8673235號令修正，對本法第8條所稱「新開發…","text":"查「下水道法施行細則」第4條本部於86年7月16日台（86）內營字第8673235號令修正，對本法第8條所稱「新開發社區」為：申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者，而其規模為「可容納500人以上居住或總計興建100住戶以上之社區」。故凡達前述規模者皆應設置專用下水道，無論開發方式或建築物之型態而有所異同。另「化糞池」已修改為「建築物污水處理設施」。","refs":["R4"]},{"id":"r221","agency":"內政部","date":"103.9.19","docNo":"內授營工程字第1030810751號","y":103,"src":"2018彙編","brief":"查下水道法施行細則第4條規定，新開發社區需設置專用下水道之規模為可容納500人以上居住或總計興建100住戶以上之社區","text":"查下水道法施行細則第4條規定，新開發社區需設置專用下水道之規模為可容納500人以上居住或總計興建100住戶以上之社區。因污水量係依據使用人數推估，如個案申請戶數雖達100戶，但　經貴府核算其使用人數未達500人者，得考量其污染量多寡及當地環境情形等因素，衡酌採建築物污水處理設施方式處理其污水。","refs":["R4"]},{"id":"r222","agency":"內政部營建署","date":"90.5.2","docNo":"營署工程字第025552號","y":90,"src":"2018彙編","brief":"下水道法施行細則第5條規定，應設置專用下水道之地區或場所，於設置專用下水道前，應檢附專用下水道規劃及設計圖說等資料，…","text":"下水道法施行細則第5條規定，應設置專用下水道之地區或場所，於設置專用下水道前，應檢附專用下水道規劃及設計圖說等資料，申請該主管機關核准，始得施工；完工後，須經下水道主管機關查驗合格，始得使用。前開查驗合格係由主管機關為之， 若須藉技師專業能力協助查驗，宜由貴府邀請較為妥適。","refs":["R5"]},{"id":"r223","agency":"內政部","date":"90.5.31","docNo":"台內營字第9008067號","y":90,"src":"2018彙編","brief":"下水道法第3條規定，下水道主管機關在縣（市）為縣（市）政府，台中港港埠專用區位處貴縣轄區，貴府自為該管主管機關，有關…","text":"一、下水道法第3條規定，下水道主管機關在縣（市）為縣（市）政府，台中港港埠專用區位處貴縣轄區，貴府自為該管主管機關，有關轄內下水道事宜，依據該法第6條規定，均屬貴府辦理事項範疇。該專用區申請專用下水道設置，貴府仍應下水道法相關規定為之，至該區下水道系統由該管台中港務局核可，但未送貴府審查，其依據如何？應請其說明之。\n二、所詢該專用區污水處理如已依水污染防治法取得其水染防治措施計畫許可設置下水道，則有關其設置書圖審查、施工、查驗等，仍應依下水道法施行細則第5條之規定辦理。","refs":["R5"]},{"id":"r224","agency":"內政部營建署","date":"92.12.19","docNo":"營署工程字第號0920079274","y":92,"src":"2018彙編","brief":"下水道法施行細則第5條規定，設置專用下水道前，應檢附專用下水道規劃及設計圖說等資料，申請該管主管機關核准，始得施工","text":"下水道法施行細則第5條規定，設置專用下水道前，應檢附專用下水道規劃及設計圖說等資料，申請該管主管機關核准，始得施工；完工後，須經下水道主管機關查驗合格，始得使用。依前開規定，專用下水道應向所在處之主管機關申請設置及書圖之審核、查驗等事項。貴園區污水收集範圍雖跨台中縣、市，惟處理設施及排放地點均位處台中縣轄區，考量對該縣環境之影響及為利該縣水污染管制及下水道系統之監督輔導，本案請向台中縣政府申請，當台中縣政府辦理審查、工程施工、完工查驗時，台中市轄基地範圍內部份，應會同台中市政府為之，審查完竣之書圖送台中市政府備考。至基地內各管轄區之事業涉及下水道法之處分時，則應依各自主管權責辦理。","refs":["R5"]},{"id":"r225","agency":"內政部","date":"99.8.2","docNo":"台內營字第0990145091號","y":99,"src":"2018彙編","brief":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕","text":"下水道法第14條規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方式為之，並應支付償金。查　貴府已依下水道法施行細則第10條定有「基隆市下水道工程使用土地支付償金或補償費標準」已建立相當之補償機制，且依法有據，本案本部爰核依前開標準辦理。","refs":["R10"]},{"id":"r226","agency":"內政部營建署","date":"94.1.25","docNo":"營署工程字第號0940004762","y":94,"src":"2018彙編","brief":"下水道法施行細則第15條規定：下水道完成地區申請建築時，應先檢附用戶排水設備圖說、配置圖、排水口地點等資料申請下水道機構核准","text":"下水道法施行細則第15條規定：下水道完成地區申請建築時，應先檢附用戶排水設備圖說、配置圖、排水口地點等資料申請下水道機構核准；用戶排水設備完工後，須經下水道機構檢驗合格，始得聯接於下水道。依前開意旨，已興建完成專用下水道地區之建築物污水均應依規定排洩於該專用下水道處理。若專用下水道相關設施（含建物）及其用地分屬不同所有權人所有，則專用下水道排水區域內興建建築物之污水排放，其起造人自應取得該專用下水道相關設施（含建物）及土地所有權人之同意始得為之。","refs":["R15"]},{"id":"r227","agency":"內政部營建署","date":"93.8.9","docNo":"內授營工程字第號0930085765","y":93,"src":"2018彙編","brief":"下水道法施行細則第18條規定：五層以下非供公眾使用之新建建築物，其下水道設備得由該建築物之建築師併同設計之","text":"下水道法施行細則第18條規定：五層以下非供公眾使用之新建建築物，其下水道設備得由該建築物之建築師併同設計之。僅指「非供公眾使用」之「新建」建築物於建築師設計階段始得「併同」設計而言。供公眾使用之新建建築物不屬之。至建築技術規則建築設備編之衛生設備係屬建築物範圍，非下水道法所規範。","refs":["R18"]},{"id":"r228","agency":"內政部營建署","date":"102.1.21","docNo":"台內營字第1020800272號","y":102,"src":"2018彙編","brief":"查下水道法施行細則第19條第2款規定，下水道主要設備包含下水道抽水站設施及其相關設備","text":"查下水道法施行細則第19條第2款規定，下水道主要設備包含下水道抽水站設施及其相關設備；其設置目的為抽揚下水道排水區域內雨水及污水，並依下水道工程設施標準分為雨水抽水站及污水抽水站。其他法令如有抽水站之用詞者(例如停車場法、排水管理辦法等)，宜洽該法令主管機關釐清其定義後，本權責卓處。","refs":["R19"]},{"id":"r229","agency":"內政部","date":"111.3.2","docNo":"內授營環字第1110803377號","y":111,"src":"111年更新","brief":"貴府為宜蘭市公所辦理「宜蘭縣宜蘭市復興路A幹線雨水下水道改善工程」遭遇私有土地償金異議案報請本部核定1事","text":"一、依據本部營建署案陳貴府111年2月22日府水下字第1110020889號函辦理。\n二、按下水道法第14條第1項規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。」依前開旨意，僅對於施工處所、方法之選擇或支付償金額度發生異議時，始報請中央主管機關核定。\n三、查本案系爭為土地所有權人希以徵收其土地之方式辦理，非對處所及方法之選擇或支付償金提具異議，與下水道法規定不符，非屬本部核定範疇。惟請貴府依上開意旨本諸權責先行釐清，旨揭工程如符合擇其損害最少之處所及方法之條件，始有下水道法第14條第1項之適用。","refs":["A14"]},{"id":"r230","agency":"內政部","date":"110.12.24","docNo":"內授營環字第1100819230號","y":110,"src":"111年更新","brief":"貴署函詢立法院江委員永昌質詢關於下水道法增訂國有土地得無償提供設置用戶排水設備之相關規定案","text":"一、復貴署110年11月22日台財產署管字第11040011580號函。\n二、按下水道法第19條規定：「下水道機構，應於下水道開始使用前，將排水區域、開始使用日期、接用程序及下水道管理規章公告週知。下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道之內。」同法第20條規定：「用戶排水設備之管理、維護，由下水道用戶自行負責。」同法第29條規定：「主管機關對於未依規定期限，設置用戶排水設備並完成與下水道聯接使用者，除依第32條規定處罰外，並得命下水道機構代為辦理，所需費用由下水道用戶負擔。」另同法施行細則第17條規定：「下水道可使用之地區，其用戶應於依本法第19條第1項所定公告開始使用之日起6個月內與下水道完成聯接使用。」合先敘明。\n三、故依上開規定意旨，在下水道可使用之地區，其用戶應自行負責設置用戶排水設備並與下水道完成聯接使用。惟委員就貴署101年11月2日台財產局管字第10140023011號函示相關處理原則，質詢「部分老舊建物於50年內有拆除重建之可能，該償金收取年期過長且無退還機制」等規定是否合宜之疑慮，建請貴署依權責妥為處理。\n四、旨案所詢雨水下水道完成後是否需依下水道法第19條規定公告周知1事，請依上開說明辦理。","refs":["A29"]},{"id":"r231","agency":"內政部營建署","date":"110.12.23","docNo":"內授營環字第1100819229號","y":110,"src":"111年更新","brief":"貴事務所函詢下水道用戶排水設備標準第2條第2款「污水管渠」之定義範圍","text":"一、依據本部營建署案陳貴事務所110年12月2日(108)直域(中)字第1081708194號函辦理。\n二、按下水道法第2條第1項第6款規定，用戶排水設備指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備，其涵蓋範圍請參照本部營建署93年9月23日營署工程字第0930060230號函略以，建築物內之給排水設備屬建築物範疇，由建築師依據建築技術規則設計，為便於公共下水道之接管作業，應將雨、污水分流設置。建築物外，連接下水道之下水道管材、陰井、人孔及銜接建築物之污水管線之用戶排水設備，均屬下水道範疇……。\n三、故下水道用戶排水設備標準第2條第2款所稱之污水管渠，應為建築物外，連接下水道之下水道管材、陰井、人孔及銜接建築物之污水管線，而建築物內之污水管線則屬建築物給排水設備範疇。","refs":["other"]},{"id":"r232","agency":"內政部營建署","date":"110.12.24","docNo":"內授營環字第1100819136號","y":110,"src":"111年更新","brief":"貴局函詢下水道用戶排水設備承裝商管理規則第8條及第16條因門牌整編變更營業許可是否須收取審查費及證照費等疑義","text":"一、依據本部營建署案陳貴局110年11月11日新北水設字第1102180195號函辦理。\n二、依規費法第7條第1項規定，「各機關學校為特定對象之權益辦理下列事項，應徵收行政規費。但因公務需要辦理者，不適用之」其中辦理事項包含「審查」及「證明或許可證之核發」，爰下水道用戶排水設備承裝商管理規則第16條規定，「下水道承裝商申請籌設許可、申請或變更營業許可，應繳交審查費新臺幣二千元；申請核發、補（換）發營業許可證書、承辦工程手冊或承裝技工工作證者，應繳交證冊費每份新臺幣二百元。」，屬規費法授權業務主管機關徵收之規費，先予述明。\n三、旨案所詢因門牌整編而變更地址（實際未遷移），申請變更營業許可是否須收取審查費及證照費情事，於下水道用戶排水設備承裝商管理規則尚無規定，建議參酌規費法第7條第1項免繳規費之要件，本諸權責自行認定。","refs":["other"]},{"id":"r233","agency":"內政部營建署","date":"111.8.25","docNo":"內授營環字第1110815645號","y":111,"src":"111年更新","brief":"貴府函詢下水道用戶排水設備承裝商管理規則第3條第1項第2款「置有專任承裝技工2人以上」相關疑義","text":"一、依據本部營建署案陳貴局111年7月18日新北水污計字第1111345950號函辦理。\n二、有關「專任」之意涵，依據司法院釋字第 456 號理由書第二段所說明，行政院勞工委員會77年8月4日台（77）勞保二字第 16786號函復就「專任員工」解釋，指受僱勞工於僱用單位之工作時間內全部在僱用單位服務；或受僱用單位之支配，於室外服務，並依規定支領全部時間之報酬者而言。如僅以部分時間為僱用人工作，支領部分工時之報酬者，則非專任人員。\n三、該承裝商之專任承裝技工擔任某工程之工地主任、品管人員、安衛人員或其他合約人員之職務，倘承攬單位為該專任承裝技工任職之下水道用戶排水設備承裝商，表示該專任承裝技工僱主不變，仍滿足承裝技工「專任」之定義。\n四、惟有關工地主任、品管人員、安衛人員或其他合約人員之職務是否須符合「專職」之規定，仍需依各類人員主管法規及個案契約規定辦理。","refs":["other"]},{"id":"r234","agency":"內政部營建署","date":"111.9.20","docNo":"內授營環字第1110816778號","y":111,"src":"111年更新","brief":"貴局函詢下水道用戶排水設備承裝商（以下簡稱承裝商）未依下水道用戶排水設備承裝商管理規則第3條及第 15條改善辦理，直轄市、縣（市）主管機關是否可廢止承裝商營業資","text":"一、依據本部營建署案陳貴局111年8月22日新北水污計字第1111583878號函辦理。\n二、依據下水道用戶排水設備承裝商管理規則（以下簡稱承裝商管理規則）第3條規定：「下水道承裝商應置有專任承裝技工二人以上。」同法第15條第1項規定：「專任承裝技工離職或因故不能執行業務時，承裝商應即報請直轄市、縣（市）主管機關備查，並應於三個月內另行聘僱。」合先敘明。\n三、有關行政執行法第27條，依法令或本於法令之行政處分，負有行為或不行為義務，指行政處分生效後，受處分者即依法令負有處分規定之義務。現行承裝商管理規則第15條無相關停止營業、撤銷證照之規定，依行政執行法第27條第1項，依法令或本於法令之行政處分，應為命承裝商3個月內另行聘僱合格之技工為專任技工，而非針對處分義務逾期者，依行政執行法第28條第2項規定，採取撤照之執行程序，如該承裝商仍未於期限內補足規定數量之專任技工時，得另依相關工程採購規範辦理 。\n四、旨案所詢下水道用戶排水設備承裝商未依下水道用戶排水設備承裝商管理規則第3條及第15條改善辦理，直轄市、縣（市）主管機關是否可廢止承裝商營業資格行政處分之疑義1事，請依上開說明辦理。","refs":["other"]},{"id":"r235","agency":"內政部營建署","date":"111.10.26","docNo":"內授營環字第1110818303號","y":111,"src":"111年更新","brief":"貴府函詢下水道用戶排水設備承裝商未依下水道用戶排水設備承裝商管理規則第15條規定，於三個月內另行聘僱專任技工之執行疑義","text":"一、依據本部營建署案陳貴府111年10月7日府水下字第1110154282號函辦理。\n二、依據下水道用戶排水設備承裝商管理規則（以下簡稱承裝商管理規則）第3條規定：「下水道承裝商應置有專任承裝技工二人以上。」同法第15條第1項規定：「專任承裝技工離職或因故不能執行業務時，承裝商應即報請直轄市、縣（市）主管機關備查，並應於三個月內另行聘僱。」合先敘明。\n三、經查本部111年9月20日內授營環字第1110816778號函釋略以，行政執行法第27條，依法令或本於法令之行政處分，負有行為或不行為義務，指行政處分生效後，受處分者即依法令負有處分規定之義務。現行承裝商管理規則第15條無相關停止營業、撤銷證照之規定，依行政執行法第27條第1項，依法令或本於法令之行政處分，應為命承裝商3個月內另行聘僱合格之技工為專任技工，而非針對處分義務逾期者，依行政執行法第28條第2項規定，採取撤照之執行程序，如該承裝商仍未於期限內補足規定數量之專任技工時，得另依工程契約及其相關規範辦理 。\n四、旨案所詢下水道用戶排水設備承裝商未依下水道用戶排水設備承裝商管理規則第15條規定，於三個月內另行聘僱專任技工之執行疑義，請依上開說明辦理。","refs":["other"]},{"id":"r236","agency":"內政部","date":"112.12.18","docNo":"內授國水建字第1120833043號","y":112,"src":"114年更新","brief":"貴府函詢雨水流出抑制設施是否屬下水道法用戶排水設備案","text":"依據本部國土管理署案陳貴府112年12月1日府授工水字第1126065441號函辦理。\n按下水道法第2條第1項第6款規定，用戶排水設備係指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備；次查臺北市基地開發排入雨水下水道逕流量標準第3條第1項第3款規定，雨水流出抑制設施指控制排放雨水逕流量至基地外之設施。\n另查本部107年1月10日內授營環字第1070800533號函略以，「雨水流出抑制設施……，究其功能為暫時儲存逕流量以防止過度集中流出，減輕下游管渠負荷，須透過水文分析及水理計算使其具排水調節及緩衝效能，並確保鄰近雨水下水道系統通洪能力，該設施無論設置於建築物內外，其所收集建築物或基地內之雨水逕流，如排放至雨水下水道系統，仍應考慮雨水下水道系統之負荷，故所涉下水道範疇，應依下水道法第17條及下水道法施行細則第13條規定辦理。」爰所詢「重力式或機械抽排之貯集滯洪池形式之雨水流出抑制設施及相關貯集滯洪池之聯外排水管路」，如屬收集建築物或基地內之雨水逕流並連接至雨水下水道之設備，自得認定為用戶排水設備。","refs":["A2"]},{"id":"r237","agency":"內政部","date":"113.4.30","docNo":"內授國水建字第1130804430號","y":113,"src":"114年更新","brief":"貴局函詢「建築技術規則建築設計施工編」之雨水貯集滯洪設施及「新北市透水保水自治條例」之透水保水設施，是否屬「下水道法」適用之範疇事宜","text":"依據本部國土管理署案陳貴局113年4月15日新北水河計字第1130700062號函辦理。\n依下水道法第2條第1項第2款及第6款規定：「本法用辭定義如左：……二、下水道：指為處理下水而設之公共及專用下水道。……六、用戶排水設備：指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備。」\n次按本部國土管理署（前營建署）93年9月23日營署工程字第0930060230號函略以，「建築物內之給排水設備屬建築物範疇，由建築師依據建築技術規則設計，為便於公共下水道之接管作業，應將雨、污水分流設置。建築物外，連接下水道之下水道管材、陰井、人孔及銜接建築物之污水管線之用戶排水設備，均屬下水道範疇…。」故雨、污水下水道及有關之用戶排水設備均屬下水道範疇。\n另查貴市「新北市透水保水技術規則」第2條第1項第1款規定：「透水保水設施：指具有使自然土層或人工土層涵養、滲透及貯留雨水能力之設施。」及同技術規則附表一相關設施類型包含：「綠地、被覆地、草溝、透水鋪面、人工地盤花園土壤雨水截留設施、貯集滲透空地、景觀貯集滲透水池、地下貯集滲透設施、滲透排水管、滲透陰井、滲透側溝、雨水貯留再利用設施、雨水貯集滯洪設施」等，爰貴市之透水保水設施已包含「建築技術規則建築設計施工編」之雨水貯集滯洪設施。\n綜上，考量貴市之透水保水設施態樣眾多，是否屬收集建築物或基地內之雨水逕流並排放至雨水下水道系統之用戶排水設備，應由貴局依實認定，如非屬用戶排水設備，自無下水道法之適用。","refs":["A2"]},{"id":"r238","agency":"內政部營建署","date":"111.11.15","docNo":"營署水字第1111239880號","y":111,"src":"114年更新","brief":"貴事務所函詢「建築基地是否設置專用下水道相關標準及規定」疑義","text":"復貴事務所111年10月20日黎字第1111020001號函。\n按刑法第10條第1項規定：「稱以上、以下、以內者，俱連本數……計算。」參照前開規定，法制用語所稱「以上、以下、以內者」，包含該本數計算，合先敘明。\n次按下水道法施行細則第4條第1項第1款規定：「本法第8條所稱新開發社區、工業區，係指符合下列條件之地區，其申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者：一、新開發社區：可容納500人以上居住或總計興建100住戶以上之社區。」同法施行細則同條第2項規定：「前項第1款之新開發社區，其人口計算基準如左：一、實施都市計畫地區：以建築物污水處理設施設計技術規範所定使用人數方式計算。二、實施都市計畫以外地區：以每人使用30平方公尺之樓地板面積計算。」另查內政部84年9月14日台（84）內營字第 8480366 號函函釋有關新開發社區設置專用下水道之原則及流程略以，「……專用下水道，其設置原則如下：1.可容納500人以上居住或總計興建100戶以上者。2.主管機關認定之社區。」\n故依上開規定，建築基地個別申請建照時，如戶數未達100戶，仍需依下水道法施行細則第4條第2項規定核算該建築之使用人數，若達500人以上，且申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者，仍應依法設置專用下水道；惟考量各建築基地所處環境差異，如該地區或場所產生之污染量有污染之虞時，雖未達前開標準，主管機關仍得指定其應設置專用下水道。\n另經主管機關認定無須設置專用下水道者，仍請依環保及建築法令規定設置相關污水處理設施，以達處理生活污水，防治水污染之目的。","refs":["A8","R4"]},{"id":"r239","agency":"內政部","date":"112.6.27","docNo":"內授營環字第1120808696號","y":112,"src":"114年更新","brief":"貴府函詢「竹山鎮柯子坑新社區公共設施管理維護」專用下水道1案","text":"依據本部營建署案陳貴府112年6月6日府工道字第1120129500號函辦理。\n按下水道法第8條第1項規定「政府機關或公營事業機構新開發社區、工業區或經直轄市、縣（市）主管機關指定之地區或場所，應設置專用下水道，由各該開發之機關或機構建設、管理之。」另依下水道法施行細則第4條第1項第1款規定「本法第8條所稱新開發社區、工業區，係指符合下列條件之地區，其申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者：一、新開發社區：可容納500人以上居住或總計興建100住戶以上之社區。」合先敘明。\n旨揭社區雖因實際住戶未達100人，惟仍請貴府先行確認其污染量是否有污染之虞，如認為有污染之虞者，仍得指定其設置專用下水道。\n另旨揭社區為921地震後興建，適用87年7月2日修正發布之「建築技術規則建築設計施工編」第49條規定，若經評估免設置專用下水道，仍應依規定改設置建築物污水處理設施，並依相關建築法令規定妥處；至該社區之專用污水下水道得否解除水污染防治法之列管，建請另洽環保主管機關釐清。","refs":["A8","R4"]},{"id":"r240","agency":"內政部","date":"113.7.10","docNo":"內授國水建字第1130807398號","y":113,"src":"114年更新","brief":"貴府函詢「擬定桃園國際機場園區及附近地區特定區計畫（第一階段）」區段徵收範圍新設污水下水道是否適用下水道法相關規定1案","text":"依據本部國土管理署案陳貴府113年6月11日府經開字第1130159349號函辦理。\n依下水道法第3條規定，「本法所稱主管機關︰在中央為內政部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。」同法第8條第1項規定，「政府機關或公營事業機構新開發社區、工業區或經直轄市、縣（市）主管機關指定之地區或場所，應設置專用下水道，由各該開發之機關或機構建設、管理之。」同法第9條規定，「中央、直轄市及縣（市）主管機關，為建設及管理下水道，應指定或設置下水道機構，負責辦理下水道之建設及管理事項。」同法第19條規定，「下水道機構，應於下水道開始使用前，將排水區域、開始使用日期、接用程序及下水道管理規章公告週知。下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道之內。」\n次依下水道法施行細則第4條第1項第2款規定，「本法第八條所稱新開發社區、工業區，係指符合下列條件之地區，其申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者：二、新開發工業區：（一）政府機關、公民營事業機構開發供事業設廠之地區。（二）事業於政府依法劃設供工業使用之土地設廠，其基地面積達二公頃以上者。」另查本部87年12月9日台內營字第8773453號函，「有關下水道法施行細則第4條第1項第2二款第1目所稱『供事業設廠之地區』，指凡經政府機關、公民營事業機構以『整體開發』方式開發之工業區皆屬之，無需規定規模之大小。」\n本案係於「擬定桃園國際機場園區及附近地區特定區計畫」規劃桃園國際機場園區南側劃設產業專用區、乙種工業區及零星住宅區範圍，並已規劃建設專用污水下水道，已符合下水道法第8條第1項規定，並應依下水道法第19條規定辦理相關公告週知作業，與其為公共或專用下水道無涉。\n另貴府為下水道法直轄市主管機關，轄內下水道建設、管理、監督、輔導，自可依下水道法第9條所賦予之權責指定該專用下水道之下水道機構，亦與下水道之屬性無涉。","refs":["A8"]},{"id":"r241","agency":"內政部","date":"111.12.7","docNo":"內授營環字第1110820863號","y":111,"src":"114年更新","brief":"所詢「自辦農村社區土地重劃區內污水處理廠管理維護及後續處理」相關疑義","text":"依據本部營建署案陳申請人呂君111年9月2日申請函辦理；併復新竹縣政府111年9月19日府工水字第1113637214號函。\n依農村社區土地重劃條例第11條第2項規定「重劃區內規劃之道路、溝渠、電信電力地下化、下水道、廣場、活動中心、綠地及重劃區內土地所有權人認為為達現代化生活機能必要之其他公共設施用地，……由參加重劃土地所有權人按其土地受益比例共同負擔。」同條例施行細則第5條第1項亦明定，土地所有權人共同負擔之公共設施用地項目，應載明於農村社區土地重劃計畫書。爰個案自辦農村社區土地重劃區內污水處理廠用地是否屬農村社區土地重劃條例及相關子法所稱公共設施用地，應視其農村社區土地重劃計畫書所載內容而定，合先敘明。\n另查農村社區土地重劃條例第30條及土地所有權人辦理農村社區土地重劃辦法第38條、第43條規定，重劃區內共同負擔之公共設施用地，登記為直轄市或縣（市）有，管理機關為各該公共設施主管機關；重劃工程完竣後，重劃會應會同各該工程主管機關驗收合格後，送請各該工程主管機關接管養護。故自辦農村社區土地重劃區內之公共設施接管養護，應依前開規定辦理。\n次按下水道法第2條第1項第4款規定「專用下水道：指供特定地區或場所使用而設置尚未納入公共下水道之下水道。」同法第6條第1項第3款規定「縣主管機關辦理左列事項：……三、縣屬下水道之管理。」同法第8條第2項規定「私人新開發社區、工業區或經直轄市、縣（市）主管機關指定之地區或場所，應設置專用下水道。但必要時，得由當地政府、鄉（鎮、市）公所或指定有關之公營事業機構建設、管理之。」同法施行細則第4條第1項第1款規定「本法第8條所稱新開發社區、工業區，係指符合下列條件之地區，其申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者：一、新開發社區：可容納500人以上居住或總計興建100住戶以上之社區。」自辦農村社區土地重劃區之開發單位屬重劃會，如社區規模滿足前開規定，亦符合下水道法第8條第2項所稱「私人新開發社區」應設置專用下水道。\n另自辦農村社區土地重劃區內之專用下水道或污水處理廠，如經公共設施主管機關接管養護後，下水道地方主管機關應依下水道法第9條規定，指定或設置下水道機構負責辦理下水道之管理事項。至新竹縣政府另行訂定自治法規或於個案開發計畫中，規範污水處理廠管理維護權責，因屬地方自治事項，應由新竹縣政府本於權責卓處。","refs":["A9"]},{"id":"r242","agency":"內政部","date":"113.1.31","docNo":"內授國水建字第1130801009號","y":113,"src":"114年更新","brief":"貴府函詢有關下水道法第14條償金發放標準1案","text":"依據本部國土管理署下水道工程分署案陳貴府113年1月10日府工水字第1130015440號函辦理。\n按下水道法第2條第6款所稱「用戶排水設備」，指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備，其立法旨意，用戶排水設備之物權屬用戶私有，應由用戶自行負責建設、管理。\n次按下水道法第14條第1項規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。」復按本部91年2月5日內授營工程字第0910002811號函釋略以，「……其立法原意，下水道在公、私有土地下埋設供『公共使用』管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償。……在既成道路或計畫道路私有土地下埋設管渠或其他設備，係作為連接公共污水下水道非供公共使用之私有用戶排水設備，即便由下水道機構代為施工，並以公務預算支應，核與第14條之性質迥異，自無支付償金問題。」\n又查本部國土管理署（原營建署）94年2月14日營署工程字第0942902317號函略以，「……分界點至污水下水道用戶端土地所有權人非污水下水道用戶者，下水道主管機關於其土地埋設管渠，應給予補償。」爰公、私分界點至污水下水道用戶端之土地非屬污水下水道用戶者，下水道主管機關於其土地埋設供「公共使用」管渠，應給予補償。\n所詢污水下水道工程案件是否適用下水道法第14條規定1事，請貴府本諸權責先行釐清施作之污水下水道管渠，是否屬公共使用之污水管渠，並依上開原則辦理。","refs":["A14"]},{"id":"r243","agency":"內政部","date":"113.5.10","docNo":"內授國水建字第1130804970號","y":113,"src":"114年更新","brief":"貴局為「臺中市豐原區污水下水道系統第一期管線暨用戶接管工程(1)-豐原大道及田心路等鄰近區域」土地所有權人(豐田段99-1地號)之異議報請本部核定案","text":"復貴局113年4月30日中市水污設字第1130035432號函。\n按下水道法第14條第1項規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。」依前開意旨，係指下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償，如其土地所有人、占有人或使用人對於施工處所、方法之選擇或支付償金額度有異議時，始由中央主管機關核定。\n查本案土地所有權人之異議係拆除復原或希以徵收其土地之方式辦理，非對處所及方法之選擇或支付償金提具異議，與下水道法規定不符，非屬本部核定範疇。另旨揭土地埋設之公共污水下水道管線如已屬損害最少之處所及方法，自應依下水道法第14條規定辦理，並依據貴市訂定之「臺中市下水道工程使用土地支付償金及補償費標準」支付償金尚無疑義。","refs":["A14"]},{"id":"r244","agency":"內政部","date":"113.7.5","docNo":"內授國水建字第1130807493號","y":113,"src":"114年更新","brief":"貴府函詢有關仁武區八德東路施作污水下水道推進工程，因工程必要需經農業部農田水利署所屬土地，是否適用下水道法第14條規定案","text":"復貴府113年7月2日高市府水污二字第11335375700號函。\n依據下水道法第14條第1項規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。查其立法原意，係指下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償，合先敘明。\n本案貴府因施作污水下水道推進工程上之必要，須經農業部農田水利署所屬土地，如已擇其損害最少之處所及方法為之，應依下水道法第14條第1項規定辦理。","refs":["A14"]},{"id":"r245","agency":"內政部","date":"113.8.9","docNo":"內授國水建字第1130809160號","y":113,"src":"114年更新","brief":"貴局預計於太平區民眾私有住宅區用地（宜欣段879地號）埋設公共污水管線1案","text":"復貴局113年8月5日中市水污設字第1130068279號函。\n按下水道法第14條前段規定，「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方式為之，並應支付償金。」其立法原意，係指下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，且所稱之「必要」指下水道工程依據下水道工程設施標準辦理規劃、設計，實無其他適合路線或位置可供埋設管渠或其他設備。\n另查下水道法第20條規定，用戶排水設備之管理、維護，由下水道用戶自行負責，用戶排水設備屬用戶接用下水道之私有設備，尚無下水道法第14條之適用。\n本案工程預計使用民眾私有住宅區用地埋設公共污水管線，該管線究係屬供公共使用之管渠或係屬用戶排水設備，請貴局本於權責釐清，並依前開規定辦理。","refs":["A14"]},{"id":"r246","agency":"內政部","date":"113.9.25","docNo":"內授國水建字第1130811417號","y":113,"src":"114年更新","brief":"貴府函轉經濟部水利署臺北水源特定區管理分署執行下水道工程涉及使用土地補償金擬比照「新北市下水道工程使用土地補償標準」辦理，是否需辦理公告事宜","text":"復貴府113年9月6日新北府水污計字第1131760376號函。\n按下水道法第9條規定：「中央、直轄市及縣（市）主管機關，為建設及管理下水道，應指定或設置下水道機構，負責辦理下水道之建設及管理事項。」同法第14條第1項規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。」同法施行細則第10條規定：「本法第十四條、第十六條規定支付之償金或補償，其標準由直轄市、縣（市）主管機關訂定之。」合先敘明。\n次依新北市下水道工程使用土地補償標準第2條第1項規定：「下水道機構依下水道法（以下簡稱本法）第十四條規定使用公、私有土地，有支付土地所有權人償金之必要時，以發給一次為限。」\n經查經濟部水利署臺北水源特定區管理分署業經貴府112年10月2日公告指定為新北市轄內水源特定區之污水下水道機構，自得依下水道法第9條之規定，辦理下水道建設及管理相關事項，包含依下水道法第14條支付償金；惟下水道法施行細則第10條並未授權下水道機構訂定下水道法第14條之償金支付標準，爰此，經濟部水利署臺北水源特定區管理分署援引貴府所訂定之「新北市下水道工程使用土地補償標準」辦理相關補償作業，尚無疑義。\n另依行政程序法第131條第1項規定：「公法上之請求權，於請求權人為行政機關時，除法律另有規定外，因五年間不行使而消滅；於請求權人為人民時，除法律另有規定外，因十年間不行使而消滅。」次查最高行政法院106年判字第87號判決：「……修正後自來水法第53條乃授權經濟部訂定該準則……該裁量準則係就母法所稱損害之程度及補償之範圍予以界定，並就補償之裁量基準予以具體化，應自母法生效之日起有其適用。……土地所有權人依自來水法第53條第1項規定之補償請求權，為公法上請求權，亦應於得請求時起適用一般之公法上請求權時效期間規定，以免此請求權之是否行使長久陷於不確定狀態，而有礙法秩序之安定。該補償請求權依規定係為支付一次性的補償（償金），已如前述，自以主管機關依法行使公權力為埋設管線時即為自來水法第53條規定補償請求權之得請求時。」\n參照最高行政法院106年判字第87號判決意旨，自來水法第53條之規定與下水道法第14條，其立法目的均係補償人民因國家行使公權力所致之特別犧牲，應得類推適用其執行方式，惟行政程序法係屬法務部權責，建請洽該部釐清。","refs":["A14"]},{"id":"r247","agency":"內政部","date":"114.1.23","docNo":"內授國水建字第1140800848號","y":114,"src":"114年更新","brief":"貴局辦理「鳳山溪污水區第四期第五標工程（II）」於大寮區崇仁街8巷及民和街施作污水下水道連接管工程，因工程必要需經民眾所屬私有土地，是否適用下水道法第14條規定","text":"復貴局114年1月16日高市水污二字第11430428300號函。\n依據下水道法第14條第1項規定，下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。查其立法原意，係指下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償，合先敘明。\n依前開意旨，本案污水下水道連接管工程施作如經貴局認定係屬供公共使用之管渠，且已採損害最少之處所及方法，即應依下水道法第14條及下水道法施行細則第7條規定辦理，並依據貴府訂定之「高雄市下水道工程使用土地支付償金及補償費標準」支付償金。","refs":["A14"]},{"id":"r248","agency":"內政部","date":"114.1.24","docNo":"內授國水建字第1140800849號","y":114,"src":"114年更新","brief":"貴府規劃於貴市松山區敦化北路道路下方設置貯留管，依下水道法第14條規定報請本部核定1案","text":"依據本部國土管理署案陳貴府114年1月9日府授工水字第1146008400號函辦理。\n按下水道法第14條第1項規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。」查其立法原意，係指下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償，合先敘明。\n次查本部110年8月10日內授營環字第1100812751號函說明，下水道法第14條所稱之「必要」指下水道工程依據下水道工程設施標準辦理規劃、設計，實無其他適合路線或位置可供埋設管渠或其他設備，依其意涵「其他設備」係指下水道工程設施標準所稱之「雨、污水管渠及其附屬設施」。\n貴府辦理「敦化北路貯留設施新建工程」規劃以潛盾工法於旨揭道路下方設置管渠用以收納雨水，其施工路徑經農業部農田水利署所持分之土地，如經貴府認定符合上開規定，自應依相關規定辦理。\n另查本案農業部農田水利署希以有償撥用或容積調派方式辦理，非對處所及方法之選擇或支付償金提具異議，與下水道法規定不符，非屬本部依前開規定核定之範疇。","refs":["A14"]},{"id":"r249","agency":"內政部","date":"112.3.10","docNo":"內授營環字第1120803073號","y":112,"src":"114年更新","brief":"貴局函詢「污水下水道用戶接管，如係於雨水排水溝或於住戶、建設公司自行建築之暗溝，將污水截流至污水下水道設施之施作方式，是否仍得視為已完成用戶接管」1案","text":"復貴局112年2月13日新北水污計字第1120256216號函。\n依據下水道法第22條第1項規定：「用戶排水設備須經下水道機構檢驗合格，始得聯接於下水道。其檢驗不合格者，下水道機構應限期責令改善。」，又依據下水道用戶排水設備標準第3條「用戶排水設備之新設、增設、改設或拆除，應依本標準規定設置」及第4條「污水管渠及雨水管渠應分開設置，不得混接。」，施作時應符合前述規定。\n有關檢驗未合格之用戶排水設備，無法聯接於下水道，且下水道機構應令其改善，自無法將其視為已完成之用戶接管戶，惟該個案細節認定，請貴局依相關規定本於權責辦理。","refs":["A22"]},{"id":"r250","agency":"內政部","date":"114.2.12","docNo":"內授國水建字第1140801507號","y":114,"src":"114年更新","brief":"貴局函詢「私接用戶排水設備未經檢驗合格而聯接於下水道」事宜一案","text":"依據本部國土管理署案陳貴局114年1月23日高市水行字第11430830000號函辦理。\n依據下水道法第 22 條第 1 項規定：「用戶排水設備須經下水道機構檢驗合格，始得聯接於下水道。其檢驗不合格者，下水道機構應限期責令改善。」，又依同法第 32 條第 1 項第 2 款規定：「下水道用戶有下列情事之一者，處新臺幣一萬元以上十萬元以下罰鍰：…二、違反第二十二條規定，未經檢驗合格而聯接使用，或經檢驗不合格而不依限期改善者。」，施作時應符合前述規定且檢驗不合格者應依下水道機構之指示限期改善，否則即得依下水道法裁處罰鍰。\n有關民眾未提出申請用戶排水設備檢驗合格，即私自將用戶排水設備接入公共污水下水道系統一事，自屬下水道法第 22 條第 1 項規定之範疇，建議貴局應本於權責卓處之。\n另，貴府訂定之高雄市污水下水道使用管理自治條例亦有類似下水道法第 22 條第 1 項、第 32 條第 1 項第 2款規定，僅為罰鍰額度不同，建議貴局宜參酌斯時之立法原意後一併考量，併此敘明。","refs":["A22"]},{"id":"r251","agency":"內政部","date":"114.6.2","docNo":"內授國水建字第1140807070號","y":114,"src":"115年更新","brief":"新北市新店區秀岡1段67號、秀岡三街94號之人孔蓋、污水處理廠及附屬管線是否為下水道法第31條所定義之下水道主要設備1案","refs":["A2"],"text":"有關貴局函詢新北市新店區秀岡1段67號、秀岡三街94號之人孔蓋、污水處理廠及附屬管線是否為下水道法第31條所定義之下水道主要設備1案，復如說明，請查照。\n復貴局114年5月8日新北水污計字第1140893826號函。\n依下水道法第2條第2款規定「下水道：指為處理下水而設之公共及專用下水道。」；同法第10條規定「下水道工程設施標準，由中央主管機關定之。」；同法第31條規定「毀損下水道主要設備或以其他行為使下水道不堪使用或發生危險者，處6月以上5年以下有期徒刑，得併科5,000元以上5萬元以下罰金。」；同法施行細則第19條規定「本法第31條所稱下水道主要設備如左：一、下水道系統管渠、放流口及其附屬設施。二、下水道抽水站設施及其相關設備。三、下水道處理廠設施及其相關設備。四、其他有關下水道重要設施。」合先敘明。\n復依下水道法第2條第6款規定「用戶排水設備：指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備。」；同法第22條第2項規定「用戶排水設備之標準，由中央主管機關定之。」爰用戶排水設備應由下水道用戶依下水道用戶排水設備標準相關規定設置之。\n依前開規定，下水道主要設備應屬下水道工程設施之範疇，並應依下水道工程設施標準相關規定設置，故來函所詢「人孔蓋、污水處理廠及附屬管線」，應視其屬性（下水道工程設施或用戶排水設備）及相關事實予以認定，若為「下水道工程設施」自屬「下水道主要設備」範疇，請貴局本諸權責依據個案情形認定之。"},{"id":"r252","agency":"內政部","date":"115.6.22","docNo":"內授國水建字第1150807840號","y":115,"src":"115年更新","brief":"豐原區南陽里附近公共污水下水道公告使用區域範圍內，民眾於同棟大樓擁有不同樓層建物所有權，倘未依限接入公共污水下水道，是否得依下水道法第32條第1項第…","refs":["A2"],"text":"貴局函詢就豐原區南陽里附近公共污水下水道公告使用區域範圍內，民眾於同棟大樓擁有不同樓層建物所有權，倘未依限接入公共污水下水道，是否得依下水道法第32條第1項第1款規定分別裁罰1案，復如說明，請查照。\n復貴局115年5月15日中市水污設字第1150052484號函。\n按下水道法第2條第5款規定：「下水道用戶：指依下水道法及下水道管理規章接用下水道者。」同法第19條規定：「（第1項）下水道機構，應於下水道開始使用前，將排水區域、開始使用日期、接用程序及下水道管理規章公告週知。（第2項）下水道排水區域內之下水，除經當地主管機關核准者外，應依公告規定排洩於下水道之內。」同法施行細則第17條規定：「下水道可使用之地區，其用戶應於依本法第19條第1項所定公告開始使用之日起6個月內與下水道完成聯接使用。」另同法第32條第1項第1款規定：「下水道用戶有下列情事之一者，處新臺幣1萬元以上10萬元以下罰鍰：一、不依規定期限將下水排洩於下水道者。」\n次按行政罰法第24條第1項規定：「一行為違反數個行政法上義務規定而應處罰鍰者，依法定罰鍰額最高之規定裁處。但裁處之額度，不得低於各該規定之罰鍰最低額。」同法第25條規定：「數行為違反同一或不同行政法上義務之規定者，分別處罰之。」又行為人之違規行為，究應評價為單一行為或數個行為，應兼顧達成規範目的之必要性，與違規行為構成要件該當性，不得有評價不足或重複評價之情形。因此，違規行為之個數判斷，必須就具體個案之事實情節，依據行為人主觀犯意、構成要件實現、受侵害法益及所侵害法律效果，斟酌被違反行政法上義務條文文義、立法意旨、制裁意義、期待可能性與社會通念等因素綜合判斷決定（最高行政法院109年度判字第541號行政判決及臺北高等行政法院高等庭113年度訴字第908號行政判決參照）。\n下水道法所稱「下水道用戶」，係行政管理及識別規範對象之概念，得依實際接用下水道之獨立使用單元（如門牌戶）分別認定。查本案系爭7戶建物各具獨立門牌，且均有污水產生，原則上均得視為下水道法所稱之下水道用戶。惟於適用同法第32條第1項第1款規定裁處罰鍰時，門牌數量或建物所有權標的數量，僅係認定用戶及義務主體之參考因素之一，主管機關仍應依行政罰法第7條規定，審酌個別用戶未於期限內完成聯接使用之原因、履行義務之期待可能性及其是否具有故意或過失等情形，綜合判斷是否具有可歸責事由。倘其對建物用戶排水設備之設置、聯接及管理具有實際支配能力，並屬依法應完成聯接使用之義務主體，而逾期未完成聯接使用者，始得認定為裁罰對象。\n另「下水道用戶數量」之認定，與「違反聯接使用義務行為數」之判斷，二者規範目的及認定基準尚屬有別。爰本案仍請貴府就個案具體事實，查明系爭建物之污水排放系統配置情形、接管工程內容、各接管單元是否具獨立性，以及依法應負聯接使用義務者對相關設施之實質支配能力與履行期待可能性等因素，綜合判斷其違規事實究屬單一違規行為或數個違規行為，並依下水道法及行政罰法相關規定辦理。"},{"id":"r253","agency":"內政部","date":"115.7.14","docNo":"內授國水建字第1150809029號","y":115,"src":"115年更新","brief":"臺北市政府工務局公園路燈工程管理處「107年度實驗性公園兒童遊戲場改善工程」之高程排水、設置透水陰井、HDPE透水網管及淺溝等工項是否屬下水道工程…","refs":["A2"],"text":"貴會函詢有關臺北市政府工務局公園路燈工程管理處「107年度實驗性公園兒童遊戲場改善工程」之高程排水、設置透水陰井、HDPE透水網管及淺溝等工項是否屬下水道工程範疇1案，復如說明，請查照。\n復貴會115年6月29日工程技字第1150200787號函。\n按下水道法第2條第2款規定「本法用辭定義如左：二、下水道：指為處理下水而設之公共及專用下水道」；次依同法施行細則第3條第1款規定「本法所稱下水道分為左列三種：一、雨水下水道：專供處理雨水之下水道」；復依下水道工程設施標準第2條第1款規定「本標準用詞，定義如下：一、下水道工程設施：管渠、抽水站、污水處理廠及其相關設施」，合先敘明。\n查臺北市政府工務局公園路燈工程管理處115年6月23日北市工公港字第1153033806號函「107年度實驗性公園兒童遊戲場改善工程」目的係為改善地坪綠地積水，爰利用透水陰井及淺溝，將該工區範圍原有逕流排至透水陰井，再導引至公園內既有排水系統內。\n針對設置透水陰井、HDPE透水網管及淺溝等性質，參照「建築基地保水設計技術規範」6.7滲透陰井設計，包含滲透管、滲透陰井、滲透側溝及高密度聚乙烯(HDPE)透水網管等設施，係將基地內無法自然入滲之降水集中後，透過管壁或井體孔隙使降水自然滲透至土壤，以達輔助入滲及基地保水效果；同規範6.8 滲透側溝設計，則是收集屋頂排水或表面逕流水的地表排水系統。另參照「水環境低衝擊開發設施操作手冊」亦將滲透側溝、滲透陰井列為低衝擊開發設施，主要功能為貯留、入滲及延遲逕流，屬場域內暴雨逕流管理及減洪設施。\n綜上，旨揭工程「高程排水、透水陰井、HDPE透水網管及淺溝」等工項，主要功能係處理公園基地內地表逕流、雨水入滲、貯留及透排水需求，性質上較屬基地保水、低衝擊開發設施、雨水逕流抑制設施及場域內排水工程，未涉及公共雨水下水道系統施作，爰不屬於下水道工程範疇。"},{"id":"r254","agency":"內政部","date":"115.7.14","docNo":"內授國水建字第1150808385號","y":115,"src":"115年更新","brief":"建築物內部使用黑色塑化類排水管，是否適用「下水道用戶排水設備標準」第32條橘紅色管材規定1案","refs":["A2"],"text":"有關貴公司函詢建築物內部使用黑色塑化類排水管，是否適用「下水道用戶排水設備標準」第32條橘紅色管材規定1案，復如說明，請查照。\n依據本部國土管理署案陳貴公司115年6月25日水之道字第1150625號函辦理。\n按下水道法第2條第6款規定：「用戶排水設備：指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備。」次按下水道用戶排水設備標準第2條第2款規定：「本標準用語定義如下：……二、污水管渠：指專供排洩家庭污水或事業廢水之管渠。」同標準第32條規定：「污水管渠管材為塑化類管者，應為橘紅色，其他管材應有橘紅色之顯著標示。……」合先敘明。\n復參照本部國土管理署（前營建署）93年9月23日營署工程字第0930060230號函釋略以，建築物內之給排水設備屬建築物範疇，由建築師依據建築技術規則設計，為便於公共下水道之接管作業，應將雨、污水分流設置。建築物外，連接下水道之下水道管材、陰井、人孔及銜接建築物之污水管線之用戶排水設備，均屬下水道範疇。\n是以，下水道用戶排水設備標準第2條第2款所稱「污水管渠」，應為建築物外，連接下水道之下水道管材、陰井、人孔及銜接建築物之污水管線，而建築物內之污水管線則屬建築物給排水設備範疇。\n所詢管線如確係設置於建築物內部，並屬建築物給排水設備範疇，其管材顏色尚非「下水道用戶排水設備標準」第32條規範範圍。至該管材之材質及其他相關規定，仍應依建築技術規則、建築物給水排水設備設計技術規範、核定圖說及其他相關規定辦理。"},{"id":"r255","agency":"內政部","date":"115.8.24","docNo":"內授國水建字第1150810624號","y":115,"src":"115年更新","brief":"下水道法第9條關於指定下水道機構是否具有前置條件疑義","refs":["A8"],"text":"有關貴局函詢下水道法第9條關於指定下水道機構是否具有前置條件疑義，復如說明，請查照。\n依據本部國土管理署案陳貴局115年7月28日桃水污設字第1150052767號函辦理。\n按下水道法第8條第2項規定，私人新開發社區、工業區或經直轄市、縣（市）主管機關指定之地區或場所，應設置專用下水道；另查本部96年8月20日營署工程字第0960045137號函，「自辦市地重劃，市地重劃地區按平均地權條例規定之程序辦理，重劃完成後，該地區設置專用下水道之原則，以個案考量，若達下水道法第8條及該法施行細則之規模者，需依規定設置專用下水道。」合先敘明。\n復依下水道法第9條規定，中央、直轄市及縣（市）主管機關應指定下水道機構，惟查下水道相關法規尚無規定其前置條件，得視地方主管機關基於地域需求，自行於自治條例或法規命令中補充；惟考量指定下水道機構涉主管權限之移轉，地方主管機關應依行政程序法第16條之規定，將指定事項（如其辦理事項、權限範圍或法令依據等）登載於地方政府公報，始為合法，且貴局仍須負監督之責；惟涉及公權力部分（如罰責、法令解釋等），仍應由貴局辦理。"},{"id":"r256","agency":"內政部","date":"114.9.19","docNo":"內授國水建字第1140812612號","y":114,"src":"115年更新","brief":"起造新竹市香山區香中段66地號等6筆工廠新建工程案，其專用污水下水道系統得否採行預鑄式建築物污水處理設施1案","refs":["A8"],"text":"有關貴公司起造新竹市香山區香中段66地號等6筆工廠新建工程案，其專用污水下水道系統得否採行預鑄式建築物污水處理設施1案，復如說明，請查照。\n依據本部國土管理署案陳貴公司114年9月2日盛虹竹污字第114090201號函辦理。\n按下水道法第8條第2項規定：「私人新開發社區、工業區或經直轄市、縣（市）主管機關指定之地區或場所，應設置專用下水道。……」次按同法施行細則第4條第1項規定：「本法第8條所稱新開發社區、工業區，係指符合下列條件之地區，其申請開發時經主管機關認定其開發完成時公共下水道尚無法容納其廢污水者：一、新開發社區：可容納500人以上居住或總計興建100住戶以上之社區。二、新開發工業區：（一）政府機關、公民營事業機構開發供事業設廠之地區。（二）事業於政府依法劃設供工業使用之土地設廠，其基地面積達2公頃以上者。」經查本案開發土地為乙種工業區，基地面積已達2公頃以上，符合下水道法第8條第2項及同法施行細則第4條第1項第2款第2目之規定，應設置專用下水道，合先敘明。\n復依來函說明二所述，「……，爰專用污水下水道系統規劃A棟、B~G棟、H~I棟等3區分別收集處理，……」，貴公司基於新開發工業區整體開發需求，統籌規劃該開發區範圍之專用下水道系統，分3區收集其廢污水，並設置3處污水處理廠（設施），於法尚無違誤。惟無論採用現場構築式污水處理設施或預鑄式建築物污水處理設施，其性質仍屬於工業區專用污水下水道系統，其放流水水質應符合水污染防治法及放流水標準相關規定，併予說明。\n另本案 B~G棟與H~I棟間受農田水利署轄管汀圳幹線14支線穿越，若後續本案之專用下水道排放放流水於此既有排水路，建請確認農田水利法之相關搭排申請規定，以符合其相關排水之水質基準。"},{"id":"r257","agency":"內政部","date":"115.7.27","docNo":"內授國水建字第1150808520號","y":115,"src":"115年更新","brief":"辦理「臺南市南區灣裡產業專用區市地重劃工程」，涉及都市計畫「產業專用區」是否屬下水道法第8條所稱「新開發工業區」等疑義1案","refs":["A8"],"text":"有關貴府辦理「臺南市南區灣裡產業專用區市地重劃工程」，涉及都市計畫「產業專用區」是否屬下水道法第8條所稱「新開發工業區」等疑義1案，復如說明，請查照。\n依據本部國土管理署案陳貴府115年6月9日府經區字第1150870609號函辦理。\n依下水道法（下稱本法）第8條第1項及其施行細則第4條第1項第2款規定，政府機關或公營事業機構新開發工業區，於申請開發時經主管機關認定開發完成後公共污水下水道尚無法容納其廢污水者（前述「無法容納」之認定應併同考量排放水量及水質），應設置專用下水道，由開發機關（構）負責建設及管理。\n次查本部87年12月9日台內營字第8773453號函釋略以，本法施行細則第4條第1項第2款所稱「供事業設廠之地區」，係指政府機關或公民營事業機構以整體開發方式開發之工業區，並無開發規模限制。又本法第8條所稱「各該開發之機關或機構」，原則以都市計畫、重劃計畫書或開發計畫等文件所載開發主體認定，並參酌實際負責整體開發、公共設施建設及經費籌措之機關或機構綜合判斷。\n綜上，旨案如係由貴府因應產業發展需求，辦理市地重劃整體開發，並負責整體規劃、工程建設及開發經費籌措等事宜，且符合前開規定者，方得認屬下水道法第8條所稱新開發工業區及開發機關。\n另考量政府機關、公民營事業機構採整體開發供事業設廠之區域型態日益多元，其名稱未必均以「工業區」命名，爰本法「新開發工業區」之認定，不宜僅以開發地區名稱或都市計畫土地使用分區名稱為斷，仍應就其開發目的、土地使用內容、開發方式、進駐對象及廢污水收集處理需求等實質情形綜合判斷，如符合本法第8條及其施行細則第4條所定要件，仍屬「新開發工業區」，應依法設置專用下水道，併予說明。"},{"id":"r258","agency":"內政部","date":"114.7.3","docNo":"內授國水建字第1140808737號","y":114,"src":"115年更新","brief":"於鳳山區林森路329巷口施作污水下水道推進立坑工程，因工程必要需經私人土地（高雄市鳳山區七老爺段一甲小段1254-0049地號），是否適用下水道法第14條…","refs":["A14"],"text":"有關貴局於鳳山區林森路329巷口施作污水下水道推進立坑工程，因工程必要需經私人土地（高雄市鳳山區七老爺段一甲小段1254-0049地號），是否適用下水道法第14條規定1案，復如說明，請查照。\n復貴府114年6月27日高市府水污二字第11435617500號函。\n按下水道法第 14 條第 1 項規定「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金⋯⋯」同法施行細則第 7 條第 1 項規定「依本法第十四條規定使用公、私有土地時，下水道機構應於工程計畫訂定後，以書面通知土地所有人、占有人或使用人。」\n依上開規定意旨，公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設供「公共使用」之管渠或其他設備，惟下水道機關應擇其損害最少之處所及方法並支付償金。\n旨揭工程之污水工作井及污水下水道分支管是否適用下水道法第 14 條規定1事，請貴府本諸權責自行認定是否符上開規定。如是，始有下水道法第 14 條第 1 項之適用。"},{"id":"r259","agency":"內政部","date":"114.7.10","docNo":"內授國水建字第1140809104號","y":114,"src":"115年更新","brief":"為「新竹縣竹北市污水下水道系統第二期實施計畫污水管線系統工程-分支管線及用户接管工程」土地所有權人不同意下水道工程使用土地支付償金或補償費案，報請本部核定…","refs":["A14"],"text":"有關貴府為「新竹縣竹北市污水下水道系統第二期實施計畫污水管線系統工程-分支管線及用户接管工程」土地所有權人不同意下水道工程使用土地支付償金或補償費案，報請本部核定1案，復如說明，請查照。\n依據本部國土管理署案陳貴府114年6月20日府工水字第1143635201號函辦理。\n按下水道法第14條第1項規定：「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。」依前開意旨，公、私有土地所有人、占有人或使用人不得拒絕下水道機構在其土地下埋設供「公共使用」之管渠或其他設備，惟下水道機關應擇其損害最少之處所及方法並支付償金；如對處所及方法之選擇或支付償金有異議時，始有必要報請中央主管機關核定後為之。\n次按大法官釋字第440號解釋理由書略以：「關於都市計畫保留地得予以徵收或購買已有相關法律可資使用，主管機關基於增進公共利益之必要，依法使用都市計畫道路用地時，應否予以徵購，須考量其侵害之嚴重性，是否妨礙其原來之使用及安全等因素而為決定。對既成道路或都市計畫用地，主管機關在依據法律辦理徵購前，固得依法加以使用，如埋設電力、自來水管線及下水道設施物，惟應依比例原則擇其損失最少之處所及方法為之；對土地權利人因此所受損失，應給與相當之補償，以保護其財產上之利益。……」依前揭解釋理由書意旨，主管機關在依據法律辦理徵購前，主管機關仍得依法加以使用，惟若有埋設電力、自來水管線及下水道設施物之行為，應給與相當之補償。\n旨案土地所施作之污水下水道管渠，請貴府依上開意旨本諸權責先行釐清是否屬公共使用之污水管渠，另若亦屬既成道路之一部份，請併同參據大法官釋字第440號解釋辦理。\n末查本案土地所有權人等之異議為拆除公共污水設施或採土地徵收方式辦理，非對處所及方法之選擇或支付償金有異議，尚非本部核定範疇。"},{"id":"r260","agency":"內政部","date":"114.12.3","docNo":"內授國水建字第1140816171號","y":114,"src":"115年更新","brief":"「用戶排水設備是否有下水道法第14條」之適用疑義","refs":["A14"],"text":"有關貴局函詢「用戶排水設備是否有下水道法第14條」之適用疑義，復如說明，請查照。\n復貴局114年11月18日新北水污計字第1142332044號函。\n按下水道法第2條第6款規定「用戶排水設備：指下水道用戶因接用下水道以排洩下水所設之管渠及有關設備。」同法第20條規定「用戶排水設備之管理、維護，由下水道用戶自行負責。」依前開立法旨意，用戶排水設備係用戶為接用下水道所設置之設備，其物權屬用戶私有，應由用戶自行負責建設、管理。\n次按下水道法第14條第1項規定「下水道機構因工程上之必要，得在公、私有土地下埋設管渠或其他設備，其土地所有人、占有人或使用人不得拒絕。但應擇其損害最少之處所及方法為之，並應支付償金。如對處所及方法之選擇或支付償金有異議時，應報請中央主管機關核定後為之。」查其立法原意，係指下水道機構在公、私有土地下埋設供「公共使用」之管渠或其他設備，致部分公、私有土地受影響，為保障受影響者權益，故予以支付償金，以為補償，並應選擇其損害最少處所及方法為之。如土地所有人、占有人或使用人就對施工處所、方法之選擇或支付償金額度提出異議時，應由地方主管機關檢附相關佐證資料，報請中央主管機關核定後，始得為之。\n本案「用戶接管工程」雖由政府機關代為施工，並以公務預算支應，核與下水道法第14條第1項性質迥異，自無「償金支付」、「擇其損害最少處所及方法」與「報請中央主管機關核定」等規定之適用。"},{"id":"r261","agency":"內政部","date":"114.8.29","docNo":"內授國水建字第1140811522號","y":114,"src":"115年更新","brief":"公共污水下水道系統修繕","refs":["A16"],"text":"有關貴局函詢「公共污水下水道系統修繕」1案，復如說明，請查照。\n依據本部國土管理署案陳貴局114年8月6日桃水污設字第1140061915號函辦理。\n依下水道法第 16 條規定：「下水道機構因勘查、測量、施工或維護下水道，臨時使用公、私土地時，土地所有人、占有人或使用人不得拒絕。但提供使用之土地因而遭受損害時，應予補償。如對補償有異議時，應報請中央主管機關核定後為之。」\n次依下水道法施行細則第8條規定：「依本法第十六條規定臨時使用公、私有土地時，下水道機構應以書面通知土地所有人、占有人或使用人，如情況急迫，得先行施工，補行通知。」同法第10條規定：「本法第十四條、第十六條規定支付之償金或補償，其標準由直轄市、縣（市）主管機關訂定之。」\n有關下水道機構進入私有土地辦理維護作業時，是否仍須另行取得土地所有人之書面同意，依下水道法第 16 條，規範土地所有人、占有人或使用人不得拒絕臨時使用，因此下水道機構進入私有土地辦理維護作業時，並非以事前取得土地使用權同意書為同意使用之成立要件，有無簽署土地使用權同意書，並不影響下水道機構依法臨時使用公、私土地時之合法性。\n有關下水道機構執行作業前應完成之通知程序或其他替代方式及是否須給付土地所有人補償，請貴局依前開規定本權責妥處。"},{"id":"r262","agency":"內政部國土管理署","date":"114.7.23","docNo":"國署水建字第1140078497號","y":114,"src":"115年更新","brief":"「都市計畫公共設施用地多目標使用辦法」附表乙對於公園用地平面多目標使用規定，涉及下水道系統相關設施所需之機電及附屬設施相關定義1案","refs":["L2:2"],"text":"貴局函詢有關「都市計畫公共設施用地多目標使用辦法」附表乙對於公園用地平面多目標使用規定，涉及下水道系統相關設施所需之機電及附屬設施相關定義1案，復如說明，請查照。\n復貴局114年7月14日新北水污計字第1141365077號函。\n按「都市計畫公共設施用地多目標使用辦法」第3條附表乙平面多目標使用－公園用地准許條件第4點規定，「自來水、再生水、下水道系統相關設施所需之機電及附屬設施用地面積應在700平方公尺以下，並應有完善之安全設備。」\n次按下水道工程設施標準第2條第1項第1款規定，「下水道工程設施：管渠、抽水站、污水處理廠及其相關設施」，爰「都市計畫公共設施用地多目標使用辦法」所稱「下水道系統相關設施」應為下水道工程設施標準所規範之相關設施。至其所需之機電及附屬設施，除機械與電氣設備本體外，尚包括為使該等設備能穩定且安全運作所必須之結構體，以及相關之安全與監測附屬設施。\n貴局所詢請依上開原則自行認定。"},{"id":"r263","agency":"內政部","date":"115.7.9","docNo":"內授國水建字第1150808551號","y":115,"src":"115年更新","brief":"「下水道作業上下設備及相關職安衛設施示意圖說」下水道塑膠包覆人孔踏步詳圖是否適用職業安全衛生設施規則第37條第1項第3款規定一案","refs":["L2:8"],"text":"有關貴處函詢「下水道作業上下設備及相關職安衛設施示意圖說」下水道塑膠包覆人孔踏步詳圖是否適用職業安全衛生設施規則第37條第1項第3款規定一案，復如說明，請查照。\n依據勞動部職業安全衛生署115年5月26日勞職安1字第1150112317號函及本部國土管理署案陳貴處115年4月30日北市工水下字第1156028625號函辦理。\n依勞動部職業安全衛生署115年5月26日函（如附件）說明二：「按職業安全衛生法（下稱職安法）第1條後段之規定：『…；其他法律有特別規定者，從其規定。』，已明確定義職安法係普通法，而其他法律規定係特別法。爰貴管法規如針對下水道人孔入口內徑及固定式上下設備等設施之標準已有特別規定，應優先適用」。\n查下水道工程設施標準第8條及第29條明定人孔應設置符合國家標準之人孔踏步，又查國家標準CNS13206規定，踏步突出牆面部分最小應為12公分，且如有特殊考量 「突出牆面部分得依人孔斷面之變化酌量增加其長度」；爰本部國土管理署依前開規定並考量人孔內部空間侷限性，及下水道從業人員之作業安全，規劃工作者上下進出、機具吊掛及緊急事故救援所需空間，另參考職業安全衛生相關法規、施工規範及CNS13206國家標準等規定，訂定「下水道作業上下設備及相關職業安全衛生設施示意圖說」，作為行政指導提供各下水道工程主辦機關參考使用，以兼顧下水道人孔之功能性及救災安全性考量。"},{"id":"r264","agency":"內政部國土管理署","date":"114.12.19","docNo":"國署水建字第1141246643號","y":114,"src":"115年更新","brief":"民眾反映「有關因下水道用戶排水設備標準規定導致雙重存水彎之疑慮」1案","refs":["L1:2"],"text":"有關民眾反映「有關因下水道用戶排水設備標準規定導致雙重存水彎之疑慮」1案，詳如說明，請查照。\n依據本署114年12月16日署長信箱郵件辦理。\n按下水道用戶排水設備標準第2條第14款規定「存水彎：指藉水封之功能，供排水、防止污水產生之廢氣及病媒等自排水管或污水下水道侵入屋內之管件或裝置。」第31條第1項規定「匯流管進入連接管前應設置存水彎，設置規定如下：一、存水彎型式應具有防止臭味迴流及易於維護之功能。二、存水彎之設置不得影響污水排放容量，其管內徑亦不得低於上游管徑。」同條第2項規定「建築物已設置存水彎者，不適用前項規定。」合先敘明。\n查其規範意旨，存水彎之設置目的係用以防止家庭排水系統及家庭污水管之間臭味及病媒之散布，故規範匯流管進入連接管前應設置存水彎，並應同時兼顧污水排放之順暢性與設備後續維護管理，確保公共衛生、使用安全及排水系統整體運作之穩定性。\n次查本署111年12月29日修正發布之「建築物給水排水設備設計技術規範」第4.4.4點、第4.4.7點及第4.4.8點已有詳細規範建築物排水設備之存水彎設計規定，並有規範「當採個別存水彎時，若器具本身已有存水彎（如:洗臉盆），該排水管不得再設置存水彎，避免雙重存水彎造成排水不順暢及無法維護管理。」\n考量雙重存水彎存在時，倘二者間無足夠高差以產生驅動一定流速之水流，克服下游存水彎所造成之水頭損失，確實容易導致阻滯現象，且依下水道用戶排水設備標準第31條第2項之立法原意，如該建築物之衛生器具本身已附存水彎或已採集合式總存水彎者，即無需再另外設置存水彎，請貴單位辦理相關用戶接管工程設計或施作時，應審視建築整體狀況，依前開規定辦理。"},{"id":"r265","agency":"內政部","date":"115.7.1","docNo":"內授國水建字第1150807484號","y":115,"src":"115年更新","brief":"「污水處理廠（水資源回收中心）用地及其毗鄰區域」屬「公有山坡地放領辦法」、「國有耕地放領實施辦法」及「國有邊際養殖用地放領實施辦法」第3條1項第3款規定不予放…","refs":["other"],"text":"有關「污水處理廠（水資源回收中心）用地及其毗鄰區域」屬「公有山坡地放領辦法」、「國有耕地放領實施辦法」及「國有邊際養殖用地放領實施辦法」第3條1項第3款規定不予放領情形，其認定及處理原則，請依說明辦理，請查照。\n依據「公有山坡地放領辦法」第3條第1項第3款、「國有耕地放領實施辦法」第3條第1項第3款及「國有邊際養殖用地放領實施辦法」第3條第1項第3款規定辦理。\n考量污水處理廠（水資源回收中心）屬國家重要公共建設，其用地及周邊土地具有未來推動建設需求，應認屬上開放領辦法第3條第1項第3款所定「政府計畫供公共建設使用」而不予放領之土地。為利執行相關放領案件有所依循，相關認定及處理原則如下：\n土地位於現有、興建中或初、複勘通過之污水處理廠（水資源回收中心）用地及其用地毗鄰區域水平距離100公尺範圍內者，應認屬上開規定所稱「政府計畫供公共建設使用」之土地，不予放領。\n上開土地範圍之認定及查註作業，由直轄市、縣（市）政府辦理。\n本函分行前已受理而尚未完成審查或核定之放領案件，亦應依本函所定認定原則辦理查註。"}];
